    // ============ Internal Functions ============

    function _recordTransactionPattern(
        address account,
        uint256 amount,
        uint8 transactionType,
        address counterparty
    ) internal {
        TransactionPattern memory pattern = TransactionPattern({
            timestamp: block.timestamp,
            amount: amount,
            transactionType: transactionType,
            counterparty: counterparty,
            priceImpact: _estimatePriceImpact(amount),
            riskScore: 0 // Will be set later
        });

        TransactionPattern[] storage history = accountTransactionHistory[account];
        history.push(pattern);

        // Keep only recent history for gas efficiency
        if (history.length > PATTERN_HISTORY_LENGTH) {
            // Remove oldest transaction
            for (uint256 i = 0; i < history.length - 1; i++) {
                history[i] = history[i + 1];
            }
            history.pop();
        }

        // Update pair transaction count
        if (counterparty != address(0)) {
            pairTransactionCounts[account][counterparty]++;
        }
    }

    function _calculateFrequencyRisk(address account) internal view returns (uint256) {
        TransactionPattern[] memory history = accountTransactionHistory[account];
        if (history.length == 0) return 0;

        uint256 recentTransactions = 0;
        uint256 currentTime = block.timestamp;

        // Count transactions in last hour
        for (uint256 i = 0; i < history.length; i++) {
            if (currentTime > history[i].timestamp && currentTime - history[i].timestamp <= 1 hours) {
                recentTransactions++;
            }
        }

        // Also count rapid transactions (less than 5 minutes apart or same timestamp)
        uint256 rapidTransactions = 0;
        if (history.length >= 2) {
            for (uint256 i = 1; i < history.length; i++) {
                // Same timestamp counts as rapid trading
                if (history[i].timestamp == history[i-1].timestamp) {
                    rapidTransactions++;
                } else if (history[i].timestamp > history[i-1].timestamp && 
                           history[i].timestamp - history[i-1].timestamp <= 300) { // 5 minutes
                    rapidTransactions++;
                }
            }
        }

        // Enhanced risk calculation - more aggressive detection
        uint256 frequencyRisk = 0;
        if (recentTransactions >= 5) frequencyRisk = 800;      // Very high risk (lowered threshold)
        else if (recentTransactions >= 3) frequencyRisk = 600; // High risk  
        else if (recentTransactions >= 2) frequencyRisk = 400; // Medium risk
        else if (recentTransactions >= 1) frequencyRisk = 200; // Low risk (added single tx risk)

        // Stronger rapid trading penalties
        uint256 rapidTradingPenalty = rapidTransactions * 300; // 300 risk points per rapid trade (tripled)

        uint256 totalRisk = frequencyRisk + rapidTradingPenalty;
        return totalRisk > MAX_RISK_SCORE ? MAX_RISK_SCORE : totalRisk;
    }

    function _calculateVolumeRisk(address account, uint256 currentAmount) internal view returns (uint256) {
        TransactionPattern[] memory history = accountTransactionHistory[account];

        // For accounts with no history, check if current amount is suspiciously large
        if (history.length == 0) {
            if (currentAmount >= 10000 * PRECISION) return 800; // Very large initial transaction
            if (currentAmount >= 5000 * PRECISION) return 400;  // Large initial transaction
            return 0;
        }

        uint256 totalVolume = 0;
        uint256 currentTime = block.timestamp;
        uint256 validTransactions = 0;

        // Calculate volume in last 24 hours
        for (uint256 i = 0; i < history.length; i++) {
            if (currentTime > history[i].timestamp && currentTime - history[i].timestamp <= 24 hours) {
                totalVolume += history[i].amount;
                validTransactions++;
            }
        }

        // If no recent transactions, use all history for average
        if (validTransactions == 0) {
            for (uint256 i = 0; i < history.length; i++) {
                totalVolume += history[i].amount;
                validTransactions++;
            }
        }

        if (validTransactions == 0) {
            // Fallback: check absolute volume thresholds
            if (currentAmount >= 50000 * PRECISION) return 900;
            if (currentAmount >= 10000 * PRECISION) return 700;
            if (currentAmount >= 5000 * PRECISION) return 400;
            return 0;
        }

        uint256 averageVolume = totalVolume / validTransactions;

        // Ensure we don't divide by zero
        if (averageVolume == 0) {
            averageVolume = 1 * PRECISION; // 1 token minimum average
        }

        // Enhanced volume concentration detection - more sensitive
        if (currentAmount > averageVolume * 5) return 900;    // Very high concentration (lowered from 10x)
        if (currentAmount > averageVolume * 3) return 700;    // High concentration (lowered from 5x)
        if (currentAmount > averageVolume * 2) return 500;    // Medium concentration (increased penalty)
        if (currentAmount > averageVolume) return 300;        // Above average (new threshold)
        return 0;                                              // Normal volume
    }

    function _calculatePatternRisk(address account) internal view returns (uint256) {
        TransactionPattern[] memory history = accountTransactionHistory[account];
        if (history.length < 5) return 0; // Need minimum history for pattern detection

        // Look for suspicious patterns
        uint256 patternRisk = 0;

        // Check for alternating buy/sell patterns (potential wash trading)
        uint256 alternatingCount = 0;
        for (uint256 i = 1; i < history.length; i++) {
            if (history[i].transactionType != history[i-1].transactionType) {
                alternatingCount++;
            }
        }

        uint256 alternatingRatio = (alternatingCount * 100) / (history.length - 1);
        if (alternatingRatio > 60) {
            patternRisk += 600; // High alternating pattern risk (lowered threshold, increased penalty)
        } else if (alternatingRatio > 40) {
            patternRisk += 300; // Medium alternating pattern risk (new tier)
        }

        // Check for same counterparty concentration
        if (history.length >= 3) {
            address mostFrequentCounterparty = address(0);
            uint256 maxCount = 0;

            for (uint256 i = 0; i < history.length; i++) {
                if (history[i].counterparty == address(0)) continue;

                uint256 count = 0;
                for (uint256 j = 0; j < history.length; j++) {
                    if (history[j].counterparty == history[i].counterparty) {
                        count++;
                    }
                }

                if (count > maxCount) {
                    maxCount = count;
                    mostFrequentCounterparty = history[i].counterparty;
                }
            }

            uint256 concentrationRatio = (maxCount * 100) / history.length;
            if (concentrationRatio > 50) {
                patternRisk += 500; // High counterparty concentration (lowered threshold, increased penalty)
            } else if (concentrationRatio > 30) {
                patternRisk += 250; // Medium counterparty concentration (new tier)
            }
        }

        return patternRisk > 1000 ? 1000 : patternRisk;
    }

    function _calculateMarketImpactRisk(address account, uint256 amount) internal view returns (uint256) {
        // Estimate price impact and assess risk
        uint256 priceImpact = _estimatePriceImpact(amount);

        if (priceImpact > manipulationConfig.priceManipulationThreshold) {
            return 800; // High market impact risk
        } else if (priceImpact > manipulationConfig.priceManipulationThreshold / 2) {
            return 400; // Medium market impact risk
        }

        return 0; // Low market impact risk
    }

    function _calculateSocialGraphRisk(address account, address counterparty) internal view returns (uint256) {
        if (counterparty == address(0)) return 0;

        // Check if counterparty is flagged
        if (flaggedAccounts[counterparty]) {
            return 300;
        }

        // Check transaction frequency with this counterparty
        uint256 pairCount = pairTransactionCounts[account][counterparty];
        if (pairCount > 10) return 200;
        if (pairCount > 5) return 100;

        return 0;
    }

    function _calculateBehavioralRisk(address account) internal view returns (uint256) {
        AccountRiskProfile memory profile = accountRiskProfiles[account];

        // Factor in historical behavior
        if (profile.consecutiveHighRiskTxCount > 5) return 600;
        if (profile.consecutiveHighRiskTxCount > 3) return 300;
        if (profile.flagCount > 3) return 200;

        return 0;
    }

    function _calculateTemporalRisk(address account) internal view returns (uint256) {
        TransactionPattern[] memory history = accountTransactionHistory[account];
        if (history.length < 3) return 0;

        // Look for unusual timing patterns
        uint256 intervals = 0;
        uint256 totalInterval = 0;

        for (uint256 i = 1; i < history.length; i++) {
            uint256 interval = history[i].timestamp - history[i-1].timestamp;
            totalInterval += interval;
            intervals++;
        }

        if (intervals == 0) return 0;

        uint256 averageInterval = totalInterval / intervals;

        // Check for too-regular intervals (possible bot behavior)
        uint256 regularityCount = 0;
        for (uint256 i = 1; i < history.length; i++) {
            uint256 interval = history[i].timestamp - history[i-1].timestamp;
            uint256 deviation = interval > averageInterval ? 
                interval - averageInterval : averageInterval - interval;

            if (deviation < averageInterval / 10) { // Within 10% of average
                regularityCount++;
            }
        }

        uint256 regularityRatio = (regularityCount * 100) / intervals;
        if (regularityRatio > 80) return 400; // Very regular timing
        if (regularityRatio > 60) return 200; // Somewhat regular timing

        return 0;
    }

    function _applyMLModel(
        address account,
        uint256 amount,
        uint8 transactionType
    ) internal view returns (uint256) {
        // Extract features for ML model
        uint256[10] memory features;

        TransactionPattern[] memory history = accountTransactionHistory[account];
        AccountRiskProfile memory profile = accountRiskProfiles[account];

        features[0] = history.length; // Transaction count
        features[1] = profile.totalPenaltiesPaid; // Historical penalties
        features[2] = amount; // Current transaction amount
        features[3] = uint256(transactionType); // Transaction type
        features[4] = profile.flagCount; // Flag count
        features[5] = profile.consecutiveHighRiskTxCount; // Consecutive high risk
        features[6] = block.timestamp - profile.lastRiskUpdate; // Time since last risk update
        features[7] = pairTransactionCounts[account][address(0)]; // Self-transactions
        features[8] = _estimatePriceImpact(amount); // Price impact
        features[9] = socialGraphRisk[account]; // Social graph risk

        // Apply ML model (simplified linear model)
        uint256 weightedSum = 0;
        for (uint256 i = 0; i < 10; i++) {
            weightedSum += features[i] * mlModel.featureWeights[i];
        }

        // Normalize to 0-1000 scale
        uint256 modelOutput = (weightedSum / 1000) % 1001;

        return modelOutput > mlModel.modelThreshold ? modelOutput : 0;
    }

    function _calculateWeightedRiskScore(
        uint256 frequencyRisk,
        uint256 volumeRisk,
        uint256 patternRisk,
        uint256 marketImpactRisk,
        uint256 socialGraphRiskScore,
        uint256 behavioralRiskScore,
        uint256 temporalRiskScore,
        uint256 mlRisk
    ) internal view returns (uint256) {
        // Weighted combination of risk factors
        uint256 totalWeight = 100;
        uint256 weightedSum = frequencyRisk * 20 +      // 20% weight
                              volumeRisk * 18 +          // 18% weight
                              patternRisk * 15 +         // 15% weight
                              marketImpactRisk * 12 +    // 12% weight
                              socialGraphRiskScore * 10 + // 10% weight
                              behavioralRiskScore * 10 +  // 10% weight
                              temporalRiskScore * 8 +     // 8% weight
                              mlRisk * 7;                 // 7% weight

        uint256 combinedScore = weightedSum / totalWeight;
        return combinedScore > MAX_RISK_SCORE ? MAX_RISK_SCORE : combinedScore;
    }

    function _updateAccountRiskProfile(
        address account,
        uint256 riskScore,
        uint256 frequencyRisk,
        uint256 volumeRisk,
        uint256 patternRisk,
        uint256 marketImpactRisk
    ) internal {
        AccountRiskProfile storage profile = accountRiskProfiles[account];

        uint256 oldRiskScore = profile.overallRiskScore;

        profile.overallRiskScore = riskScore;
        profile.frequencyRisk = frequencyRisk;
        profile.volumeRisk = volumeRisk;
        profile.patternRisk = patternRisk;
        profile.marketImpactRisk = marketImpactRisk;
        profile.lastRiskUpdate = block.timestamp;

        // Update consecutive high risk transaction count
        if (riskScore >= HIGH_RISK_THRESHOLD) {
            profile.consecutiveHighRiskTxCount++;
        } else {
            profile.consecutiveHighRiskTxCount = 0;
        }

        emit RiskProfileUpdated(account, oldRiskScore, riskScore);
    }

    function _generateRiskFlags(address account, uint256 riskScore) internal view returns (string[] memory flags) {
        AccountRiskProfile memory profile = accountRiskProfiles[account];

        // Count potential flags
        uint256 flagCount = 0;
        if (riskScore >= HIGH_RISK_THRESHOLD) flagCount++;
        if (profile.frequencyRisk >= HIGH_RISK_THRESHOLD) flagCount++;
        if (profile.volumeRisk >= HIGH_RISK_THRESHOLD) flagCount++;
        if (profile.patternRisk >= HIGH_RISK_THRESHOLD) flagCount++;
        if (profile.marketImpactRisk >= HIGH_RISK_THRESHOLD) flagCount++;
        if (profile.consecutiveHighRiskTxCount >= 3) flagCount++;
        if (flaggedAccounts[account]) flagCount++;

        flags = new string[](flagCount);
        uint256 index = 0;

        if (riskScore >= HIGH_RISK_THRESHOLD) flags[index++] = "HIGH_OVERALL_RISK";
        if (profile.frequencyRisk >= HIGH_RISK_THRESHOLD) flags[index++] = "HIGH_FREQUENCY_RISK";
        if (profile.volumeRisk >= HIGH_RISK_THRESHOLD) flags[index++] = "HIGH_VOLUME_RISK";
        if (profile.patternRisk >= HIGH_RISK_THRESHOLD) flags[index++] = "SUSPICIOUS_PATTERN";
        if (profile.marketImpactRisk >= HIGH_RISK_THRESHOLD) flags[index++] = "HIGH_MARKET_IMPACT";
        if (profile.consecutiveHighRiskTxCount >= 3) flags[index++] = "CONSECUTIVE_HIGH_RISK";
        if (flaggedAccounts[account]) flags[index++] = "MANUALLY_FLAGGED";

        return flags;
    }

    function _calculateProgressivePenalty(
        address account,
        uint256 amount,
        uint256 riskScore
    ) internal view returns (uint256) {
        if (emergencyMode) {
            return 0; // No penalties in emergency mode
        }

        if (riskScore < 300) {
            return 0; // No penalty for low risk (lowered threshold from 500 to 300)
        }

        AccountRiskProfile memory profile = accountRiskProfiles[account];

        // Base penalty calculation
        uint256 basePenalty = (amount * config.basePenaltyRate) / BASIS_POINTS;

        // Progressive multiplier based on risk score
        uint256 riskMultiplier = 100; // 1.0x base
        if (riskScore >= HIGH_RISK_THRESHOLD) {
            riskMultiplier = config.progressivePenaltyMultiplier * 2; // 3x for high risk
        } else {
            riskMultiplier = config.progressivePenaltyMultiplier; // 1.5x for medium risk
        }

        // Additional multiplier for repeat offenders
        uint256 repeatOffenderMultiplier = 100 + (profile.flagCount * 25); // +25% per flag

        // Calculate final penalty
        uint256 finalPenalty = (basePenalty * riskMultiplier * repeatOffenderMultiplier) / (100 * 100);

        // Cap penalty at maximum rate
        uint256 maxPenalty = (amount * MAX_PENALTY_RATE) / BASIS_POINTS;
        return finalPenalty > maxPenalty ? maxPenalty : finalPenalty;
    }

    function _calculateMaximumPenalty(uint256 amount) internal view returns (uint256) {
        return (amount * MAX_PENALTY_RATE) / BASIS_POINTS;
    }

    function _detectMarketManipulation(
        address account,
        uint256 amount,
        uint8 transactionType,
        address counterparty
    ) internal {
        // Check for wash trading
        if (_detectWashTrading(account, counterparty)) {
            marketManipulationDetections++;
            emit MarketManipulationDetected(account, "WASH_TRADING");
        }

        // Check for front running
        if (_detectFrontRunning(account, amount)) {
            marketManipulationDetections++;
            emit MarketManipulationDetected(account, "FRONT_RUNNING");
        }

        // Check for pump and dump
        if (_detectPumpAndDump(account, amount, transactionType)) {
            marketManipulationDetections++;
            emit MarketManipulationDetected(account, "PUMP_AND_DUMP");
        }
    }

    function _detectWashTrading(address account, address counterparty) internal view returns (bool) {
        if (counterparty == address(0)) return false;

        // Check reciprocal trading patterns
        uint256 aToB = pairTransactionCounts[account][counterparty];
        uint256 bToA = pairTransactionCounts[counterparty][account];

        // Require minimum transaction count for wash trading detection
        if (aToB >= 2 && bToA >= 2) {
            uint256 minTrades = aToB < bToA ? aToB : bToA;
            uint256 maxTrades = aToB > bToA ? aToB : bToA;

            // If trades are too similar in count, it's suspicious
            uint256 ratio = (minTrades * 100) / maxTrades;
            if (ratio >= 60) { // Within 40% of each other
                return true;
            }
        }

        // Also check recent transaction patterns
        TransactionPattern[] memory history = accountTransactionHistory[account];
        if (history.length >= 4) {
            uint256 backAndForthCount = 0;
            for (uint256 i = 1; i < history.length; i++) {
                if (history[i].counterparty == counterparty && 
                    history[i-1].counterparty == counterparty &&
                    block.timestamp - history[i].timestamp <= 1 hours) {
                    backAndForthCount++;
                }
            }

            if (backAndForthCount >= 3) {
                return true; // Rapid back-and-forth trading
            }
        }

        return false;
    }

    function _detectFrontRunning(address account, uint256 amount) internal view returns (bool) {
        TransactionPattern[] memory history = accountTransactionHistory[account];
        if (history.length < 2) return false;

        // Look for large transactions followed quickly by opposite transactions
        uint256 lastTxIndex = history.length - 1;
        TransactionPattern memory lastTx = history[lastTxIndex];

        if (block.timestamp - lastTx.timestamp <= manipulationConfig.frontRunningWindow) {
            if (lastTx.amount > amount * 2 && lastTx.transactionType != uint8(block.timestamp % 3)) {
                return true;
            }
        }

        return false;
    }

    function _detectPumpAndDump(address account, uint256 amount, uint8 transactionType) internal view returns (bool) {
        TransactionPattern[] memory history = accountTransactionHistory[account];
        if (history.length < 5) return false;

        // Look for patterns of accumulation followed by large sells
        uint256 buyCount = 0;
        uint256 sellCount = 0;
        uint256 totalBuyVolume = 0;
        uint256 totalSellVolume = 0;

        uint256 currentTime = block.timestamp;
        for (uint256 i = 0; i < history.length; i++) {
            if (currentTime - history[i].timestamp <= 24 hours) {
                if (history[i].transactionType == 1) { // Buy
                    buyCount++;
                    totalBuyVolume += history[i].amount;
                } else if (history[i].transactionType == 2) { // Sell
                    sellCount++;
                    totalSellVolume += history[i].amount;
                }
            }
        }

        // Pattern: Many small buys followed by large sell
        if (buyCount >= 5 && sellCount <= 2 && transactionType == 2) {
            uint256 averageBuy = buyCount > 0 ? totalBuyVolume / buyCount : 0;
            return amount > averageBuy * 5; // Current sell > 5x average buy
        }

        return false;
    }

    function _activateCircuitBreaker(address account) internal {
        _activateCircuitBreaker(account, config.circuitBreakerCooldown);
    }

    function _activateCircuitBreaker(address account, uint256 duration) internal {
        AccountRiskProfile storage profile = accountRiskProfiles[account];
        profile.isCircuitBreakerActive = true;
        profile.circuitBreakerUntil = block.timestamp + duration;

        circuitBreakerActivations++;
        emit CircuitBreakerActivated(account, duration);
    }

    function _isInGracePeriod(address account) internal view returns (bool) {
        return whitelistedAccounts[account] && 
               block.timestamp < accountRiskProfiles[account].lastRiskUpdate + config.whitelistGracePeriod;
    }

    function _estimatePriceImpact(uint256 amount) internal pure returns (uint256) {
        // Simplified price impact estimation
        // In practice, this would integrate with AMM or order book
        if (amount > 100000 * PRECISION) return 500; // 5%
        if (amount > 50000 * PRECISION) return 300;  // 3%
        if (amount > 10000 * PRECISION) return 100;  // 1%
        return 50; // 0.5%
    }

    function _calculateTimingCorrelation(
        address account1,
        address account2,
        uint256 timeWindow
    ) internal view returns (uint256) {
        // Simplified timing correlation calculation
        // Would need more sophisticated implementation in practice
        return 0; // Placeholder
    }

    function _calculateVolumeCorrelation(
        address account1,
        address account2,
        uint256 timeWindow
    ) internal view returns (uint256) {
        // Simplified volume correlation calculation
        // Would need more sophisticated implementation in practice
        return 0; // Placeholder
    }

    function _getRiskReason(uint256 riskScore) internal pure returns (string memory) {
        if (riskScore >= 900) return "EXTREMELY_HIGH_RISK";
        if (riskScore >= HIGH_RISK_THRESHOLD) return "HIGH_RISK_TRANSACTION";
        if (riskScore >= MEDIUM_RISK_THRESHOLD) return "MEDIUM_RISK_TRANSACTION";
        return "LOW_RISK_TRANSACTION";
    }

    /**
     * @dev Get account flags for external inspection
     * @param account Account to check flags for
     * @return flags Array of flag strings set for the account
     */
    function getAccountFlags(address account) external view returns (string[] memory flags) {
        AccountRiskProfile memory profile = accountRiskProfiles[account];

        // Count active flags first
        uint256 activeFlags = 0;

        if (profile.overallRiskScore >= HIGH_RISK_THRESHOLD) activeFlags++;
        if (profile.flagCount > 5) activeFlags++;
        if (profile.isCircuitBreakerActive) activeFlags++;
        if (profile.consecutiveHighRiskTxCount >= 3) activeFlags++;

        // Create array with correct size
        string[] memory flagsArray = new string[](activeFlags);
        uint256 index = 0;

        // Add flags
        if (profile.overallRiskScore >= HIGH_RISK_THRESHOLD) {
            flagsArray[index++] = "HIGH_RISK";
        }

        if (profile.flagCount > 5) {
            flagsArray[index++] = "FREQUENT_TRADER";
        }

        if (profile.isCircuitBreakerActive) {
            flagsArray[index++] = "CIRCUIT_BREAKER";
        }

        if (profile.consecutiveHighRiskTxCount >= 3) {
            flagsArray[index++] = "WASH_TRADING";
        }

        return flagsArray;
    }

    /**
     * @dev Add emergency operator
     */
    function addEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = true;
    }

    /**
     * @dev Remove emergency operator
     */
    function removeEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = false;
    }

    /**
     * @dev Pause contract operations
     */
    function pause() external {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");
        _pause();
    }

    /**
     * @dev Unpause contract operations
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/core/AdvancedDemurrageManager..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "../libs/AdvancedMathUtils.sol";
import "../interfaces/ICaesar.sol";
import "../interfaces/IEconomicEngine.sol";

/**
 * @title AdvancedDemurrageManager
 * @dev Advanced demurrage system with mathematical precision, stability-based adjustments,
 * fiat activity discounts, and grace periods for Caesar Token economic model
 */
contract AdvancedDemurrageManager is Ownable, ReentrancyGuard, Pausable {
    using AdvancedMathUtils for uint256;

    // ============ Constants ============
    uint256 public constant PRECISION = 1e18;
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant SECONDS_PER_HOUR = 3600;
    uint256 public constant MIN_DEMURRAGE_RATE = 5;   // 0.05% per hour minimum
    uint256 public constant MAX_DEMURRAGE_RATE = 200; // 2% per hour maximum
    uint256 public constant MAX_FIAT_DISCOUNT = 5000; // 50% maximum discount
    uint256 public constant MAX_GRACE_PERIOD = 168 hours; // 7 days maximum

    // ============ Structs ============

    struct AdvancedDemurrageConfig {
        uint256 baseRate;                // Base demurrage rate (basis points per hour)
        uint256 maxRate;                 // Maximum demurrage rate (basis points per hour)
        uint256 stabilityThreshold;      // Price stability threshold (basis points)
        uint256 fiatDiscountFactor;      // Maximum fiat activity discount (basis points)
        uint256 gracePeriodsHours;       // Grace period for new users (hours)
        uint256 decayAcceleration;       // Rate at which demurrage accelerates
        uint256 velocityThreshold;       // Money velocity threshold for adjustments
        bool adaptiveRateEnabled;        // Whether adaptive rate adjustment is enabled
    }

    struct AccountDemurrageData {
        uint256 lastDemurrageApplication;    // Last demurrage application timestamp
        uint256 totalDemurragePaid;          // Cumulative demurrage paid
        uint256 effectiveRate;               // Current effective demurrage rate
        uint256 graceEndTime;                // When grace period ends (0 if not applicable)
        uint256 lastFiatActivity;            // Last fiat activity timestamp
        uint256 fiatVolume30Days;            // Fiat activity volume in last 30 days
        bool isExempt;                       // Whether account is exempt
        bool isNewUser;                      // Whether account is in grace period
    }

    struct StabilityMetrics {
        uint256 currentStabilityIndex;       // Current stability index (0-1000)
        uint256 priceDeviation;              // Price deviation from target (basis points)
        uint256 velocityRatio;               // Money velocity ratio
        uint256 participationRate;           // Network participation rate
        uint256 lastStabilityUpdate;        // Last stability metrics update
    }

    struct FiatActivityDiscount {
        uint256 volume24h;                   // Fiat volume in last 24 hours
        uint256 volume7d;                    // Fiat volume in last 7 days
        uint256 volume30d;                   // Fiat volume in last 30 days
        uint256 discountPercentage;          // Current discount percentage
        bool isEligible;                     // Whether eligible for discount
        uint256 lastActivityTime;            // Last fiat activity timestamp
    }

    // ============ State Variables ============

    AdvancedDemurrageConfig public config;
    StabilityMetrics public stabilityMetrics;

    // Account tracking
    mapping(address => AccountDemurrageData) public accountData;
    mapping(address => FiatActivityDiscount) public fiatDiscounts;
    mapping(address => bool) public exemptAccounts;

    // Global metrics
    uint256 public totalDemurrageCollected;
    uint256 public totalAccountsProcessed;
    uint256 public averageDemurrageRate;
    uint256 public lastGlobalUpdate;

    // Fiat integration
    address public fiatOracle; // Oracle for fiat activity validation
    mapping(address => bool) public authorizedFiatReporters;

    // Emergency controls
    bool public emergencyMode;
    uint256 public emergencyRateOverride;
    mapping(address => bool) public emergencyOperators;

    // ============ Events ============

    event DemurrageConfigUpdated(AdvancedDemurrageConfig config);
    event DemurrageApplied(address indexed account, uint256 amount, uint256 effectiveRate);
    event AccountExemptionSet(address indexed account, bool exempt);
    event StabilityIndexUpdated(uint256 oldIndex, uint256 newIndex);
    event FiatActivityRecorded(address indexed account, uint256 amount, uint8 activityType);
    event FiatDiscountApplied(address indexed account, uint256 originalRate, uint256 discountedRate);
    event GracePeriodStarted(address indexed account, uint256 endTime);
    event GracePeriodEnded(address indexed account);
    event EmergencyModeActivated(address operator, uint256 rateOverride);
    event AdaptiveRateAdjustment(address indexed account, uint256 oldRate, uint256 newRate);

    /**
     * @dev Constructor
     * @param initialOwner Contract owner
     * @param _fiatOracle Fiat activity oracle address
     */
    constructor(address initialOwner, address _fiatOracle) Ownable(initialOwner) {
        fiatOracle = _fiatOracle;

        config = AdvancedDemurrageConfig({
            baseRate: 50,                    // 0.5% per hour
            maxRate: 200,                    // 2% per hour
            stabilityThreshold: 100,         // 1% stability threshold
            fiatDiscountFactor: 5000,        // Up to 50% discount
            gracePeriodsHours: 48,           // 48 hours grace period
            decayAcceleration: 10,           // 10% acceleration per instability period
            velocityThreshold: 500,          // 50% of optimal velocity
            adaptiveRateEnabled: true        // Enable adaptive rates
        });

        stabilityMetrics = StabilityMetrics({
            currentStabilityIndex: 1000,     // Perfect stability initially
            priceDeviation: 0,               // No deviation initially
            velocityRatio: 500,              // 50% velocity initially
            participationRate: 0,            // No participation initially
            lastStabilityUpdate: block.timestamp
        });

        lastGlobalUpdate = block.timestamp;
    }

    // ============ Core Demurrage Functions ============

    /**
     * @dev Calculate demurrage with all advanced features
     * @param account Account to calculate demurrage for
     * @param balance Current account balance
     * @return demurrageAmount Calculated demurrage amount
     */
    function calculateAdvancedDemurrage(
        address account,
        uint256 balance
    ) external view returns (uint256 demurrageAmount) {
        if (balance == 0 || exemptAccounts[account]) {
            return 0;
        }

        AccountDemurrageData memory data = accountData[account];

        // Check grace period
        if (data.isNewUser && block.timestamp < data.graceEndTime) {
            return 0;
        }

        // Calculate time elapsed since last application
        uint256 lastApplication = data.lastDemurrageApplication;
        if (lastApplication == 0) {
            lastApplication = data.graceEndTime > 0 ? data.graceEndTime : block.timestamp - SECONDS_PER_HOUR;
        }

        uint256 timeElapsed = block.timestamp - lastApplication;
        if (timeElapsed < SECONDS_PER_HOUR) {
            return 0; // No demurrage within first hour
        }

        // Calculate effective rate with all adjustments
        uint256 effectiveRate = _calculateEffectiveRate(account);

        // Apply exponential decay formula: New_Balance = Original_Balance * e^(-rate * time_elapsed)
        uint256 hoursElapsed = timeElapsed / SECONDS_PER_HOUR;

        // Cap hours elapsed to prevent extreme demurrage (max 30 days = 720 hours)
        if (hoursElapsed > 720) {
            hoursElapsed = 720;
        }

        uint256 decayedBalance = balance.calculateExponentialDecay(effectiveRate, hoursElapsed);
        uint256 calculatedDemurrage = balance > decayedBalance ? balance - decayedBalance : 0;

        // Cap demurrage at 50% of balance to prevent "Insufficient balance" errors
        uint256 maxDemurrage = balance / 2; // 50% maximum

        return calculatedDemurrage > maxDemurrage ? maxDemurrage : calculatedDemurrage;
    }

    /**
     * @dev Apply demurrage with full tracking and metrics
     * @param account Account to apply demurrage to
     * @param balance Current account balance
     * @return appliedAmount Amount of demurrage applied
     */
    function applyAdvancedDemurrage(
        address account,
        uint256 balance
    ) external nonReentrant whenNotPaused returns (uint256 appliedAmount) {
        require(msg.sender == owner() || emergencyOperators[msg.sender], "Unauthorized");

        appliedAmount = this.calculateAdvancedDemurrage(account, balance);

        if (appliedAmount > 0) {
            AccountDemurrageData storage data = accountData[account];
            uint256 effectiveRate = _calculateEffectiveRate(account);

            // Update account data
            data.lastDemurrageApplication = block.timestamp;
            data.totalDemurragePaid += appliedAmount;
            data.effectiveRate = effectiveRate;

            // Update global metrics
            totalDemurrageCollected += appliedAmount;
            totalAccountsProcessed++;

            // Update average rate
            averageDemurrageRate = ((averageDemurrageRate * (totalAccountsProcessed - 1)) + effectiveRate) / totalAccountsProcessed;

            emit DemurrageApplied(account, appliedAmount, effectiveRate);
        }

        return appliedAmount;
    }

    /**
     * @dev Record fiat activity for discount calculation
     * @param account Account with fiat activity
     * @param amount Fiat activity amount (in USD equivalent)
     * @param activityType Type of activity (0=purchase, 1=redemption, 2=payment)
     */
    function recordFiatActivity(
        address account,
        uint256 amount,
        uint8 activityType
    ) external nonReentrant {
        require(authorizedFiatReporters[msg.sender] || msg.sender == owner(), "Unauthorized reporter");
        require(amount > 0, "Amount must be positive");

        FiatActivityDiscount storage discount = fiatDiscounts[account];
        uint256 currentTime = block.timestamp;

        // Update volume tracking with time-weighted decay
        _updateFiatVolumeTracking(discount, amount, currentTime);

        // Calculate new discount percentage
        uint256 newDiscountPercentage = _calculateFiatDiscount(account);
        discount.discountPercentage = newDiscountPercentage;
        discount.isEligible = newDiscountPercentage > 0;
        discount.lastActivityTime = currentTime;

        emit FiatActivityRecorded(account, amount, activityType);

        if (newDiscountPercentage > 0) {
            uint256 originalRate = _calculateBaseStabilityRate();
            uint256 discountedRate = _applyFiatActivityDiscount(account, originalRate);
            emit FiatDiscountApplied(account, originalRate, discountedRate);
        }
    }

    /**
     * @dev Start grace period for new user
     * @param account New user account
     */
    function startGracePeriod(address account) external {
        require(msg.sender == owner() || emergencyOperators[msg.sender], "Unauthorized");

        AccountDemurrageData storage data = accountData[account];
        require(!data.isNewUser, "Already in grace period");

        data.isNewUser = true;
        data.graceEndTime = block.timestamp + (config.gracePeriodsHours * SECONDS_PER_HOUR);

        emit GracePeriodStarted(account, data.graceEndTime);
    }

    /**
     * @dev Update stability metrics for rate adjustments
     * @param priceDeviation Current price deviation from peg (basis points)
     * @param velocityRatio Current money velocity ratio
     * @param participationRate Current network participation rate
     */
    function updateStabilityMetrics(
        uint256 priceDeviation,
        uint256 velocityRatio,
        uint256 participationRate
    ) external {
        require(msg.sender == owner() || emergencyOperators[msg.sender], "Unauthorized");

        uint256 oldStabilityIndex = stabilityMetrics.currentStabilityIndex;

        // Calculate new stability index using advanced formula
        uint256 newStabilityIndex = _calculateAdvancedStabilityIndex(
            priceDeviation,
            velocityRatio,
            participationRate
        );

        stabilityMetrics.currentStabilityIndex = newStabilityIndex;
        stabilityMetrics.priceDeviation = priceDeviation;
        stabilityMetrics.velocityRatio = velocityRatio;
        stabilityMetrics.participationRate = participationRate;
        stabilityMetrics.lastStabilityUpdate = block.timestamp;

        emit StabilityIndexUpdated(oldStabilityIndex, newStabilityIndex);

        // Trigger adaptive rate adjustments if enabled
        if (config.adaptiveRateEnabled) {
            _triggerAdaptiveRateAdjustments();
        }
    }

    // ============ Configuration Functions ============

    /**
     * @dev Update demurrage configuration
     * @param newConfig New configuration parameters
     */
    function updateDemurrageConfig(
        AdvancedDemurrageConfig calldata newConfig
    ) external onlyOwner {
        require(newConfig.baseRate >= MIN_DEMURRAGE_RATE, "Base rate too low");
        require(newConfig.maxRate <= MAX_DEMURRAGE_RATE, "Max rate too high");
        require(newConfig.baseRate <= newConfig.maxRate, "Invalid rate range");
        require(newConfig.fiatDiscountFactor <= MAX_FIAT_DISCOUNT, "Discount factor too high");
        require(newConfig.gracePeriodsHours <= MAX_GRACE_PERIOD / SECONDS_PER_HOUR, "Grace period too long");

        config = newConfig;
        emit DemurrageConfigUpdated(newConfig);
    }

    /**
     * @dev Set account exemption status
     * @param account Account address
     * @param exempt Whether to exempt account
     */
    function setAccountExemption(address account, bool exempt) external onlyOwner {
        exemptAccounts[account] = exempt;
        accountData[account].isExempt = exempt;
        emit AccountExemptionSet(account, exempt);
    }

    /**
     * @dev Add authorized fiat reporter
     * @param reporter Reporter address
     */
    function addFiatReporter(address reporter) external onlyOwner {
        authorizedFiatReporters[reporter] = true;
    }

    /**
     * @dev Remove authorized fiat reporter
     * @param reporter Reporter address
     */
    function removeFiatReporter(address reporter) external onlyOwner {
        authorizedFiatReporters[reporter] = false;
    }

    /**
     * @dev Add emergency operator
     * @param operator Operator address
     */
    function addEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = true;
    }

    /**
     * @dev Remove emergency operator
     * @param operator Operator address
     */
    function removeEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = false;
    }

    // ============ Emergency Functions ============

    /**
     * @dev Activate emergency mode with rate override
     * @param rateOverride Emergency rate override (0 to pause demurrage)
     */
    function activateEmergencyMode(uint256 rateOverride) external {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");
        require(rateOverride <= MAX_DEMURRAGE_RATE, "Rate override too high");

        emergencyMode = true;
        emergencyRateOverride = rateOverride;

        emit EmergencyModeActivated(msg.sender, rateOverride);
    }

    /**
     * @dev Deactivate emergency mode
     */
    function deactivateEmergencyMode() external onlyOwner {
        emergencyMode = false;
        emergencyRateOverride = 0;
    }

    // ============ View Functions ============

    function getAdvancedDemurrageConfig() external view returns (AdvancedDemurrageConfig memory) {
        return config;
    }

    function getAccountDemurrageData(address account) external view returns (AccountDemurrageData memory) {
        return accountData[account];
    }

    function getFiatDiscountData(address account) external view returns (FiatActivityDiscount memory) {
        return fiatDiscounts[account];
    }

    function getStabilityMetrics() external view returns (StabilityMetrics memory) {
        return stabilityMetrics;
    }

    function getCurrentEffectiveRate(address account) external view returns (uint256) {
        return _calculateEffectiveRate(account);
    }

    function isAccountInGracePeriod(address account) external view returns (bool) {
        AccountDemurrageData memory data = accountData[account];
        return data.isNewUser && block.timestamp < data.graceEndTime;
    }

    // ============ Internal Functions ============

    function _calculateEffectiveRate(address account) internal view returns (uint256) {
        if (exemptAccounts[account]) {
            return 0;
        }

        if (emergencyMode) {
            return emergencyRateOverride;
        }

        // Start with base stability-adjusted rate
        uint256 baseRate = _calculateBaseStabilityRate();

        // Apply fiat activity discount
        uint256 discountedRate = _applyFiatActivityDiscount(account, baseRate);

        // Apply adaptive adjustments if enabled
        if (config.adaptiveRateEnabled) {
            discountedRate = _applyAdaptiveAdjustments(account, discountedRate);
        }

        // Ensure rate is within bounds
        return _clampRate(discountedRate);
    }

    function _calculateBaseStabilityRate() internal view returns (uint256) {
        uint256 stabilityIndex = stabilityMetrics.currentStabilityIndex;
        uint256 baseRate = config.baseRate;
        uint256 maxRate = config.maxRate;

        if (stabilityIndex >= 950) {
            // Very stable - minimal demurrage
            return baseRate / 4;
        } else if (stabilityIndex <= 200) {
            // Very unstable - maximum demurrage
            return maxRate;
        }

        // Linear interpolation based on stability
        // Rate increases as stability decreases
        uint256 instability = 1000 - stabilityIndex;
        uint256 rateRange = maxRate - baseRate;
        uint256 additionalRate = (rateRange * instability) / 800; // Scale factor

        return baseRate + additionalRate;
    }

    function _applyFiatActivityDiscount(address account, uint256 rate) internal view returns (uint256) {
        FiatActivityDiscount memory discount = fiatDiscounts[account];

        if (!discount.isEligible || discount.discountPercentage == 0) {
            return rate;
        }

        uint256 discountAmount = (rate * discount.discountPercentage) / BASIS_POINTS;
        return rate > discountAmount ? rate - discountAmount : 0;
    }

    function _applyAdaptiveAdjustments(address account, uint256 rate) internal view returns (uint256) {
        AccountDemurrageData memory data = accountData[account];

        // Adjust based on account's historical behavior
        // Accounts with consistent low-risk behavior get rate reduction
        if (data.totalDemurragePaid > 0 && data.lastDemurrageApplication > 0) {
            uint256 timeSinceLastPayment = block.timestamp - data.lastDemurrageApplication;

            if (timeSinceLastPayment >= 30 days) {
                // Long-term holders get bonus reduction
                uint256 loyaltyDiscount = rate / 10; // 10% discount
                return rate > loyaltyDiscount ? rate - loyaltyDiscount : rate / 2;
            }
        }

        return rate;
    }

    function _calculateFiatDiscount(address account) internal view returns (uint256) {
        FiatActivityDiscount memory discount = fiatDiscounts[account];
        uint256 currentTime = block.timestamp;

        // Time-decay the discount eligibility
        if (currentTime > discount.lastActivityTime + 30 days) {
            return 0; // No discount after 30 days of inactivity
        }

        // Calculate discount based on recent activity
        uint256 volume24h = _getVolumeInPeriod(discount, currentTime - 1 days);
        uint256 volume7d = _getVolumeInPeriod(discount, currentTime - 7 days);

        if (volume24h >= 1000 * PRECISION) {
            return config.fiatDiscountFactor; // Maximum discount
        } else if (volume7d >= 5000 * PRECISION) {
            return config.fiatDiscountFactor * 3 / 4; // 75% of max discount
        } else if (volume7d >= 1000 * PRECISION) {
            return config.fiatDiscountFactor / 2; // 50% of max discount
        } else if (volume7d >= 100 * PRECISION) {
            return config.fiatDiscountFactor / 4; // 25% of max discount
        }

        return 0;
    }

    function _updateFiatVolumeTracking(
        FiatActivityDiscount storage discount,
        uint256 amount,
        uint256 currentTime
    ) internal {
        // Simple time-weighted decay for volume tracking
        uint256 timeSinceLastActivity = currentTime - discount.lastActivityTime;

        if (timeSinceLastActivity > 0) {
            // Apply decay to existing volumes
            if (timeSinceLastActivity >= 24 hours) {
                discount.volume24h = 0;
            } else {
                discount.volume24h = (discount.volume24h * (24 hours - timeSinceLastActivity)) / 24 hours;
            }

            if (timeSinceLastActivity >= 7 days) {
                discount.volume7d = 0;
            } else {
                discount.volume7d = (discount.volume7d * (7 days - timeSinceLastActivity)) / 7 days;
            }

            if (timeSinceLastActivity >= 30 days) {
                discount.volume30d = 0;
            } else {
                discount.volume30d = (discount.volume30d * (30 days - timeSinceLastActivity)) / 30 days;
            }
        }

        // Add new activity
        discount.volume24h += amount;
        discount.volume7d += amount;
        discount.volume30d += amount;
    }

    function _getVolumeInPeriod(
        FiatActivityDiscount memory discount,
        uint256 periodStart
    ) internal pure returns (uint256) {
        if (discount.lastActivityTime < periodStart) {
            return 0;
        }

        // This is a simplified implementation
        // In practice, you'd need more sophisticated time-series tracking
        return discount.volume24h;
    }

    function _calculateAdvancedStabilityIndex(
        uint256 priceDeviation,
        uint256 velocityRatio,
        uint256 participationRate
    ) internal pure returns (uint256) {
        // Advanced stability calculation using weighted factors
        uint256 priceStability = priceDeviation > 1000 ? 0 : 1000 - priceDeviation;
        uint256 velocityStability = velocityRatio > 1000 ? 1000 : velocityRatio;
        uint256 participationStability = participationRate > 1000 ? 1000 : participationRate;

        // Weighted combination: 50% price, 30% velocity, 20% participation
        return (priceStability * 50 + velocityStability * 30 + participationStability * 20) / 100;
    }

    function _triggerAdaptiveRateAdjustments() internal {
        // This would trigger rate adjustments for accounts based on new stability metrics
        // Implementation would depend on how many accounts to process at once
        // For gas efficiency, this might be done in batches or triggered externally
    }

    function _clampRate(uint256 rate) internal view returns (uint256) {
        if (rate < MIN_DEMURRAGE_RATE) {
            return MIN_DEMURRAGE_RATE;
        } else if (rate > MAX_DEMURRAGE_RATE) {
            return MAX_DEMURRAGE_RATE;
        }
        return rate;
    }

    /**
     * @dev Pause contract operations
     */
    function pause() external {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");
        _pause();
    }

    /**
     * @dev Unpause contract operations
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/core/AntiSpeculationEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../libs/MathUtils.sol";
import "../interfaces/ICaesar.sol";

/**
 * @title AntiSpeculationEngine
 * @dev Implements transaction analysis and speculation prevention mechanisms
 */
contract AntiSpeculationEngine is Ownable, ReentrancyGuard {
    using MathUtils for uint256;

    // Configuration
    ICaesar.AntiSpeculationConfig public config;

    // Account tracking
    struct TransactionHistory {
        uint256 lastTransactionTime;
        uint256 transactionCount;
        uint256 totalVolume;
        uint256 averageHoldingPeriod;
        uint256 rapidTradeCount;
        bool flaggedForSpeculation;
    }

    mapping(address => TransactionHistory) public accountHistory;
    mapping(address => uint256[]) public holdingPeriods; // Track holding periods
    mapping(address => bool) public whitelistedAddresses;

    // Global metrics
    uint256 public totalPenaltiesCollected;
    uint256 public averageNetworkHoldingPeriod;
    uint256 public speculationThreshold = 3; // Number of rapid trades to flag

    // Events
    event SpeculationPenaltyApplied(address indexed account, uint256 penalty, string reason);
    event AccountFlagged(address indexed account, string reason);
    event AccountUnflagged(address indexed account);
    event ConfigurationUpdated();
    event WhitelistUpdated(address indexed account, bool whitelisted);

    constructor(address initialOwner) Ownable(initialOwner) {
        config = ICaesar.AntiSpeculationConfig({
            maxHoldingPeriod: 30 days,     // 30 days optimal holding
            penaltyRate: 200,              // 2% penalty for speculation
            rapidTradePenalty: 100,        // 1% penalty for rapid trading
            minTransactionGap: 1 hours     // Minimum 1 hour between transactions
        });
    }

    /**
     * @dev Analyze transaction and update account metrics
     * @param account The account making the transaction
     * @param amount The transaction amount
     * @param transactionType Type of transaction (0=transfer, 1=buy, 2=sell)
     * @return penalty Calculated penalty amount
     */
    function analyzeTransaction(
        address account,
        uint256 amount,
        uint8 transactionType
    ) external returns (uint256 penalty) {
        require(msg.sender == owner() || msg.sender == address(this), "Unauthorized");

        if (whitelistedAddresses[account]) {
            return 0;
        }

        TransactionHistory storage history = accountHistory[account];
        uint256 currentTime = block.timestamp;

        // Update transaction metrics
        uint256 timeSinceLastTx = currentTime - history.lastTransactionTime;
        history.transactionCount++;
        history.totalVolume += amount;

        // Check for rapid trading
        if (timeSinceLastTx < config.minTransactionGap && history.lastTransactionTime != 0) {
            history.rapidTradeCount++;
            penalty += _calculateRapidTradePenalty(amount);
            emit SpeculationPenaltyApplied(account, penalty, "Rapid trading detected");
        }

        // Check for excessive holding (for sells)
        if (transactionType == 2 && history.lastTransactionTime != 0) {
            uint256 holdingPeriod = timeSinceLastTx;
            holdingPeriods[account].push(holdingPeriod);

            if (holdingPeriod > config.maxHoldingPeriod) {
                uint256 excessivePenalty = _calculateExcessiveHoldingPenalty(amount, holdingPeriod);
                penalty += excessivePenalty;
                emit SpeculationPenaltyApplied(account, excessivePenalty, "Excessive holding period");
            }
        }

        // Update speculation flag
        if (history.rapidTradeCount >= speculationThreshold) {
            if (!history.flaggedForSpeculation) {
                history.flaggedForSpeculation = true;
                emit AccountFlagged(account, "Excessive rapid trading");
            }
        }

        // Calculate volume-based penalty for flagged accounts
        if (history.flaggedForSpeculation) {
            uint256 volumePenalty = _calculateVolumePenalty(amount);
            penalty += volumePenalty;
            emit SpeculationPenaltyApplied(account, volumePenalty, "Flagged account penalty");
        }

        history.lastTransactionTime = currentTime;
        totalPenaltiesCollected += penalty;

        return penalty;
    }

    /**
     * @dev Calculate speculation penalty for an account
     * @param account The account to calculate penalty for
     * @param amount The transaction amount
     * @return penalty The calculated penalty amount
     */
    function calculateSpeculationPenalty(
        address account,
        uint256 amount
    ) external view returns (uint256 penalty) {
        if (whitelistedAddresses[account]) {
            return 0;
        }

        TransactionHistory memory history = accountHistory[account];

        // Rapid trade penalty
        if (block.timestamp - history.lastTransactionTime < config.minTransactionGap) {
            penalty += _calculateRapidTradePenalty(amount);
        }

        // Flagged account penalty
        if (history.flaggedForSpeculation) {
            penalty += _calculateVolumePenalty(amount);
        }

        return penalty;
    }

    /**
     * @dev Update participation score based on transaction patterns
     * @param account The account to update
     * @param transactionVolume Recent transaction volume
     * @return newScore The updated participation score
     */
    function updateParticipationScore(
        address account,
        uint256 transactionVolume
    ) external returns (uint256 newScore) {
        require(msg.sender == owner() || msg.sender == address(this), "Unauthorized");

        if (whitelistedAddresses[account]) {
            return 1000; // Max score for whitelisted accounts
        }

        TransactionHistory memory history = accountHistory[account];

        // Base score calculation
        newScore = 500; // Starting score

        // Penalty for rapid trading
        if (history.rapidTradeCount > 0) {
            uint256 rapidTradePenalty = (history.rapidTradeCount * 100);
            newScore = newScore > rapidTradePenalty ? newScore - rapidTradePenalty : 0;
        }

        // Bonus for consistent activity
        if (history.transactionCount >= 10) {
            uint256 averageInterval = _calculateAverageInterval(account);
            if (averageInterval >= 1 days && averageInterval <= 7 days) {
                newScore += 200; // Bonus for regular activity
            }
        }

        // Penalty for excessive volume concentration
        if (transactionVolume > history.totalVolume / 2) {
            newScore = newScore > 150 ? newScore - 150 : 0;
        }

        // Cap score at maximum
        if (newScore > 1000) {
            newScore = 1000;
        }

        return newScore;
    }

    /**
     * @dev Set anti-speculation configuration
     * @param newConfig New configuration parameters
     */
    function setAntiSpeculationConfig(
        ICaesar.AntiSpeculationConfig calldata newConfig
    ) external onlyOwner {
        require(newConfig.penaltyRate <= 1000, "Penalty rate too high"); // Max 10%
        require(newConfig.rapidTradePenalty <= 500, "Rapid trade penalty too high"); // Max 5%
        require(newConfig.minTransactionGap >= 300, "Transaction gap too short"); // Min 5 minutes
        require(newConfig.maxHoldingPeriod >= 1 days, "Holding period too short");

        config = newConfig;
        emit ConfigurationUpdated();
    }

    /**
     * @dev Set whitelist status for an account
     * @param account The account to whitelist/unwhitelist
     * @param whitelisted Whether the account should be whitelisted
     */
    function setWhitelistStatus(address account, bool whitelisted) external onlyOwner {
        whitelistedAddresses[account] = whitelisted;
        emit WhitelistUpdated(account, whitelisted);
    }

    /**
     * @dev Unflag an account manually
     * @param account The account to unflag
     */
    function unflagAccount(address account) external onlyOwner {
        accountHistory[account].flaggedForSpeculation = false;
        accountHistory[account].rapidTradeCount = 0;
        emit AccountUnflagged(account);
    }

    /**
     * @dev Get account transaction history
     * @param account The account to query
     * @return history The transaction history
     */
    function getAccountHistory(
        address account
    ) external view returns (TransactionHistory memory history) {
        return accountHistory[account];
    }

    /**
     * @dev Check if account is flagged for speculation
     * @param account The account to check
     * @return flagged Whether the account is flagged
     */
    function isAccountFlagged(address account) external view returns (bool flagged) {
        return accountHistory[account].flaggedForSpeculation;
    }

    /**
     * @dev Get total penalties collected
     * @return total Total penalties collected
     */
    function getTotalPenaltiesCollected() external view returns (uint256 total) {
        return totalPenaltiesCollected;
    }

    // Internal functions

    /**
     * @dev Calculate rapid trade penalty
     * @param amount Transaction amount
     * @return penalty Penalty amount
     */
    function _calculateRapidTradePenalty(uint256 amount) internal view returns (uint256 penalty) {
        return (amount * config.rapidTradePenalty) / 10000;
    }

    /**
     * @dev Calculate excessive holding penalty
     * @param amount Transaction amount
     * @param holdingPeriod Holding period in seconds
     * @return penalty Penalty amount
     */
    function _calculateExcessiveHoldingPenalty(
        uint256 amount,
        uint256 holdingPeriod
    ) internal view returns (uint256 penalty) {
        if (holdingPeriod <= config.maxHoldingPeriod) {
            return 0;
        }

        uint256 excessDays = (holdingPeriod - config.maxHoldingPeriod) / 1 days;
        uint256 penaltyRate = config.penaltyRate + (excessDays * 10); // Escalating penalty

        // Cap penalty at 10%
        if (penaltyRate > 1000) {
            penaltyRate = 1000;
        }

        return (amount * penaltyRate) / 10000;
    }

    /**
     * @dev Calculate volume-based penalty for flagged accounts
     * @param amount Transaction amount
     * @return penalty Penalty amount
     */
    function _calculateVolumePenalty(uint256 amount) internal view returns (uint256 penalty) {
        return (amount * config.penaltyRate) / 10000;
    }

    /**
     * @dev Calculate average transaction interval for an account
     * @param account The account to analyze
     * @return averageInterval Average interval in seconds
     */
    function _calculateAverageInterval(address account) internal view returns (uint256 averageInterval) {
        uint256[] memory periods = holdingPeriods[account];
        if (periods.length == 0) {
            return 0;
        }

        uint256 totalPeriod = 0;
        for (uint256 i = 0; i < periods.length; i++) {
            totalPeriod += periods[i];
        }

        return totalPeriod / periods.length;
    }

    /**
     * @dev Get anti-speculation configuration
     * @return config Current configuration
     */
    function getAntiSpeculationConfig() external view returns (ICaesar.AntiSpeculationConfig memory) {
        return config;
    }

    /**
     * @dev Emergency pause function
     */
    function pauseAntiSpeculation() external onlyOwner {
        config.penaltyRate = 0;
        config.rapidTradePenalty = 0;
        config.minTransactionGap = 0;
    }
}

contracts/core/CaesarToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import { OFT } from "@layerzerolabs/oft-evm/contracts/OFT.sol";
import { SendParam, MessagingFee } from "@layerzerolabs/oft-evm/contracts/interfaces/IOFT.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { ReentrancyGuard } from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "../interfaces/ICaesar.sol";
import "./DemurrageManager.sol";
import "./AntiSpeculationEngine.sol";
import "../libs/MathUtils.sol";
import "../oracles/GoldPriceOracle.sol";

/**
 * @title Caesar (CAES)
 * @dev LayerZero V2 OFT implementation with demurrage and anti-speculation mechanisms
 * Updated version with CAESAR name and CAES symbol for migration
 */
contract CaesarToken is OFT, ICaesar, ReentrancyGuard {
    using MathUtils for uint256;

    // Core components
    GoldPriceOracle public immutable goldOracle;
    DemurrageManager public immutable demurrageManager;
    AntiSpeculationEngine public immutable antiSpeculationEngine;

    // Migration tracking
    address public migrationContract;
    bool public migrationEnabled;

    // State variables
    uint256 public currentEpoch;
    uint256 public epochDuration = 1 days;
    uint256 public lastEpochUpdate;
    uint256 public targetPrice = 1e18; // 1 USDC in wei
    uint256 public lastRebaseTime;
    uint256 public rebaseInterval = 7 days;
    uint256 public maxRebasePercent = 1000; // 10%

    // Account tracking
    mapping(address => AccountInfo) public accounts;
    mapping(uint256 => uint256) public epochSupply;

    // Network metrics
    uint256 public totalHolders;
    uint256 public activeParticipants;
    uint256 public stabilityPoolBalance;

    // Cross-chain state
    mapping(uint32 => uint256) public chainSupply; // Track supply per chain

    // Events
    event EpochAdvanced(uint256 indexed newEpoch, uint256 timestamp);
    event AccountActivityUpdated(address indexed account, uint256 timestamp);
    event CrossChainSupplySync(uint32 indexed chainId, uint256 supply);
    event MigrationContractSet(address indexed migrationContract);
    event MigrationEnabled(bool enabled);

    /**
     * @dev Constructor
     * @param lzEndpoint LayerZero endpoint address
     * @param owner Contract owner
     */
    constructor(
        address lzEndpoint,
        address owner
    ) OFT("CAESAR", "CAES", lzEndpoint, owner) Ownable(owner) {
        goldOracle = new GoldPriceOracle(owner);
        demurrageManager = new DemurrageManager(owner, address(goldOracle));
        antiSpeculationEngine = new AntiSpeculationEngine(owner);

        currentEpoch = 1;
        lastEpochUpdate = block.timestamp;
        lastRebaseTime = block.timestamp;

        // Initialize with zero supply - will be minted during migration
        epochSupply[currentEpoch] = 0;
    }

    /**
     * @dev Set migration contract address
     */
    function setMigrationContract(address _migrationContract) external onlyOwner {
        require(_migrationContract != address(0), "Invalid migration contract");
        migrationContract = _migrationContract;
        emit MigrationContractSet(_migrationContract);
    }

    /**
     * @dev Enable/disable migration
     */
    function setMigrationEnabled(bool _enabled) external onlyOwner {
        migrationEnabled = _enabled;
        emit MigrationEnabled(_enabled);
    }

    /**
     * @dev Mint tokens during migration (only callable by migration contract)
     */
    function migrationMint(address to, uint256 amount) external {
        require(msg.sender == migrationContract, "Only migration contract");
        require(migrationEnabled, "Migration not enabled");
        _mint(to, amount);
    }

    /**
     * @dev Transfer function with demurrage and anti-speculation
     */
    function transfer(address to, uint256 amount) public override returns (bool) {
        address from = msg.sender;

        // Apply demurrage before transfer
        uint256 demurrageFrom = _applyDemurrage(from);
        _applyDemurrage(to);

        // Check if balance is sufficient after demurrage
        uint256 balanceAfterDemurrage = balanceOf(from);
        require(balanceAfterDemurrage >= amount, "Insufficient balance after demurrage");

        // Check anti-speculation penalties
        uint256 penalty = antiSpeculationEngine.calculateSpeculationPenalty(from, amount);
        if (penalty > 0) {
            uint256 netAmount = amount - penalty;
            require(netAmount > 0, "Penalty exceeds transfer amount");
            require(balanceAfterDemurrage >= amount, "Insufficient balance for penalty and transfer");

            // Transfer penalty to stability pool
            _transfer(from, address(this), penalty);
            stabilityPoolBalance += penalty;

            // Transfer remaining amount
            _transfer(from, to, netAmount);

            // Update participation scores
            antiSpeculationEngine.updateParticipationScore(from, amount);
        } else {
            _transfer(from, to, amount);
        }

        // Update account activity
        _updateAccountActivity(from);
        _updateAccountActivity(to);

        return true;
    }

    /**
     * @dev Transfer from function with demurrage and anti-speculation
     */
    function transferFrom(address from, address to, uint256 amount) public override returns (bool) {
        // Apply demurrage before transfer
        _applyDemurrage(from);
        _applyDemurrage(to);

        // Check if balance is sufficient after demurrage
        uint256 balanceAfterDemurrage = balanceOf(from);
        require(balanceAfterDemurrage >= amount, "Insufficient balance after demurrage");

        // Check anti-speculation penalties
        uint256 penalty = antiSpeculationEngine.calculateSpeculationPenalty(from, amount);
        if (penalty > 0) {
            uint256 netAmount = amount - penalty;
            require(netAmount > 0, "Penalty exceeds transfer amount");
            require(balanceAfterDemurrage >= amount, "Insufficient balance for penalty and transfer");

            // Update allowance for full amount
            _spendAllowance(from, msg.sender, amount);

            // Transfer penalty to stability pool
            _transfer(from, address(this), penalty);
            stabilityPoolBalance += penalty;

            // Transfer remaining amount
            _transfer(from, to, netAmount);
        } else {
            _spendAllowance(from, msg.sender, amount);
            _transfer(from, to, amount);
        }

        // Update account activity
        _updateAccountActivity(from);
        _updateAccountActivity(to);

        return true;
    }

    /**
     * @dev Apply demurrage to an account
     */
    function applyDemurrage(address account) external returns (uint256 appliedAmount) {
        return _applyDemurrage(account);
    }

    /**
     * @dev Calculate demurrage for an account
     */
    function calculateDemurrage(address account) external view returns (uint256 demurrageAmount) {
        if (accounts[account].isExempt || balanceOf(account) == 0) {
            return 0;
        }

        AccountInfo memory accountInfo = accounts[account];

        // Only calculate demurrage if there has been activity before
        if (accountInfo.lastActivity == 0) {
            return 0;
        }

        return demurrageManager.calculateDemurrage(
            account,
            balanceOf(account),
            accountInfo.lastActivity
        );
    }

    /**
     * @dev Get current decay rate
     */
    function getCurrentDecayRate() external view returns (uint256 decayRate) {
        return demurrageManager.getCurrentDecayRate();
    }

    /**
     * @dev Set demurrage configuration
     */
    function setDemurrageConfig(DemurrageConfig calldata config) external onlyOwner {
        // For simplicity, we'll just validate the config here
        // In a production system, you'd want to properly integrate with DemurrageManager
        require(config.baseRate <= config.maxRate, "Invalid rate configuration");
        require(config.maxRate <= 1000, "Max rate too high");
        require(config.decayInterval > 0, "Invalid decay interval");
        // Configuration accepted (would normally pass to DemurrageManager)
    }

    /**
     * @dev Calculate speculation penalty
     */
    function calculateSpeculationPenalty(address account) external view returns (uint256 penalty) {
        return antiSpeculationEngine.calculateSpeculationPenalty(account, balanceOf(account));
    }

    /**
     * @dev Update participation score
     */
    function updateParticipationScore(address account, uint256 transactionVolume) external onlyOwner {
        uint256 newScore = antiSpeculationEngine.updateParticipationScore(account, transactionVolume);
        accounts[account].participationScore = newScore;
    }

    /**
     * @dev Set anti-speculation configuration
     */
    function setAntiSpeculationConfig(AntiSpeculationConfig calldata config) external onlyOwner {
        antiSpeculationEngine.setAntiSpeculationConfig(config);
    }

    /**
     * @dev Check if account is exempt from demurrage
     */
    function isAccountExempt(address account) external view returns (bool exempt) {
        return accounts[account].isExempt;
    }

    /**
     * @dev Get current epoch
     */
    function getCurrentEpoch() external view returns (uint256 epoch) {
        return currentEpoch;
    }

    /**
     * @dev Advance to next epoch
     */
    function advanceEpoch() external {
        require(block.timestamp >= lastEpochUpdate + epochDuration, "Epoch duration not elapsed");

        currentEpoch++;
        lastEpochUpdate = block.timestamp;
        epochSupply[currentEpoch] = totalSupply();

        emit EpochAdvanced(currentEpoch, block.timestamp);
        emit TensorEpochUpdate(currentEpoch, block.timestamp);
    }

    /**
     * @dev Get epoch duration
     */
    function getEpochDuration() external view returns (uint256 duration) {
        return epochDuration;
    }

    /**
     * @dev Perform rebase operation
     */
    function rebase() external returns (uint256 newSupply) {
        require(shouldRebase(), "Rebase conditions not met");

        uint256 rebaseRatio = getRebaseRatio();
        uint256 currentSupply = totalSupply();

        if (rebaseRatio > 10000) {
            // Increase supply
            uint256 increase = ((rebaseRatio - 10000) * currentSupply) / 10000;
            _mint(address(this), increase);
            stabilityPoolBalance += increase;
        } else if (rebaseRatio < 10000) {
            // Decrease supply
            uint256 decrease = ((10000 - rebaseRatio) * currentSupply) / 10000;
            uint256 availableBalance = balanceOf(address(this));
            if (decrease > availableBalance) {
                decrease = availableBalance;
            }
            _burn(address(this), decrease);
            if (stabilityPoolBalance > decrease) {
                stabilityPoolBalance -= decrease;
            } else {
                stabilityPoolBalance = 0;
            }
        }

        lastRebaseTime = block.timestamp;
        newSupply = totalSupply();

        emit RebaseOccurred(currentEpoch, rebaseRatio, newSupply);
        return newSupply;
    }

    /**
     * @dev Get current rebase ratio
     */
    function getRebaseRatio() public view returns (uint256 ratio) {
        // This would typically get price from an oracle
        // For now, return base ratio (no rebase needed)
        return 10000; // 1.0x ratio
    }

    /**
     * @dev Check if rebase should occur
     */
    function shouldRebase() public view returns (bool shouldRebaseNow) {
        if (block.timestamp < lastRebaseTime + rebaseInterval) {
            return false;
        }

        uint256 ratio = getRebaseRatio();
        return ratio != 10000; // Rebase if ratio is not 1.0x
    }

    /**
     * @dev Contribute to stability pool
     */
    function contributeToStabilityPool(uint256 amount) external {
        require(amount > 0, "Amount must be positive");
        require(balanceOf(msg.sender) >= amount, "Insufficient balance");

        _transfer(msg.sender, address(this), amount);
        stabilityPoolBalance += amount;

        emit StabilityPoolContribution(amount, block.timestamp);
    }

    /**
     * @dev Get stability pool balance
     */
    function getStabilityPoolBalance() external view returns (uint256 balance) {
        return stabilityPoolBalance;
    }

    /**
     * @dev Withdraw from stability pool (owner only)
     */
    function withdrawFromStabilityPool(uint256 amount) external onlyOwner {
        require(amount <= stabilityPoolBalance, "Insufficient stability pool balance");

        _transfer(address(this), owner(), amount);
        stabilityPoolBalance -= amount;
    }

    /**
     * @dev Get network health index
     */
    function getNetworkHealthIndex() external view returns (uint256 healthIndex) {
        if (totalHolders == 0) {
            return 0;
        }

        uint256 participationRatio = (activeParticipants * 1000) / totalHolders;
        uint256 liquidityRatio = getLiquidityRatio();
        uint256 stabilityRatio = stabilityPoolBalance > 0 ? 
            (stabilityPoolBalance * 1000) / totalSupply() : 0;

        return (participationRatio + liquidityRatio + stabilityRatio) / 3;
    }

    /**
     * @dev Get liquidity ratio
     */
    function getLiquidityRatio() public view returns (uint256 liquidityRatio) {
        // Calculate based on active vs total supply
        // This is a simplified implementation
        if (totalHolders == 0) {
            return 0;
        }
        return (activeParticipants * 1000) / totalHolders;
    }

    /**
     * @dev Get active participants count
     */
    function getActiveParticipants() external view returns (uint256 activeCount) {
        return activeParticipants;
    }

    /**
     * @dev Get account information
     */
    function getAccountInfo(address account) external view returns (AccountInfo memory info) {
        return accounts[account];
    }

    /**
     * @dev Set account exemption status
     */
    function setAccountExemption(address account, bool exempt) external onlyOwner {
        accounts[account].isExempt = exempt;
        // Note: DemurrageManager ownership would need to be transferred to this contract
        // For testing, we'll handle exemptions internally
    }

    /**
     * @dev Update account activity
     */
    function updateAccountActivity(address account) external {
        _updateAccountActivity(account);
    }

    /**
     * @dev Internal function to apply demurrage
     */
    function _applyDemurrage(address account) internal returns (uint256 appliedAmount) {
        if (accounts[account].isExempt || balanceOf(account) == 0) {
            return 0;
        }

        AccountInfo storage accountInfo = accounts[account];

        // Only apply demurrage if there has been some activity before
        if (accountInfo.lastActivity == 0) {
            return 0;
        }

        appliedAmount = demurrageManager.calculateDemurrage(
            account,
            balanceOf(account),
            accountInfo.lastActivity
        );

        if (appliedAmount > 0 && appliedAmount <= balanceOf(account)) {
            _transfer(account, address(this), appliedAmount);
            stabilityPoolBalance += appliedAmount;
            // Update the last demurrage application time to prevent double-application
            accountInfo.lastActivity = block.timestamp;
            emit DemurrageApplied(account, appliedAmount, block.timestamp);
        }

        return appliedAmount;
    }

    /**
     * @dev Internal function to update account activity
     */
    function _updateAccountActivity(address account) internal {
        AccountInfo storage accountInfo = accounts[account];

        if (accountInfo.lastActivity == 0) {
            totalHolders++;
        }

        accountInfo.lastActivity = block.timestamp;

        // Update active participants (active in last 24 hours)
        if (block.timestamp - accountInfo.lastActivity <= 1 days) {
            // This is simplified - in production you'd track this more efficiently
            _updateActiveParticipants();
        }

        emit AccountActivityUpdated(account, block.timestamp);
    }

    /**
     * @dev Internal function to update active participants count
     */
    function _updateActiveParticipants() internal {
        // Simplified implementation - in production this would be more sophisticated
        // Could use a more efficient data structure to track active participants
        activeParticipants = totalHolders; // Placeholder
    }

    /**
     * @dev Bridge with decay implementation for LayerZero OFT
     */
    function bridgeWithDecay(
        SendParam calldata sendParam,
        MessagingFee calldata fee,
        address refundAddress
    ) external payable returns (MessagingFee memory messagingFee) {
        // Apply demurrage before bridge operation
        _applyDemurrage(msg.sender);

        // For now, return the provided fee structure
        // In production, this would include decay calculations and actual bridging
        return fee;
    }

    /**
     * @dev Quote bridge with decay for LayerZero OFT
     */
    function quoteBridgeWithDecay(
        SendParam calldata sendParam,
        bool payInLzToken
    ) external view returns (MessagingFee memory messagingFee) {
        // For now, return a basic fee structure
        // In production, this would include decay calculation fees
        return MessagingFee({ nativeFee: 0.001 ether, lzTokenFee: 0 });
    }
}

contracts/core/CrossChainEconomicSync.so.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@layerzerolabs/lz-evm-protocol-v2/contracts/interfaces/ILayerZeroEndpointV2.sol";
import "@layerzerolabs/lz-evm-protocol-v2/contracts/interfaces/IMessageLibManager.sol";
import "@layerzerolabs/lz-evm-oapp-v2/contracts/oapp/OApp.sol";
import "../interfaces/IEconomicEngine.sol";
import "../libs/AdvancedMathUtils.sol";

/**
 * @title CrossChainEconomicSync
 * @dev LayerZero V2 based cross-chain economic parameter synchronization system
 * Enables real-time synchronization of economic parameters, stability metrics,
 * and intervention commands across all supported chains for Caesar Token
 */
contract CrossChainEconomicSync is OApp, ReentrancyGuard, Pausable {
    using AdvancedMathUtils for uint256;

    // ============ Constants ============
    uint256 public constant MAX_BATCH_SIZE = 50;
    uint256 public constant SYNC_TIMEOUT = 1 hours;
    uint256 public constant PARAMETER_VERSION = 1;
    uint256 public constant MAX_RETRIES = 3;

    // ============ Message Types ============
    uint8 public constant MSG_PARAMETER_SYNC = 1;
    uint8 public constant MSG_STABILITY_UPDATE = 2;
    uint8 public constant MSG_EMERGENCY_BROADCAST = 3;
    uint8 public constant MSG_INTERVENTION_COMMAND = 4;
    uint8 public constant MSG_HEALTH_METRICS = 5;
    uint8 public constant MSG_BATCH_SYNC = 6;

    // ============ Structs ============

    struct CrossChainParameters {
        uint256 baseDemurrageRate;           // Base demurrage rate
        uint256 maxDemurrageRate;            // Maximum demurrage rate
        uint256 stabilityThreshold;          // Stability threshold
        uint256 fiatDiscountFactor;          // Fiat discount factor
        uint256 antiSpeculationPenaltyRate;  // Anti-speculation penalty rate
        uint256 circuitBreakerThreshold;     // Circuit breaker threshold
        uint256 rebalanceFrequency;          // Rebalance frequency
        uint256 timestamp;                   // Parameter timestamp
        bytes32 parameterHash;               // Hash for integrity verification
    }

    struct StabilityMetrics {
        uint256 priceStability;              // Price stability index
        uint256 liquidityHealth;             // Liquidity health score
        uint256 participationRate;           // Network participation rate
        uint256 reserveRatio;                // Reserve backing ratio
        uint256 overallHealth;               // Overall system health
        uint256 timestamp;                   // Metrics timestamp
        uint32 sourceChain;                  // Source chain ID
    }

    struct EmergencyBroadcast {
        uint8 emergencyType;                 // Type of emergency (pause, circuit breaker, etc.)
        uint256 severity;                    // Emergency severity level
        uint256 duration;                    // Duration of emergency measures
        string reason;                       // Emergency reason
        address initiator;                   // Emergency initiator
        uint256 timestamp;                   // Broadcast timestamp
    }

    struct InterventionCommand {
        uint8 commandType;                   // Type of intervention
        uint256 targetParameter;             // Parameter to adjust
        uint256 newValue;                    // New parameter value
        uint256 executionTime;               // When to execute (0 = immediate)
        bool requiresConsensus;              // Whether consensus is required
        uint256 consensusThreshold;          // Consensus threshold if required
        bytes additionalData;                // Additional command data
    }

    struct SyncState {
        uint256 lastSyncTime;                // Last sync timestamp
        uint256 syncNonce;                   // Sync nonce for ordering
        bytes32 lastParameterHash;           // Last parameter hash
        bool isPending;                      // Whether sync is pending
        uint256 retryCount;                  // Number of retry attempts
        uint32[] targetChains;               // Target chains for sync
    }

    struct ChainStatus {
        bool isActive;                       // Whether chain is active
        uint256 lastHeartbeat;               // Last heartbeat timestamp
        uint256 latency;                     // Average message latency
        uint256 failureCount;                // Number of failures
        StabilityMetrics lastMetrics;        // Last received stability metrics
        CrossChainParameters lastParameters; // Last synchronized parameters
    }

    struct BatchSyncData {
        CrossChainParameters[] parameters;   // Batch of parameters
        StabilityMetrics[] metrics;          // Batch of metrics
        uint256 batchId;                     // Unique batch ID
        uint256 totalBatches;                // Total number of batches
        uint256 batchIndex;                  // Index of this batch
    }

    // ============ State Variables ============

    // Core economic engine reference
    IEconomicEngine public economicEngine;

    // Cross-chain state management
    mapping(uint32 => ChainStatus) public chainStatus;
    mapping(uint32 => SyncState) public chainSyncState;
    mapping(bytes32 => bool) public processedMessages;
    mapping(uint32 => uint256) public chainLatency;

    // Parameter synchronization
    CrossChainParameters public masterParameters;
    StabilityMetrics public aggregatedMetrics;
    uint256 public lastParameterUpdate;
    uint256 public lastMetricsAggregation;

    // Emergency management
    EmergencyBroadcast public activeEmergency;
    bool public isEmergencyActive;
    mapping(address => bool) public emergencyOperators;

    // Consensus system
    mapping(bytes32 => mapping(uint32 => bool)) public consensusVotes;
    mapping(bytes32 => uint256) public consensusCount;
    mapping(bytes32 => InterventionCommand) public pendingInterventions;

    // Performance metrics
    uint256 public totalMessagesSent;
    uint256 public totalMessagesReceived;
    uint256 public failedSyncAttempts;
    uint256 public averageSyncTime;

    // Supported chains
    uint32[] public supportedChains;
    mapping(uint32 => bool) public isSupportedChain;

    // ============ Events ============

    event ParametersSynchronized(uint32[] chains, bytes32 parameterHash);
    event StabilityMetricsReceived(uint32 fromChain, StabilityMetrics metrics);
    event EmergencyBroadcastSent(uint8 emergencyType, uint32[] targetChains);
    event InterventionCommandExecuted(bytes32 commandId, uint8 commandType);
    event ChainStatusUpdated(uint32 chainId, bool isActive, uint256 latency);
    event ConsensusReached(bytes32 interventionId, uint256 votes);
    event SyncFailure(uint32 chainId, string reason, uint256 retryCount);
    event BatchSyncCompleted(uint256 batchId, uint32[] chains);
    event CrossChainMessage(uint32 fromChain, uint32 toChain, uint8 messageType);

    /**
     * @dev Constructor
     * @param _endpoint LayerZero endpoint address
     * @param _owner Contract owner
     * @param _economicEngine Economic engine address
     */
    constructor(
        address _endpoint,
        address _owner,
        address _economicEngine
    ) OApp(_endpoint, _owner) Ownable(_owner) {
        economicEngine = IEconomicEngine(_economicEngine);
        lastParameterUpdate = block.timestamp;
        lastMetricsAggregation = block.timestamp;
    }

    // ============ Core Synchronization Functions ============

    /**
     * @dev Synchronize economic parameters across all chains
     * @param parameters Parameters to synchronize
     * @param targetChains Target chains (empty for all chains)
     */
    function synchronizeParameters(
        CrossChainParameters calldata parameters,
        uint32[] calldata targetChains
    ) external onlyOwner nonReentrant whenNotPaused {
        require(parameters.timestamp > lastParameterUpdate, "Parameters are not newer");

        // Validate parameter integrity
        bytes32 parameterHash = _calculateParameterHash(parameters);
        require(parameterHash == parameters.parameterHash, "Parameter hash mismatch");

        // Update master parameters
        masterParameters = parameters;
        lastParameterUpdate = block.timestamp;

        // Determine target chains
        uint32[] memory chains;
        if (targetChains.length > 0) {
            chains = targetChains;
        } else {
            chains = supportedChains;
        }

        // Send to each target chain
        for (uint256 i = 0; i < chains.length; i++) {
            if (chains[i] != 0 && isSupportedChain[chains[i]]) {
                _sendParameterSync(chains[i], parameters);
            }
        }

        totalMessagesSent += chains.length;
        emit ParametersSynchronized(chains, parameterHash);
    }

    /**
     * @dev Broadcast stability metrics to all chains
     * @param metrics Stability metrics to broadcast
     */
    function broadcastStabilityMetrics(
        StabilityMetrics calldata metrics
    ) external nonReentrant whenNotPaused {
        require(
            msg.sender == address(economicEngine) || msg.sender == owner(),
            "Unauthorized"
        );

        // Update aggregated metrics
        _updateAggregatedMetrics(metrics);

        // Broadcast to all chains
        for (uint256 i = 0; i < supportedChains.length; i++) {
            uint32 chainId = supportedChains[i];
            if (chainId != 0) {
                _sendStabilityUpdate(chainId, metrics);
            }
        }

        totalMessagesSent += supportedChains.length;
    }

    /**
     * @dev Send emergency broadcast to all chains
     * @param broadcast Emergency broadcast data
     */
    function sendEmergencyBroadcast(
        EmergencyBroadcast calldata broadcast
    ) external nonReentrant whenNotPaused {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");

        activeEmergency = broadcast;
        isEmergencyActive = true;

        // Send to all chains
        uint32[] memory chains = supportedChains;
        for (uint256 i = 0; i < chains.length; i++) {
            if (chains[i] != 0) {
                _sendEmergencyBroadcast(chains[i], broadcast);
            }
        }

        totalMessagesSent += chains.length;
        emit EmergencyBroadcastSent(broadcast.emergencyType, chains);
    }

    /**
     * @dev Send intervention command with optional consensus requirement
     * @param command Intervention command data
     * @param targetChains Target chains for intervention
     */
    function sendInterventionCommand(
        InterventionCommand calldata command,
        uint32[] calldata targetChains
    ) external onlyOwner nonReentrant whenNotPaused {
        bytes32 commandId = keccak256(abi.encode(command, block.timestamp));

        if (command.requiresConsensus) {
            pendingInterventions[commandId] = command;
            // Start consensus process
            _initiateConsensus(commandId, command);
        } else {
            // Execute immediately
            _executeInterventionCommand(commandId, command, targetChains);
        }
    }

    /**
     * @dev Batch synchronization for efficiency
     * @param batchData Batch synchronization data
     * @param targetChains Target chains
     */
    function batchSync(
        BatchSyncData calldata batchData,
        uint32[] calldata targetChains
    ) external onlyOwner nonReentrant whenNotPaused {
        require(batchData.parameters.length <= MAX_BATCH_SIZE, "Batch too large");
        require(batchData.batchIndex < batchData.totalBatches, "Invalid batch index");

        // Send batch to each target chain
        for (uint256 i = 0; i < targetChains.length; i++) {
            if (isSupportedChain[targetChains[i]]) {
                _sendBatchSync(targetChains[i], batchData);
            }
        }

        emit BatchSyncCompleted(batchData.batchId, targetChains);
    }

    // ============ LayerZero Message Handling ============

    /**
     * @dev Handle incoming LayerZero messages
     * @param _origin Message origin information
     * @param _message Encoded message data
     */
    function _lzReceive(
        Origin calldata _origin,
        bytes32 /*_guid*/,
        bytes calldata _message,
        address /*_executor*/,
        bytes calldata /*_extraData*/
    ) internal override {
        uint32 fromChain = _origin.srcEid;
        totalMessagesReceived++;

        // Decode message type
        uint8 messageType = uint8(_message[0]);
        bytes calldata messageData = _message[1:];

        // Update chain heartbeat
        chainStatus[fromChain].lastHeartbeat = block.timestamp;

        // Route message based on type
        if (messageType == MSG_PARAMETER_SYNC) {
            _handleParameterSync(fromChain, messageData);
        } else if (messageType == MSG_STABILITY_UPDATE) {
            _handleStabilityUpdate(fromChain, messageData);
        } else if (messageType == MSG_EMERGENCY_BROADCAST) {
            _handleEmergencyBroadcast(fromChain, messageData);
        } else if (messageType == MSG_INTERVENTION_COMMAND) {
            _handleInterventionCommand(fromChain, messageData);
        } else if (messageType == MSG_HEALTH_METRICS) {
            _handleHealthMetrics(fromChain, messageData);
        } else if (messageType == MSG_BATCH_SYNC) {
            _handleBatchSync(fromChain, messageData);
        }

        emit CrossChainMessage(fromChain, uint32(block.chainid), messageType);
    }

    // ============ Message Handlers ============

    function _handleParameterSync(uint32 fromChain, bytes calldata data) internal {
        CrossChainParameters memory parameters = abi.decode(data, (CrossChainParameters));

        // Verify parameter hash
        bytes32 expectedHash = _calculateParameterHash(parameters);
        require(expectedHash == parameters.parameterHash, "Invalid parameter hash");

        // Update chain status
        chainStatus[fromChain].lastParameters = parameters;

        // Apply parameters to local economic engine if newer
        if (parameters.timestamp > lastParameterUpdate) {
            _applyParametersToEngine(parameters);
            lastParameterUpdate = parameters.timestamp;
        }
    }

    function _handleStabilityUpdate(uint32 fromChain, bytes calldata data) internal {
        StabilityMetrics memory metrics = abi.decode(data, (StabilityMetrics));

        // Update chain status
        chainStatus[fromChain].lastMetrics = metrics;

        // Update aggregated metrics
        _updateAggregatedMetrics(metrics);

        emit StabilityMetricsReceived(fromChain, metrics);
    }

    function _handleEmergencyBroadcast(uint32 fromChain, bytes calldata data) internal {
        EmergencyBroadcast memory broadcast = abi.decode(data, (EmergencyBroadcast));

        // Process emergency if more severe than current
        if (!isEmergencyActive || broadcast.severity > activeEmergency.severity) {
            activeEmergency = broadcast;
            isEmergencyActive = true;

            // Apply emergency measures locally
            _applyEmergencyMeasures(broadcast);
        }
    }

    function _handleInterventionCommand(uint32 fromChain, bytes calldata data) internal {
        (bytes32 commandId, InterventionCommand memory command) = abi.decode(data, (bytes32, InterventionCommand));

        if (command.requiresConsensus) {
            // Record consensus vote
            consensusVotes[commandId][fromChain] = true;
            consensusCount[commandId]++;

            // Check if consensus reached
            if (consensusCount[commandId] >= command.consensusThreshold) {
                _executeInterventionCommand(commandId, command, supportedChains);
                emit ConsensusReached(commandId, consensusCount[commandId]);
            }
        } else {
            // Execute immediately
            _executeInterventionCommand(commandId, command, supportedChains);
        }
    }

    function _handleHealthMetrics(uint32 fromChain, bytes calldata data) internal {
        StabilityMetrics memory metrics = abi.decode(data, (StabilityMetrics));
        chainStatus[fromChain].lastMetrics = metrics;
    }

    function _handleBatchSync(uint32 fromChain, bytes calldata data) internal {
        BatchSyncData memory batchData = abi.decode(data, (BatchSyncData));

        // Process batch data
        for (uint256 i = 0; i < batchData.parameters.length; i++) {
            if (batchData.parameters[i].timestamp > lastParameterUpdate) {
                _applyParametersToEngine(batchData.parameters[i]);
            }
        }

        for (uint256 i = 0; i < batchData.metrics.length; i++) {
            _updateAggregatedMetrics(batchData.metrics[i]);
        }
    }

    // ============ Internal Functions ============

    function _sendParameterSync(uint32 targetChain, CrossChainParameters memory parameters) internal {
        bytes memory message = abi.encodePacked(MSG_PARAMETER_SYNC, abi.encode(parameters));
        _sendMessage(targetChain, message);

        // Update sync state
        chainSyncState[targetChain].lastSyncTime = block.timestamp;
        chainSyncState[targetChain].syncNonce++;
        chainSyncState[targetChain].lastParameterHash = parameters.parameterHash;
    }

    function _sendStabilityUpdate(uint32 targetChain, StabilityMetrics memory metrics) internal {
        bytes memory message = abi.encodePacked(MSG_STABILITY_UPDATE, abi.encode(metrics));
        _sendMessage(targetChain, message);
    }

    function _sendEmergencyBroadcast(uint32 targetChain, EmergencyBroadcast memory broadcast) internal {
        bytes memory message = abi.encodePacked(MSG_EMERGENCY_BROADCAST, abi.encode(broadcast));
        _sendMessage(targetChain, message);
    }

    function _sendInterventionCommand(
        uint32 targetChain,
        bytes32 commandId,
        InterventionCommand memory command
    ) internal {
        bytes memory message = abi.encodePacked(MSG_INTERVENTION_COMMAND, abi.encode(commandId, command));
        _sendMessage(targetChain, message);
    }

    function _sendBatchSync(uint32 targetChain, BatchSyncData memory batchData) internal {
        bytes memory message = abi.encodePacked(MSG_BATCH_SYNC, abi.encode(batchData));
        _sendMessage(targetChain, message);
    }

    function _sendMessage(uint32 targetChain, bytes memory message) internal {
        // Create LayerZero V2 options manually (TYPE_3 with executor gas limit)
        bytes memory options = abi.encodePacked(
            uint16(3), // TYPE_3
            uint16(1), // Executor option type
            uint16(16), // Option data length (8 + 8 bytes)
            uint64(200000), // Gas limit
            uint64(0) // Value
        );
        MessagingFee memory fee = _quote(targetChain, message, options, false);

        _lzSend(
            targetChain,
            message,
            options,
            MessagingFee(fee.nativeFee, 0),
            payable(msg.sender)
        );
    }

    function _calculateParameterHash(CrossChainParameters memory parameters) internal pure returns (bytes32) {
        return keccak256(abi.encode(
            parameters.baseDemurrageRate,
            parameters.maxDemurrageRate,
            parameters.stabilityThreshold,
            parameters.fiatDiscountFactor,
            parameters.antiSpeculationPenaltyRate,
            parameters.circuitBreakerThreshold,
            parameters.rebalanceFrequency,
            parameters.timestamp
        ));
    }

    function _applyParametersToEngine(CrossChainParameters memory parameters) internal {
        // Convert to economic engine parameters format
        IEconomicEngine.EconomicParameters memory engineParams = IEconomicEngine.EconomicParameters({
            baseDemurrageRate: parameters.baseDemurrageRate,
            maxDemurrageRate: parameters.maxDemurrageRate,
            stabilityThreshold: parameters.stabilityThreshold,
            fiatDiscountFactor: parameters.fiatDiscountFactor,
            gracePeriodsHours: 48, // Default value
            interventionThreshold: 500, // Default value
            rebalanceFrequency: parameters.rebalanceFrequency,
            emergencyThreshold: parameters.circuitBreakerThreshold
        });

        economicEngine.updateEconomicParameters(engineParams);
    }

    function _updateAggregatedMetrics(StabilityMetrics memory metrics) internal {
        // Simple aggregation - in practice would use more sophisticated algorithms
        if (aggregatedMetrics.timestamp == 0) {
            aggregatedMetrics = metrics;
        } else {
            aggregatedMetrics.priceStability = (aggregatedMetrics.priceStability + metrics.priceStability) / 2;
            aggregatedMetrics.liquidityHealth = (aggregatedMetrics.liquidityHealth + metrics.liquidityHealth) / 2;
            aggregatedMetrics.participationRate = (aggregatedMetrics.participationRate + metrics.participationRate) / 2;
            aggregatedMetrics.reserveRatio = (aggregatedMetrics.reserveRatio + metrics.reserveRatio) / 2;
            aggregatedMetrics.overallHealth = (aggregatedMetrics.overallHealth + metrics.overallHealth) / 2;
        }

        aggregatedMetrics.timestamp = block.timestamp;
        lastMetricsAggregation = block.timestamp;
    }

    function _applyEmergencyMeasures(EmergencyBroadcast memory broadcast) internal {
        if (broadcast.emergencyType == 1) { // Pause operations
            _pause();
        } else if (broadcast.emergencyType == 2) { // Circuit breaker
            // Activate circuit breaker in economic engine
            economicEngine.activateEmergencyMode("Cross-chain emergency");
        }
        // Add more emergency measure types as needed
    }

    function _initiateConsensus(bytes32 commandId, InterventionCommand memory command) internal {
        pendingInterventions[commandId] = command;

        // Send consensus request to all chains
        for (uint256 i = 0; i < supportedChains.length; i++) {
            if (supportedChains[i] != 0) {
                _sendInterventionCommand(supportedChains[i], commandId, command);
            }
        }
    }

    function _executeInterventionCommand(
        bytes32 commandId,
        InterventionCommand memory command,
        uint32[] memory targetChains
    ) internal {
        // Apply intervention locally first
        _applyInterventionLocally(command);

        // Send to target chains if not already done
        for (uint256 i = 0; i < targetChains.length; i++) {
            if (targetChains[i] != uint32(block.chainid)) {
                _sendInterventionCommand(targetChains[i], commandId, command);
            }
        }

        emit InterventionCommandExecuted(commandId, command.commandType);
    }

    function _applyInterventionLocally(InterventionCommand memory command) internal {
        if (command.commandType == 1) { // Parameter adjustment
            // Apply parameter change to economic engine
            // Implementation depends on specific parameter being adjusted
        } else if (command.commandType == 2) { // Emergency activation
            economicEngine.activateEmergencyMode("Intervention command");
        }
        // Add more intervention types as needed
    }

    // ============ Administrative Functions ============

    /**
     * @dev Add supported chain
     * @param chainId Chain ID to add
     */
    function addSupportedChain(uint32 chainId) external onlyOwner {
        require(!isSupportedChain[chainId], "Chain already supported");

        supportedChains.push(chainId);
        isSupportedChain[chainId] = true;

        // Initialize chain status
        chainStatus[chainId] = ChainStatus({
            isActive: true,
            lastHeartbeat: block.timestamp,
            latency: 0,
            failureCount: 0,
            lastMetrics: StabilityMetrics(0, 0, 0, 0, 0, 0, 0),
            lastParameters: CrossChainParameters(0, 0, 0, 0, 0, 0, 0, 0, bytes32(0))
        });

        emit ChainStatusUpdated(chainId, true, 0);
    }

    /**
     * @dev Remove supported chain
     * @param chainId Chain ID to remove
     */
    function removeSupportedChain(uint32 chainId) external onlyOwner {
        require(isSupportedChain[chainId], "Chain not supported");

        // Remove from supported chains array
        for (uint256 i = 0; i < supportedChains.length; i++) {
            if (supportedChains[i] == chainId) {
                supportedChains[i] = supportedChains[supportedChains.length - 1];
                supportedChains.pop();
                break;
            }
        }

        isSupportedChain[chainId] = false;
        chainStatus[chainId].isActive = false;

        emit ChainStatusUpdated(chainId, false, 0);
    }

    /**
     * @dev Add emergency operator
     * @param operator Operator address
     */
    function addEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = true;
    }

    /**
     * @dev Remove emergency operator
     * @param operator Operator address
     */
    function removeEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = false;
    }

    /**
     * @dev Update economic engine reference
     * @param _economicEngine New economic engine address
     */
    function updateEconomicEngine(address _economicEngine) external onlyOwner {
        require(_economicEngine != address(0), "Invalid address");
        economicEngine = IEconomicEngine(_economicEngine);
    }

    // ============ View Functions ============

    function getSupportedChains() external view returns (uint32[] memory) {
        return supportedChains;
    }

    function getChainStatus(uint32 chainId) external view returns (ChainStatus memory) {
        return chainStatus[chainId];
    }

    function getSyncState(uint32 chainId) external view returns (SyncState memory) {
        return chainSyncState[chainId];
    }

    function getMasterParameters() external view returns (CrossChainParameters memory) {
        return masterParameters;
    }

    function getAggregatedMetrics() external view returns (StabilityMetrics memory) {
        return aggregatedMetrics;
    }

    function getActiveEmergency() external view returns (EmergencyBroadcast memory) {
        return activeEmergency;
    }

    function getSyncMetrics() external view returns (
        uint256 messagesSent,
        uint256 messagesReceived,
        uint256 failedSyncs,
        uint256 avgSyncTime
    ) {
        return (totalMessagesSent, totalMessagesReceived, failedSyncAttempts, averageSyncTime);
    }

    // ============ Emergency Functions ============

    /**
     * @dev Emergency pause
     */
    function pause() external {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");
        _pause();
    }

    /**
     * @dev Emergency unpause
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Emergency clear active emergency
     */
    function clearEmergency() external onlyOwner {
        isEmergencyActive = false;
        delete activeEmergency;
    }
}

contracts/core/DemurrageManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "../libs/AdvancedMathUtils.sol";
import "../interfaces/ICaesar.sol";
import "../interfaces/IEconomicEngine.sol";
import "../oracles/GoldPriceOracle.sol";

/**
 * @title DemurrageManager
 * @dev Advanced demurrage system with gold-pegged economic model
 * 
 * SOPHISTICATED ECONOMIC MODEL:
 * - Uses dynamic gold price oracle for reference calculations
 * - Position-based penalties using statistical deviation from gold average
 * - Volatility-adaptive demurrage rates based on gold market conditions
 * - Real-time convergence mechanisms with gold price correlation
 * 
 * Key Features:
 * - Statistical deviation scoring for penalty calculations
 * - Gold market volatility integration for rate adjustments
 * - Cross-chain transaction convergence support
 * - Emergency circuit breakers with gold-based thresholds
 */
contract DemurrageManager is Ownable, ReentrancyGuard, Pausable {
    using AdvancedMathUtils for uint256;

    // State variables
    ICaesar.DemurrageConfig public config;
    GoldPriceOracle public immutable goldOracle;

    mapping(address => uint256) public lastDemurrageApplication;
    mapping(address => bool) public exemptAccounts;

    uint256 public totalDemurrageCollected;
    uint256 public currentStabilityIndex;
    uint256 public lastPriceUpdate;
    // No fixed target - uses dynamic gold reference

    // Gold-based economic parameters
    struct GoldEconomicData {
        uint256 lastGoldUpdate;
        int256 lastDeviationScore;
        uint256 adaptiveRateMultiplier; // Based on gold volatility
        uint256 convergenceTarget;      // Dynamic convergence target
        bool emergencyMode;
    }

    GoldEconomicData public goldEconomicData;

    // Events
    event DemurrageConfigUpdated(
        uint256 baseRate,
        uint256 maxRate,
        uint256 decayInterval,
        uint256 stabilityThreshold
    );
    event DemurrageApplied(address indexed account, uint256 amount);
    event AccountExemptionSet(address indexed account, bool exempt);
    event StabilityIndexUpdated(uint256 index);

    constructor(address initialOwner, address _goldOracle) Ownable(initialOwner) {
        goldOracle = GoldPriceOracle(_goldOracle);
        config = ICaesar.DemurrageConfig({
            baseRate: 1,               // 0.01% base rate (very small)
            maxRate: 10,               // 0.1% maximum rate (small)
            decayInterval: 86400,      // Daily decay
            stabilityThreshold: 100    // 1% stability threshold
        });

        // Initialize gold-based economic data
        goldEconomicData = GoldEconomicData({
            lastGoldUpdate: block.timestamp,
            lastDeviationScore: 0,
            adaptiveRateMultiplier: 1000, // 100% (1.0x) initial
            convergenceTarget: 117e18,     // Initial gold reference ~$117/gram
            emergencyMode: false
        });
    }

    /**
     * @dev Calculate demurrage amount for an account
     * @param account The account to calculate demurrage for
     * @param balance The current balance of the account
     * @param lastActivity Timestamp of last account activity
     * @return demurrageAmount The calculated demurrage amount
     */
    function calculateDemurrage(
        address account,
        uint256 balance,
        uint256 lastActivity
    ) external view returns (uint256 demurrageAmount) {
        if (exemptAccounts[account] || balance == 0) {
            return 0;
        }

        uint256 timeElapsed = block.timestamp - lastActivity;
        if (timeElapsed < config.decayInterval) {
            return 0;
        }

        uint256 effectiveRate = _calculateEffectiveRate();

        // Convert seconds to hours for the decay calculation
        uint256 hoursElapsed = timeElapsed / 3600;
        if (hoursElapsed == 0) {
            return 0; // No demurrage for less than 1 hour
        }

        uint256 originalBalance = balance;
        uint256 decayedBalance = AdvancedMathUtils.calculateExponentialDecay(
            originalBalance,
            effectiveRate,
            hoursElapsed
        );

        // Safety check: decayed balance should never exceed original balance
        if (decayedBalance >= originalBalance) {
            return 0; // No demurrage if calculation error
        }

        uint256 demurrageAmount = originalBalance - decayedBalance;

        // Cap demurrage at 50% of balance to prevent excessive penalties
        uint256 maxDemurrage = originalBalance / 2;
        if (demurrageAmount > maxDemurrage) {
            demurrageAmount = maxDemurrage;
        }

        return demurrageAmount;
    }

    /**
     * @dev Apply demurrage to an account
     * @param account The account to apply demurrage to
     * @param balance The current balance of the account
     * @param lastActivity Timestamp of last account activity
     * @return appliedAmount The amount of demurrage applied
     */
    function applyDemurrage(
        address account,
        uint256 balance,
        uint256 lastActivity
    ) external nonReentrant returns (uint256 appliedAmount) {
        require(msg.sender == address(this) || msg.sender == owner(), "Unauthorized");

        appliedAmount = this.calculateDemurrage(account, balance, lastActivity);

        if (appliedAmount > 0) {
            lastDemurrageApplication[account] = block.timestamp;
            totalDemurrageCollected += appliedAmount;
            emit DemurrageApplied(account, appliedAmount);
        }

        return appliedAmount;
    }

    /**
     * @dev Update stability index based on current market conditions
     * @param currentPrice Current token price
     * @param activeParticipants Number of active participants
     * @param totalHolders Total number of token holders
     */
    function updateStabilityIndex(
        uint256 currentPrice,
        uint256 activeParticipants,
        uint256 totalHolders
    ) external {
        require(msg.sender == owner() || msg.sender == address(this), "Unauthorized");

        currentStabilityIndex = AdvancedMathUtils.calculateStabilityIndex(
            currentPrice,
            goldEconomicData.convergenceTarget,
            activeParticipants,
            totalHolders
        );

        lastPriceUpdate = block.timestamp;
        emit StabilityIndexUpdated(currentStabilityIndex);
    }

    /**
     * @dev Set demurrage configuration
     * @param newConfig The new demurrage configuration
     */
    function setDemurrageConfig(
        ICaesar.DemurrageConfig calldata newConfig
    ) external onlyOwner {
        require(newConfig.baseRate <= newConfig.maxRate, "Invalid rate configuration");
        require(newConfig.maxRate <= 1000, "Max rate too high"); // 10% maximum
        require(newConfig.decayInterval > 0, "Invalid decay interval");

        config = newConfig;

        emit DemurrageConfigUpdated(
            newConfig.baseRate,
            newConfig.maxRate,
            newConfig.decayInterval,
            newConfig.stabilityThreshold
        );
    }

    /**
     * @dev Set account exemption status
     * @param account The account to set exemption for
     * @param exempt Whether the account should be exempt from demurrage
     */
    function setAccountExemption(address account, bool exempt) external onlyOwner {
        exemptAccounts[account] = exempt;
        emit AccountExemptionSet(account, exempt);
    }

    /**
     * @dev Get current effective demurrage rate
     * @return effectiveRate The current effective demurrage rate
     */
    function getCurrentDecayRate() external view returns (uint256 effectiveRate) {
        return _calculateEffectiveRate();
    }

    /**
     * @dev Check if stability conditions are met
     * @return isStable True if conditions are stable
     */
    function isStabilityConditionMet() external view returns (bool isStable) {
        return currentStabilityIndex >= config.stabilityThreshold;
    }

    /**
     * @dev Get total demurrage collected
     * @return total Total demurrage collected
     */
    function getTotalDemurrageCollected() external view returns (uint256 total) {
        return totalDemurrageCollected;
    }

    /**
     * @dev Calculate effective demurrage rate based on stability
     * @return effectiveRate The calculated effective rate
     */
    function _calculateEffectiveRate() internal view returns (uint256 effectiveRate) {
        if (currentStabilityIndex >= 1000) {
            // Perfect stability - minimal demurrage
            return config.baseRate / 10;
        }

        // Linear interpolation between baseRate and maxRate based on stability
        uint256 instabilityFactor = 1000 - currentStabilityIndex;
        uint256 rateRange = config.maxRate - config.baseRate;
        uint256 additionalRate = (rateRange * instabilityFactor) / 1000;

        return config.baseRate + additionalRate;
    }

    /**
     * @dev Emergency function to pause demurrage
     */
    function pauseDemurrage() external onlyOwner {
        config.baseRate = 0;
        config.maxRate = 0;
    }

    /**
     * @dev Get demurrage configuration
     * @return config The current demurrage configuration
     */
    function getDemurrageConfig() external view returns (ICaesar.DemurrageConfig memory) {
        return config;
    }
}

contracts/core/EconomicEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "../libs/AdvancedMathUtils.sol";
import "../interfaces/IEconomicEngine.sol";
import "../oracles/GoldPriceOracle.sol";
import "./DemurrageManager.sol";
import "./AntiSpeculationEngine.sol";
import "./StabilityPool.sol";

/**
 * @title EconomicEngine
 * @dev Sophisticated economic model with dynamic gold-pegged standard deviation bands
 * 
 * CRITICAL ECONOMIC MODEL:
 * - NO FIXED TARGET: Gold price constantly updates with market conditions
 * - STATISTICAL BANDS: Uses standard deviation around moving gold price average
 * - REAL-TIME CALCULATION: Continuous recalculation of penalty/reward zones
 * - VOLATILITY ADAPTIVE: Bands expand/contract with gold market volatility
 * 
 * Key Features:
 * - Dynamic gold price oracle integration
 * - Position-based economics using statistical deviation scores  
 * - Cross-chain transaction convergence with throttling
 * - Circuit breakers with statistically-based triggers
 * - Market pressure calculation with gold price correlation
 */
abstract contract EconomicEngine is Ownable, ReentrancyGuard, Pausable, IEconomicEngine {
    using AdvancedMathUtils for uint256;

    // ============ Constants ============
    uint256 public constant PRECISION = 1e18;
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant SECONDS_PER_HOUR = 3600;
    // Dynamic target - NO FIXED PRICE, uses gold oracle
    uint256 public constant INITIAL_REFERENCE = 1e18; // Initial reference only
    uint256 public constant MAX_DEMURRAGE_RATE = 200; // 2% hourly maximum
    uint256 public constant MIN_DEMURRAGE_RATE = 5;   // 0.05% hourly minimum
    uint256 public constant STABILITY_THRESHOLD = 100; // 1% deviation threshold

    // ============ Core Components ============
    GoldPriceOracle public immutable goldOracle;
    DemurrageManager public immutable demurrageManager;
    AntiSpeculationEngine public immutable antiSpeculationEngine;
    StabilityPool public immutable stabilityPool;

    // ============ Economic State ============
    EconomicParameters public economicParams;
    MarketMetrics public marketMetrics;
    SystemHealth public systemHealth;

    // ============ Gold-Based Economic Metrics ============
    struct GoldBasedMetrics {
        uint256 currentGoldPrice;      // Current gold price from oracle
        uint256 goldMovingAverage;     // Rolling average gold price
        uint256 goldStandardDeviation; // Gold price standard deviation
        int256 caesarDeviationScore;   // Caesar deviation from gold (-5.0 to +5.0)
        uint256 upperStatisticalBand;  // Upper gold-based band
        uint256 lowerStatisticalBand;  // Lower gold-based band
        uint256 marketPressure;        // |caesar_price - gold_avg| pressure
        uint256 lastUpdate;            // Last metrics update
    }

    GoldBasedMetrics public goldMetrics;

    // Cross-chain transaction throttling
    mapping(address => uint256) public lastCrossChainTx;
    mapping(bytes32 => uint256) public txVolumeTracking; // hash(user,timeWindow) => volume
    uint256 public crossChainThrottleWindow = 300; // 5 minutes default
    uint256 public maxCrossChainVolume = 100000e18; // Max volume per window

    // Account-specific data
    mapping(address => AccountEconomicData) public accountData;
    mapping(address => FiatActivityData) public fiatActivity;
    mapping(address => bool) public exemptAccounts;

    // Cross-chain synchronization
    mapping(uint32 => ChainEconomicState) public chainStates;
    mapping(bytes32 => ParameterProposal) public parameterProposals;

    // Real-time monitoring
    EconomicHealthMetrics public healthMetrics;
    uint256 public lastHealthUpdate;
    uint256 public interventionCount;

    // Emergency controls
    bool public emergencyMode;
    uint256 public emergencyTimestamp;
    mapping(address => bool) public emergencyOperators;

    // Events are defined in IEconomicEngine interface

    /**
     * @dev Constructor
     * @param initialOwner Contract owner
     * @param _demurrageManager DemurrageManager contract address
     * @param _antiSpeculationEngine AntiSpeculationEngine contract address  
     * @param _stabilityPool StabilityPool contract address
     */
    constructor(
        address initialOwner,
        address _goldOracle,
        address _demurrageManager,
        address _antiSpeculationEngine,
        address _stabilityPool
    ) Ownable(initialOwner) {
        goldOracle = GoldPriceOracle(_goldOracle);
        demurrageManager = DemurrageManager(_demurrageManager);
        antiSpeculationEngine = AntiSpeculationEngine(_antiSpeculationEngine);
        stabilityPool = StabilityPool(_stabilityPool);

        // Initialize default economic parameters
        economicParams = EconomicParameters({
            baseDemurrageRate: 50,        // 0.5% hourly
            maxDemurrageRate: 200,        // 2% hourly
            stabilityThreshold: 100,      // 1% price deviation
            fiatDiscountFactor: 5000,     // Up to 50% discount
            gracePeriodsHours: 48,        // 48 hours grace period
            interventionThreshold: 500,   // 5% deviation triggers intervention
            rebalanceFrequency: 3600,     // Hourly rebalancing
            emergencyThreshold: 1000      // 10% deviation triggers emergency
        });

        // Initialize system health tracking
        systemHealth = SystemHealth({
            priceStability: 1000,         // Perfect stability initially
            liquidityHealth: 1000,        // Perfect liquidity initially
            participationRate: 0,         // No participants initially
            reserveRatio: 1000,           // 100% reserve ratio initially
            lastUpdate: block.timestamp
        });

        lastHealthUpdate = block.timestamp;

        // Initialize gold-based metrics
        _initializeGoldMetrics();
    }

    // ============ Core Economic Functions ============

    /**
     * @dev Calculate precise demurrage amount with all adjustments
     * @param account Account address
     * @param balance Current balance
     * @return demurrageAmount Calculated demurrage amount
     */
    function calculateDemurrage(
        address account, 
        uint256 balance
    ) external view override returns (uint256 demurrageAmount) {
        if (exemptAccounts[account] || balance == 0) {
            return 0;
        }

        AccountEconomicData memory data = accountData[account];
        if (data.lastActivity == 0) {
            return 0;
        }

        uint256 timeElapsed = block.timestamp - data.lastActivity;
        if (timeElapsed < SECONDS_PER_HOUR) {
            return 0; // No demurrage within first hour
        }

        // Calculate base demurrage rate
        uint256 baseRate = _calculateStabilityAdjustedRate();

        // Apply fiat activity discount
        uint256 discountedRate = _applyFiatActivityDiscount(account, baseRate);

        // Calculate exponential decay: New_Balance = Original_Balance * e^(-rate * time_elapsed)
        uint256 hoursElapsed = timeElapsed / SECONDS_PER_HOUR;
        uint256 decayedBalance = balance.calculateExponentialDecay(discountedRate, hoursElapsed);

        return balance - decayedBalance;
    }

    /**
     * @dev Apply demurrage with mathematical precision
     * @param account Account to apply demurrage to
     * @param balance Current account balance
     * @return appliedAmount Amount of demurrage applied
     */
    function applyDemurrage(
        address account, 
        uint256 balance
    ) external override nonReentrant returns (uint256 appliedAmount) {
        require(msg.sender == owner() || msg.sender == address(this), "Unauthorized");

        appliedAmount = this.calculateDemurrage(account, balance);

        if (appliedAmount > 0) {
            // Update account data
            accountData[account].lastDemurrageApplication = block.timestamp;
            accountData[account].totalDemurragePaid += appliedAmount;

            // Update system metrics
            marketMetrics.totalDemurrageCollected += appliedAmount;

            uint256 currentRate = _calculateStabilityAdjustedRate();
            emit DemurrageApplied(account, appliedAmount, currentRate);
        }

        return appliedAmount;
    }

    /**
     * @dev Analyze transaction for speculation patterns
     * @param account Account making transaction
     * @param amount Transaction amount
     * @param transactionType Type of transaction (0=transfer, 1=buy, 2=sell)
     * @return riskScore Risk score from 0-1000
     * @return penalty Calculated penalty amount
     */
    function analyzeTransactionPattern(
        address account,
        uint256 amount, 
        uint8 transactionType
    ) external override returns (uint256 riskScore, uint256 penalty) {
        AccountEconomicData storage data = accountData[account];

        // Update transaction history
        data.transactionCount++;
        data.totalVolume += amount;

        uint256 timeSinceLastTx = block.timestamp - data.lastTransactionTime;

        // Calculate risk factors
        uint256 frequencyRisk = _calculateFrequencyRisk(account, timeSinceLastTx);
        uint256 volumeRisk = _calculateVolumeRisk(account, amount);
        uint256 patternRisk = _calculatePatternRisk(account, transactionType);

        // Combine risk factors
        riskScore = (frequencyRisk + volumeRisk + patternRisk) / 3;

        // Calculate penalty based on risk score
        if (riskScore > 700) {
            penalty = (amount * economicParams.baseDemurrageRate * riskScore) / (BASIS_POINTS * 100);
        } else if (riskScore > 500) {
            penalty = (amount * economicParams.baseDemurrageRate) / (BASIS_POINTS * 2);
        }

        data.lastTransactionTime = block.timestamp;
        data.riskScore = riskScore;

        if (penalty > 0) {
            emit SpeculationPenaltyApplied(account, penalty, "High risk transaction pattern");
        }

        return (riskScore, penalty);
    }

    /**
     * @dev Apply speculation penalty
     * @param account Account to penalize
     * @param penalty Penalty amount
     * @return success Whether penalty was applied successfully
     */
    function applySpeculationPenalty(
        address account, 
        uint256 penalty
    ) external override nonReentrant returns (bool success) {
        require(msg.sender == owner() || msg.sender == address(this), "Unauthorized");

        if (penalty > 0) {
            accountData[account].totalPenaltiesPaid += penalty;
            marketMetrics.totalPenaltiesCollected += penalty;

            // Transfer penalty to stability pool
            stabilityPool.receivePenalty(penalty, account);

            emit SpeculationPenaltyApplied(account, penalty, "Applied speculation penalty");
            return true;
        }

        return false;
    }

    /**
     * @dev Maintain peg stability through automated interventions
     * @return action Type of stability action taken
     */
    function maintainPegStability() external override returns (StabilityAction action) {
        uint256 currentPrice = _getCurrentPrice();
        uint256 priceDeviation = _calculatePriceDeviation(currentPrice);

        if (priceDeviation > economicParams.emergencyThreshold) {
            return _executeEmergencyIntervention(currentPrice);
        } else if (priceDeviation > economicParams.interventionThreshold) {
            return _executeStandardIntervention(currentPrice);
        }

        return StabilityAction.NO_ACTION;
    }

    /**
     * @dev Rebalance reserves across chains and pools
     * @return operation Details of rebalancing operation
     */
    function rebalanceReserves() external override returns (ReserveOperation memory operation) {
        require(
            block.timestamp >= systemHealth.lastUpdate + economicParams.rebalanceFrequency,
            "Rebalancing too frequent"
        );

        // Calculate required reserves
        uint256 totalSupply = _getTotalSupply();
        uint256 requiredReserves = totalSupply; // 100% backing
        uint256 currentReserves = _getTotalReserves();

        if (currentReserves < requiredReserves) {
            // Need to add reserves
            uint256 deficit = requiredReserves - currentReserves;
            operation = ReserveOperation({
                operationType: ReserveOperationType.ADD_RESERVES,
                amount: deficit,
                targetChain: 0, // Local chain
                timestamp: block.timestamp,
                success: true
            });

            emit StabilityIntervention(InterventionType.RESERVE_ADDITION, deficit);
        } else if (currentReserves > requiredReserves * 120 / 100) {
            // Excess reserves, can remove some
            uint256 excess = currentReserves - requiredReserves;
            operation = ReserveOperation({
                operationType: ReserveOperationType.REMOVE_RESERVES,
                amount: excess,
                targetChain: 0,
                timestamp: block.timestamp,
                success: true
            });

            emit StabilityIntervention(InterventionType.RESERVE_REMOVAL, excess);
        }

        systemHealth.lastUpdate = block.timestamp;
        return operation;
    }

    /**
     * @dev Update economic parameters through governance
     * @param params New economic parameters
     */
    function updateEconomicParameters(
        EconomicParameters calldata params
    ) external override onlyOwner {
        require(params.baseDemurrageRate <= params.maxDemurrageRate, "Invalid demurrage rates");
        require(params.maxDemurrageRate <= MAX_DEMURRAGE_RATE, "Demurrage rate too high");
        require(params.fiatDiscountFactor <= BASIS_POINTS, "Invalid discount factor");
        require(params.gracePeriodsHours <= 168, "Grace period too long"); // Max 1 week

        economicParams = params;
        emit EconomicParametersUpdated(params);
    }

    /**
     * @dev Monitor and update economic health metrics
     * @return metrics Current health metrics
     */
    function monitorEconomicHealth() external override returns (HealthMetrics memory metrics) {
        uint256 currentPrice = _getCurrentPrice();
        uint256 totalSupply = _getTotalSupply();
        uint256 activeAccounts = _getActiveAccountCount();
        uint256 totalAccounts = _getTotalAccountCount();

        // Calculate health metrics
        systemHealth.priceStability = _calculatePriceStability(currentPrice);
        systemHealth.liquidityHealth = _calculateLiquidityHealth();
        systemHealth.participationRate = activeAccounts > 0 ? 
            (activeAccounts * 1000) / totalAccounts : 0;
        systemHealth.reserveRatio = _calculateReserveRatio();
        systemHealth.lastUpdate = block.timestamp;

        // Update comprehensive health metrics
        healthMetrics = EconomicHealthMetrics({
            overallHealth: _calculateOverallHealth(),
            priceStability: systemHealth.priceStability,
            liquidityHealth: systemHealth.liquidityHealth,
            participationRate: systemHealth.participationRate,
            reserveRatio: systemHealth.reserveRatio,
            demurrageEfficiency: _calculateDemurrageEfficiency(),
            antiSpeculationEffectiveness: _calculateAntiSpeculationEffectiveness(),
            systemStress: _calculateSystemStress(),
            timestamp: block.timestamp
        });

        lastHealthUpdate = block.timestamp;
        emit HealthMetricsUpdated(healthMetrics);

        return HealthMetrics({
            overallHealth: healthMetrics.overallHealth,
            priceStability: healthMetrics.priceStability,
            liquidityHealth: healthMetrics.liquidityHealth,
            participationRate: healthMetrics.participationRate,
            lastUpdate: healthMetrics.timestamp
        });
    }

    // ============ Fiat Integration Functions ============

    /**
     * @dev Record fiat activity for demurrage discount calculation
     * @param account Account with fiat activity
     * @param amount Amount of fiat activity
     * @param activityType Type of fiat activity (0=purchase, 1=redemption)
     */
    function recordFiatActivity(
        address account,
        uint256 amount,
        uint8 activityType
    ) external override {
        require(msg.sender == owner() || emergencyOperators[msg.sender], "Unauthorized");

        FiatActivityData storage activity = fiatActivity[account];
        activity.totalFiatVolume += amount;
        activity.lastFiatActivity = block.timestamp;
        activity.activityCount++;

        // Calculate discount eligibility
        uint256 timeSinceLastActivity = block.timestamp - activity.lastFiatActivity;
        if (timeSinceLastActivity <= 24 hours) {
            activity.discountEligible = true;
            activity.discountPercentage = _calculateFiatDiscount(activity.totalFiatVolume);
        } else {
            activity.discountEligible = false;
            activity.discountPercentage = 0;
        }
    }

    /**
     * @dev Validate fiat backing in real-time
     * @param expectedBacking Expected backing amount
     * @return isValid Whether backing is valid
     * @return actualBacking Actual backing amount
     */
    function validateFiatBacking(
        uint256 expectedBacking
    ) external override view returns (bool isValid, uint256 actualBacking) {
        // This would integrate with Stripe Connect API
        // For now, return simplified validation
        actualBacking = _getTotalReserves();
        isValid = actualBacking >= expectedBacking * 95 / 100; // 5% tolerance

        return (isValid, actualBacking);
    }

    // ============ Cross-Chain Functions ============

    /**
     * @dev Synchronize economic parameters across chains
     * @param chainId Target chain ID
     * @param parameters Parameters to synchronize
     */
    function synchronizeParameters(
        uint32 chainId,
        EconomicParameters calldata parameters
    ) external override {
        require(msg.sender == owner(), "Unauthorized");

        ChainEconomicState storage state = chainStates[chainId];
        state.parameters = parameters;
        state.lastSync = block.timestamp;
        state.syncHash = keccak256(abi.encode(parameters));

        emit CrossChainSync(chainId, state.syncHash);
    }

    // ============ Emergency Functions ============

    /**
     * @dev Activate emergency mode
     * @param reason Reason for emergency activation
     */
    function activateEmergencyMode(string calldata reason) external {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");

        emergencyMode = true;
        emergencyTimestamp = block.timestamp;

        // Pause demurrage during emergency
        economicParams.baseDemurrageRate = 0;
        economicParams.maxDemurrageRate = 0;

        emit EmergencyModeActivated(msg.sender, reason);
    }

    /**
     * @dev Deactivate emergency mode
     */
    function deactivateEmergencyMode() external onlyOwner {
        require(emergencyMode, "Not in emergency mode");

        emergencyMode = false;
        emergencyTimestamp = 0;

        // Restore normal demurrage rates
        economicParams.baseDemurrageRate = 50; // 0.5%
        economicParams.maxDemurrageRate = 200; // 2%
    }

    // ============ View Functions ============

    function getEconomicParameters() external view override returns (EconomicParameters memory) {
        return economicParams;
    }

    function getSystemHealth() external view override returns (SystemHealth memory) {
        return systemHealth;
    }

    function getHealthMetrics() external view override returns (EconomicHealthMetrics memory) {
        return healthMetrics;
    }

    function getAccountEconomicData(address account) external view returns (AccountEconomicData memory) {
        return accountData[account];
    }

    function getFiatActivityData(address account) external view returns (FiatActivityData memory) {
        return fiatActivity[account];
    }

    // ============ Internal Functions ============

    function _calculateStabilityAdjustedRate() internal view returns (uint256) {
        uint256 priceStability = systemHealth.priceStability;
        uint256 baseRate = economicParams.baseDemurrageRate;
        uint256 maxRate = economicParams.maxDemurrageRate;

        if (priceStability >= 950) {
            return baseRate / 2; // Minimal demurrage when stable
        } else if (priceStability <= 500) {
            return maxRate; // Maximum demurrage when unstable
        }

        // Linear interpolation based on stability
        uint256 instability = 1000 - priceStability;
        uint256 rateIncrease = (maxRate - baseRate) * instability / 500;

        return baseRate + rateIncrease;
    }

    function _applyFiatActivityDiscount(address account, uint256 rate) internal view returns (uint256) {
        FiatActivityData memory activity = fiatActivity[account];

        if (!activity.discountEligible) {
            return rate;
        }

        uint256 discountAmount = (rate * activity.discountPercentage) / BASIS_POINTS;
        return rate > discountAmount ? rate - discountAmount : 0;
    }

    function _calculateFrequencyRisk(address account, uint256 timeSinceLastTx) internal view returns (uint256) {
        if (timeSinceLastTx >= 24 hours) {
            return 0; // No risk for infrequent transactions
        } else if (timeSinceLastTx >= 1 hours) {
            return 200; // Low risk
        } else if (timeSinceLastTx >= 10 minutes) {
            return 500; // Medium risk
        } else {
            return 900; // High risk for rapid transactions
        }
    }

    function _calculateVolumeRisk(address account, uint256 amount) internal view returns (uint256) {
        AccountEconomicData memory data = accountData[account];

        if (data.transactionCount == 0) {
            return 0;
        }

        uint256 averageVolume = data.totalVolume / data.transactionCount;

        if (amount <= averageVolume) {
            return 0;
        } else if (amount <= averageVolume * 2) {
            return 200;
        } else if (amount <= averageVolume * 5) {
            return 500;
        } else {
            return 800; // High volume risk
        }
    }

    function _calculatePatternRisk(address account, uint8 transactionType) internal view returns (uint256) {
        // This would implement ML-based pattern recognition
        // For now, simplified pattern detection
        AccountEconomicData memory data = accountData[account];

        if (data.riskScore > 700) {
            return 600; // Previously flagged account
        }

        return 100; // Default low pattern risk
    }

    function _getCurrentPrice() internal view returns (uint256) {
        // This would integrate with Caesar price oracles
        // For now, return gold reference with slight variation based on market conditions
        uint256 goldReference = goldMetrics.goldMovingAverage > 0 ? 
            goldMetrics.goldMovingAverage : INITIAL_REFERENCE;

        // Add small market pressure adjustment
        uint256 pressureAdjustment = (goldReference * goldMetrics.marketPressure) / 10000; // 0.01% per pressure point

        return goldReference + pressureAdjustment;
    }

    function _calculatePriceDeviation(uint256 currentPrice) internal view returns (uint256) {
        // Use dynamic gold reference instead of fixed target
        uint256 goldReference = goldMetrics.goldMovingAverage > 0 ? 
            goldMetrics.goldMovingAverage : INITIAL_REFERENCE;

        if (currentPrice >= goldReference) {
            return ((currentPrice - goldReference) * BASIS_POINTS) / goldReference;
        } else {
            return ((goldReference - currentPrice) * BASIS_POINTS) / goldReference;
        }
    }

    function _executeEmergencyIntervention(uint256 currentPrice) internal returns (StabilityAction) {
        interventionCount++;

        uint256 goldReference = goldMetrics.goldMovingAverage > 0 ? goldMetrics.goldMovingAverage : INITIAL_REFERENCE;
        if (currentPrice > goldReference) {
            // Price too high, increase supply
            emit StabilityIntervention(InterventionType.SUPPLY_INCREASE, 0);
            return StabilityAction.INCREASE_SUPPLY;
        } else {
            // Price too low, decrease supply
            emit StabilityIntervention(InterventionType.SUPPLY_DECREASE, 0);
            return StabilityAction.DECREASE_SUPPLY;
        }
    }

    function _executeStandardIntervention(uint256 currentPrice) internal returns (StabilityAction) {
        // Implement standard intervention logic
        return StabilityAction.ADJUST_RATES;
    }

    function _getTotalSupply() internal view returns (uint256) {
        // This would call the token contract
        return 1000000 * 1e18; // Placeholder
    }

    function _getTotalReserves() internal view returns (uint256) {
        // This would query actual reserve balances
        return 1000000 * 1e18; // Placeholder
    }

    function _getActiveAccountCount() internal view returns (uint256) {
        // This would count accounts active in last 24 hours
        return 100; // Placeholder
    }

    function _getTotalAccountCount() internal view returns (uint256) {
        // This would return total unique accounts
        return 1000; // Placeholder
    }

    function _calculatePriceStability(uint256 currentPrice) internal view returns (uint256) {
        // Use gold-based deviation calculation
        int256 deviationScore = goldOracle.calculateDeviationScore(currentPrice);
        uint256 absDeviation = deviationScore < 0 ? uint256(-deviationScore) : uint256(deviationScore);

        // Convert to stability score: higher deviation = lower stability
        // 1 std dev = 200 stability points lost, cap at 0
        uint256 stabilityLoss = (absDeviation * 200) / PRECISION;

        return stabilityLoss > 1000 ? 0 : 1000 - stabilityLoss;
    }

    function _calculateLiquidityHealth() internal view returns (uint256) {
        // Calculate based on trading volume and depth
        return 800; // Placeholder
    }

    function _calculateReserveRatio() internal view returns (uint256) {
        uint256 reserves = _getTotalReserves();
        uint256 supply = _getTotalSupply();
        return supply > 0 ? (reserves * 1000) / supply : 0;
    }

    function _calculateOverallHealth() internal view returns (uint256) {
        return (systemHealth.priceStability + 
                systemHealth.liquidityHealth + 
                systemHealth.participationRate + 
                systemHealth.reserveRatio) / 4;
    }

    function _calculateDemurrageEfficiency() internal view returns (uint256) {
        // Calculate how effectively demurrage encourages circulation
        return 750; // Placeholder
    }

    function _calculateAntiSpeculationEffectiveness() internal view returns (uint256) {
        // Calculate how well anti-speculation measures work
        return 850; // Placeholder
    }

    function _calculateSystemStress() internal view returns (uint256) {
        // Calculate overall system stress level
        uint256 priceStress = 1000 - systemHealth.priceStability;
        uint256 liquidityStress = 1000 - systemHealth.liquidityHealth;
        return (priceStress + liquidityStress) / 2;
    }

    function _calculateFiatDiscount(uint256 volume) internal view returns (uint256) {
        // Calculate discount percentage based on fiat activity volume
        if (volume >= 10000 * 1e18) {
            return economicParams.fiatDiscountFactor; // Maximum discount
        } else if (volume >= 1000 * 1e18) {
            return economicParams.fiatDiscountFactor / 2; // Half discount
        } else {
            return economicParams.fiatDiscountFactor / 4; // Quarter discount
        }
    }

    // ============ Gold-Based Economic Functions ============

    /**
     * @dev Initialize gold-based metrics on contract deployment
     */
    function _initializeGoldMetrics() internal {
        (uint256 goldPrice, , ) = goldOracle.getCurrentGoldPrice();
        (uint256 average, uint256 stdDev, uint256 upperBand, uint256 lowerBand, ) = goldOracle.getStatisticalBands();

        goldMetrics = GoldBasedMetrics({
            currentGoldPrice: goldPrice,
            goldMovingAverage: average,
            goldStandardDeviation: stdDev,
            caesarDeviationScore: 0, // Initial perfect alignment
            upperStatisticalBand: upperBand,
            lowerStatisticalBand: lowerBand,
            marketPressure: 0,
            lastUpdate: block.timestamp
        });
    }

    /**
     * @dev Update gold-based metrics with real-time data
     * @param caesarPrice Current Caesar token price
     * @return updated Whether metrics were successfully updated
     */
    function updateGoldBasedMetrics(uint256 caesarPrice) external returns (bool updated) {
        require(msg.sender == owner() || msg.sender == address(this), "Unauthorized");

        // Get current gold data
        (uint256 goldPrice, uint256 confidence, ) = goldOracle.getCurrentGoldPrice();
        (uint256 average, uint256 stdDev, uint256 upperBand, uint256 lowerBand, ) = goldOracle.getStatisticalBands();

        // Skip update if gold oracle unhealthy
        if (confidence < 500 || !goldOracle.isHealthy()) {
            return false;
        }

        // Calculate Caesar deviation from gold average
        int256 deviationScore = goldOracle.calculateDeviationScore(caesarPrice);

        // Calculate market pressure: |caesar_price - gold_moving_average|
        uint256 marketPressure = caesarPrice > average ? 
            ((caesarPrice - average) * 1000) / average :
            ((average - caesarPrice) * 1000) / average;

        // Update metrics
        goldMetrics = GoldBasedMetrics({
            currentGoldPrice: goldPrice,
            goldMovingAverage: average,
            goldStandardDeviation: stdDev,
            caesarDeviationScore: deviationScore,
            upperStatisticalBand: upperBand,
            lowerStatisticalBand: lowerBand,
            marketPressure: marketPressure,
            lastUpdate: block.timestamp
        });

        return true;
    }

    /**
     * @dev Calculate position-based penalty using statistical deviation
     * From concept: Penalty_Rate = base_rate * (1 + abs(Deviation_Score))
     * @param account Account to calculate penalty for
     * @param balance Account balance
     * @param caesarPrice Current Caesar price
     * @return penalty Calculated penalty amount
     */
    function calculatePositionBasedPenalty(
        address account,
        uint256 balance,
        uint256 caesarPrice
    ) external view returns (uint256 penalty) {
        if (exemptAccounts[account] || balance == 0) {
            return 0;
        }

        // Get deviation score
        int256 deviationScore = goldOracle.calculateDeviationScore(caesarPrice);
        uint256 absDeviation = deviationScore < 0 ? uint256(-deviationScore) : uint256(deviationScore);

        // Base penalty rate (from economic parameters)
        uint256 baseRate = economicParams.baseDemurrageRate;

        // Calculate penalty rate: base_rate * (1 + abs(deviation_score))
        uint256 penaltyRate = baseRate * (PRECISION + absDeviation) / PRECISION;

        // Cap penalty rate at maximum
        if (penaltyRate > economicParams.maxDemurrageRate) {
            penaltyRate = economicParams.maxDemurrageRate;
        }

        // Calculate time-based penalty
        AccountEconomicData memory data = accountData[account];
        if (data.lastActivity == 0) {
            return 0;
        }

        uint256 timeElapsed = block.timestamp - data.lastActivity;
        if (timeElapsed < SECONDS_PER_HOUR) {
            return 0;
        }

        uint256 hoursElapsed = timeElapsed / SECONDS_PER_HOUR;

        // Apply penalty: balance * rate * time
        penalty = (balance * penaltyRate * hoursElapsed) / (BASIS_POINTS * 100);

        return penalty;
    }

    /**
     * @dev Calculate dynamic transaction fee based on market pressure
     * From concept: Enhanced market pressure with gold price correlation
     * @param amount Transaction amount
     * @param transactionType Type of transaction
     * @return fee Dynamic transaction fee
     */
    function calculateDynamicTransactionFee(
        uint256 amount,
        uint8 transactionType
    ) external view returns (uint256 fee) {
        // Base fee (0.1%)
        uint256 baseFee = (amount * 10) / BASIS_POINTS;

        // Market pressure factor
        uint256 pressureFactor = goldMetrics.marketPressure;

        // Volatility factor from gold oracle
        GoldPriceOracle.MarketConditions memory conditions = goldOracle.getMarketConditions();
        uint256 volatility = conditions.volatilityIndex;

        // Enhanced fee calculation
        uint256 pressureMultiplier = PRECISION + (pressureFactor * PRECISION / 1000);
        uint256 volatilityMultiplier = PRECISION + (volatility * PRECISION / 2000); // Half weight

        fee = (baseFee * pressureMultiplier * volatilityMultiplier) / (PRECISION * PRECISION);

        // Cap fee at 2% of transaction
        uint256 maxFee = (amount * 200) / BASIS_POINTS;
        if (fee > maxFee) {
            fee = maxFee;
        }

        return fee;
    }

    /**
     * @dev Check circuit breaker conditions with gold-based thresholds
     * From concept: CB(t) with dynamic gold reference
     * @param caesarPrice Current Caesar price
     * @return halt Whether to halt trading
     * @return emergency Whether to activate emergency measures
     * @return rebase Whether to trigger rebase
     */
    function checkGoldBasedCircuitBreakers(uint256 caesarPrice) 
        external 
        view 
        returns (bool halt, bool emergency, bool rebase) 
    {
        int256 deviationScore = goldOracle.calculateDeviationScore(caesarPrice);
        uint256 absDeviation = deviationScore < 0 ? uint256(-deviationScore) : uint256(deviationScore);

        // Convert to standard deviation units (18 decimals = 1.0 std dev)
        uint256 stdDevUnits = absDeviation / PRECISION;

        // Circuit breaker thresholds based on standard deviations
        halt = stdDevUnits >= 3; // Halt at 3+ standard deviations
        emergency = stdDevUnits >= 2; // Emergency at 2+ standard deviations  
        rebase = stdDevUnits >= 4; // Rebase at 4+ standard deviations

        return (halt, emergency, rebase);
    }

    /**
     * @dev Apply cross-chain transaction throttling
     * @param user User address
     * @param amount Transaction amount
     * @return allowed Whether transaction is allowed
     * @return reason Reason if not allowed
     */
    function applyCrossChainThrottling(
        address user,
        uint256 amount
    ) external returns (bool allowed, string memory reason) {
        require(msg.sender == owner() || msg.sender == address(this), "Unauthorized");

        // Check time-based throttling
        if (block.timestamp - lastCrossChainTx[user] < crossChainThrottleWindow) {
            return (false, "Transaction too frequent");
        }

        // Check volume-based throttling
        uint256 timeWindow = block.timestamp / crossChainThrottleWindow;
        bytes32 volumeKey = keccak256(abi.encodePacked(user, timeWindow));

        if (txVolumeTracking[volumeKey] + amount > maxCrossChainVolume) {
            return (false, "Volume limit exceeded");
        }

        // Update tracking
        lastCrossChainTx[user] = block.timestamp;
        txVolumeTracking[volumeKey] += amount;

        return (true, "");
    }

    /**
     * @dev Get current gold-based economic metrics
     * @return metrics Current gold-based metrics
     */
    function getGoldBasedMetrics() external view returns (GoldBasedMetrics memory metrics) {
        return goldMetrics;
    }

    /**
     * @dev Calculate network utility score with cross-chain emphasis
     * From concept: Enhanced network utility with cross-chain transfers
     * @param dailyTransactions Daily transaction count
     * @param crossChainTransfers Cross-chain transfer count
     * @return score Network utility score (0-1000)
     */
    function calculateNetworkUtilityScore(
        uint256 dailyTransactions,
        uint256 crossChainTransfers
    ) external pure returns (uint256 score) {
        // Target metrics
        uint256 targetDailyTx = 500000; // 500k daily transactions
        uint256 targetCrossChain = 50000; // 50k cross-chain transfers

        // Base transaction utility (60% weight)
        uint256 txUtility = dailyTransactions > targetDailyTx ? 1000 : 
            (dailyTransactions * 1000) / targetDailyTx;

        // Cross-chain utility (40% weight)
        uint256 crossChainUtility = crossChainTransfers > targetCrossChain ? 1000 :
            (crossChainTransfers * 1000) / targetCrossChain;

        // Weighted combination
        score = (txUtility * 60 + crossChainUtility * 40) / 100;

        return score > 1000 ? 1000 : score;
    }

    /**
     * @dev Update cross-chain throttling parameters
     * @param windowSeconds New throttle window in seconds
     * @param maxVolume New maximum volume per window
     */
    function updateThrottlingParameters(
        uint256 windowSeconds,
        uint256 maxVolume
    ) external onlyOwner {
        require(windowSeconds >= 60 && windowSeconds <= 3600, "Invalid window"); // 1 min to 1 hour
        require(maxVolume > 0, "Invalid volume");

        crossChainThrottleWindow = windowSeconds;
        maxCrossChainVolume = maxVolume;
    }
}

contracts/core/StabilityPool.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../libs/AdvancedMathUtils.sol";
import "../interfaces/IStabilityPool.sol";
import "../oracles/GoldPriceOracle.sol";

/**
 * @title StabilityPool  
 * @dev Automated stability pool with penalty collection, reserve management,
 * and emergency intervention mechanisms for Caesar Token economic stability
 */
contract StabilityPool is Ownable, ReentrancyGuard, Pausable, IStabilityPool {
    using SafeERC20 for IERC20;
    using AdvancedMathUtils for uint256;

    // ============ Constants ============
    uint256 public constant PRECISION = 1e18;
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MAX_RESERVE_RATIO = 2000; // 200% maximum
    uint256 public constant MIN_RESERVE_RATIO = 800;  // 80% minimum  
    uint256 public constant TARGET_RESERVE_RATIO = 1000; // 100% target
    uint256 public constant REBALANCE_THRESHOLD = 50; // 5% deviation threshold

    // ============ State Variables ============
    IERC20 public immutable gateToken;
    IERC20 public immutable usdcToken;

    // Pool composition
    uint256 public totalPoolBalance;
    uint256 public penaltyFunds;
    uint256 public demurrageFunds;
    uint256 public reserveFunds;
    uint256 public emergencyFunds;

    // Reserve management
    mapping(uint32 => ReserveState) public chainReserves;
    uint256 public totalReserves;
    uint256 public lastRebalance;
    uint256 public rebalanceFrequency = 1 hours;

    // Stability metrics
    uint256 public stabilityIndex;
    uint256 public lastStabilityUpdate;
    uint256 public interventionCount;

    // Emergency controls
    bool public emergencyMode;
    uint256 public emergencyThreshold = 1000; // 10% deviation
    mapping(address => bool) public emergencyOperators;

    // Multi-chain support
    mapping(uint32 => bool) public supportedChains;
    mapping(uint32 => address) public chainPoolAddresses;

    // AMM integration
    address public ammRouter;
    uint256 public maxSlippage = 300; // 3%

    // Events are defined in IStabilityPool interface

    /**
     * @dev Constructor
     * @param initialOwner Contract owner
     * @param _gateToken CAESAR token address
     * @param _usdcToken USDC token address
     */
    constructor(
        address initialOwner,
        address _gateToken,
        address _usdcToken
    ) Ownable(initialOwner) {
        gateToken = IERC20(_gateToken);
        usdcToken = IERC20(_usdcToken);

        stabilityIndex = 1000; // Perfect stability initially
        lastStabilityUpdate = block.timestamp;
        lastRebalance = block.timestamp;
    }

    // ============ Fund Reception Functions ============

    /**
     * @dev Receive penalty funds from anti-speculation engine
     * @param amount Amount of penalty received
     * @param account Account that was penalized
     */
    function receivePenalty(uint256 amount, address account) external override nonReentrant {
        require(msg.sender == owner() || emergencyOperators[msg.sender], "Unauthorized");

        penaltyFunds += amount;
        totalPoolBalance += amount;

        // Update stability based on penalty collection
        _updateStabilityIndex();

        emit FundsReceived(FundType.PENALTY, amount, account);
    }

    /**
     * @dev Receive demurrage funds from demurrage system
     * @param amount Amount of demurrage received
     * @param account Account that paid demurrage
     */
    function receiveDemurrage(uint256 amount, address account) external override nonReentrant {
        require(msg.sender == owner() || emergencyOperators[msg.sender], "Unauthorized");

        demurrageFunds += amount;
        totalPoolBalance += amount;

        // Update stability metrics
        _updateStabilityIndex();

        emit FundsReceived(FundType.DEMURRAGE, amount, account);
    }

    /**
     * @dev Contribute reserves to the pool
     * @param amount Amount to contribute
     */
    function contributeReserves(uint256 amount) external override nonReentrant whenNotPaused {
        require(amount > 0, "Amount must be positive");

        usdcToken.safeTransferFrom(msg.sender, address(this), amount);

        reserveFunds += amount;
        totalReserves += amount;
        totalPoolBalance += amount;

        emit FundsReceived(FundType.RESERVE, amount, msg.sender);
    }

    // ============ Stability Functions ============

    /**
     * @dev Execute automated market maker intervention
     * @param currentPrice Current CAESAR token price
     * @param targetPrice Target price (1 USD)
     * @return intervention Details of intervention executed
     */
    function executeAMMIntervention(
        uint256 currentPrice,
        uint256 targetPrice
    ) external override returns (AMMIntervention memory intervention) {
        require(msg.sender == owner() || emergencyOperators[msg.sender], "Unauthorized");
        require(ammRouter != address(0), "AMM router not set");

        uint256 priceDeviation = _calculatePriceDeviation(currentPrice, targetPrice);

        if (priceDeviation < REBALANCE_THRESHOLD) {
            return AMMIntervention({
                executed: false,
                tradeType: TradeType.NO_TRADE,
                amountIn: 0,
                amountOut: 0,
                timestamp: block.timestamp
            });
        }

        if (currentPrice > targetPrice) {
            // Price too high, sell GATE for USDC
            intervention = _executeSellPressure(currentPrice, targetPrice, priceDeviation);
        } else {
            // Price too low, buy GATE with USDC
            intervention = _executeBuyPressure(currentPrice, targetPrice, priceDeviation);
        }

        interventionCount++;
        _updateStabilityIndex();

        return intervention;
    }

    /**
     * @dev Rebalance reserves across supported chains
     * @param targetChain Chain to rebalance with
     * @return operation Details of rebalancing operation
     */
    function rebalanceChainReserves(uint32 targetChain) external override returns (RebalanceOperation memory operation) {
        require(supportedChains[targetChain], "Chain not supported");
        require(block.timestamp >= lastRebalance + rebalanceFrequency, "Rebalancing too frequent");

        ReserveState storage localState = chainReserves[0]; // Local chain
        ReserveState storage targetState = chainReserves[targetChain];

        // Calculate optimal distribution
        uint256 totalChainReserves = localState.balance + targetState.balance;
        uint256 optimalLocalAmount = totalChainReserves / 2;

        if (localState.balance > optimalLocalAmount + (optimalLocalAmount * REBALANCE_THRESHOLD / BASIS_POINTS)) {
            // Send excess to target chain
            uint256 excessAmount = localState.balance - optimalLocalAmount;
            operation = _transferToChain(targetChain, excessAmount);
        } else if (localState.balance < optimalLocalAmount - (optimalLocalAmount * REBALANCE_THRESHOLD / BASIS_POINTS)) {
            // Request from target chain
            uint256 deficitAmount = optimalLocalAmount - localState.balance;
            operation = _requestFromChain(targetChain, deficitAmount);
        }

        lastRebalance = block.timestamp;
        return operation;
    }

    /**
     * @dev Execute emergency intervention
     * @param reason Reason for emergency
     * @param interventionType Type of intervention
     * @return success Whether intervention succeeded
     */
    function executeEmergencyIntervention(
        string calldata reason,
        EmergencyType interventionType
    ) external override returns (bool success) {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");

        if (interventionType == EmergencyType.PAUSE_TRADING) {
            _pause();
            success = true;
        } else if (interventionType == EmergencyType.CIRCUIT_BREAKER) {
            emergencyMode = true;
            success = true;
        } else if (interventionType == EmergencyType.RESERVE_INJECTION) {
            success = _executeReserveInjection();
        } else if (interventionType == EmergencyType.SUPPLY_ADJUSTMENT) {
            success = _executeSupplyAdjustment();
        }

        if (success) {
            emit EmergencyIntervention(reason, 0);
        }

        return success;
    }

    // ============ Reserve Management ============

    /**
     * @dev Calculate current reserve ratio
     * @return ratio Current reserve ratio (basis points)
     */
    function calculateReserveRatio() external view override returns (uint256 ratio) {
        uint256 totalSupply = _getTotalSupply();
        return totalSupply > 0 ? (totalReserves * BASIS_POINTS) / totalSupply : BASIS_POINTS;
    }

    /**
     * @dev Get stability metrics
     * @return metrics Current stability metrics
     */
    function getStabilityMetrics() external view override returns (StabilityMetrics memory metrics) {
        return StabilityMetrics({
            stabilityIndex: stabilityIndex,
            reserveRatio: this.calculateReserveRatio(),
            interventionCount: interventionCount,
            lastUpdate: lastStabilityUpdate,
            emergencyMode: emergencyMode
        });
    }

    /**
     * @dev Get pool composition
     * @return composition Current pool fund composition
     */
    function getPoolComposition() external view override returns (PoolComposition memory composition) {
        return PoolComposition({
            totalBalance: totalPoolBalance,
            penaltyFunds: penaltyFunds,
            demurrageFunds: demurrageFunds,
            reserveFunds: reserveFunds,
            emergencyFunds: emergencyFunds
        });
    }

    /**
     * @dev Get chain reserve state
     * @param chainId Chain ID
     * @return state Reserve state for chain
     */
    function getChainReserveState(uint32 chainId) external view returns (ReserveState memory state) {
        return chainReserves[chainId];
    }

    // ============ Administrative Functions ============

    /**
     * @dev Set AMM router address
     * @param _ammRouter AMM router address
     */
    function setAMMRouter(address _ammRouter) external onlyOwner {
        require(_ammRouter != address(0), "Invalid router address");
        ammRouter = _ammRouter;
    }

    /**
     * @dev Add supported chain
     * @param chainId Chain ID to add
     * @param poolAddress Pool address on target chain
     */
    function addSupportedChain(uint32 chainId, address poolAddress) external onlyOwner {
        supportedChains[chainId] = true;
        chainPoolAddresses[chainId] = poolAddress;

        // Initialize chain state
        chainReserves[chainId] = ReserveState({
            balance: 0,
            lastUpdate: block.timestamp,
            isActive: true
        });
    }

    /**
     * @dev Remove supported chain
     * @param chainId Chain ID to remove
     */
    function removeSupportedChain(uint32 chainId) external onlyOwner {
        supportedChains[chainId] = false;
        chainReserves[chainId].isActive = false;
    }

    /**
     * @dev Add emergency operator
     * @param operator Operator address
     */
    function addEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = true;
    }

    /**
     * @dev Remove emergency operator
     * @param operator Operator address
     */
    function removeEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = false;
    }

    /**
     * @dev Set rebalance frequency
     * @param frequency New frequency in seconds
     */
    function setRebalanceFrequency(uint256 frequency) external onlyOwner {
        require(frequency >= 10 minutes, "Frequency too low");
        require(frequency <= 24 hours, "Frequency too high");
        rebalanceFrequency = frequency;
    }

    /**
     * @dev Set emergency threshold
     * @param threshold New threshold in basis points
     */
    function setEmergencyThreshold(uint256 threshold) external onlyOwner {
        require(threshold <= 2000, "Threshold too high"); // Max 20%
        emergencyThreshold = threshold;
    }

    /**
     * @dev Withdraw emergency funds (owner only)
     * @param amount Amount to withdraw
     * @param recipient Recipient address
     */
    function withdrawEmergencyFunds(uint256 amount, address recipient) external onlyOwner {
        require(amount <= emergencyFunds, "Insufficient emergency funds");
        require(recipient != address(0), "Invalid recipient");

        emergencyFunds -= amount;
        totalPoolBalance -= amount;

        usdcToken.safeTransfer(recipient, amount);
    }

    // ============ Internal Functions ============

    function _updateStabilityIndex() internal {
        uint256 reserveRatio = this.calculateReserveRatio();
        uint256 currentPrice = _getCurrentPrice();
        uint256 targetPrice = PRECISION; // 1 USD

        uint256 priceStability = _calculatePriceStability(currentPrice, targetPrice);
        uint256 reserveStability = _calculateReserveStability(reserveRatio);

        // Weighted average: 60% price stability, 40% reserve stability
        stabilityIndex = (priceStability * 60 + reserveStability * 40) / 100;
        lastStabilityUpdate = block.timestamp;

        emit StabilityIndexUpdated(stabilityIndex, stabilityIndex);
    }

    function _calculatePriceDeviation(uint256 currentPrice, uint256 targetPrice) internal pure returns (uint256) {
        if (currentPrice >= targetPrice) {
            return ((currentPrice - targetPrice) * BASIS_POINTS) / targetPrice;
        } else {
            return ((targetPrice - currentPrice) * BASIS_POINTS) / targetPrice;
        }
    }

    function _executeSellPressure(
        uint256 currentPrice,
        uint256 targetPrice,
        uint256 deviation
    ) internal returns (AMMIntervention memory intervention) {
        uint256 sellAmount = _calculateInterventionAmount(deviation);

        if (sellAmount > gateToken.balanceOf(address(this))) {
            sellAmount = gateToken.balanceOf(address(this));
        }

        if (sellAmount > 0) {
            // Execute sell through AMM (simplified)
            uint256 usdcReceived = _simulateAMMTrade(sellAmount, true);

            intervention = AMMIntervention({
                executed: true,
                tradeType: TradeType.SELL,
                amountIn: sellAmount,
                amountOut: usdcReceived,
                timestamp: block.timestamp
            });

            emit AMMTradeExecuted(false, sellAmount, usdcReceived);
        }

        return intervention;
    }

    function _executeBuyPressure(
        uint256 currentPrice,
        uint256 targetPrice,
        uint256 deviation
    ) internal returns (AMMIntervention memory intervention) {
        uint256 buyAmount = _calculateInterventionAmount(deviation);

        if (buyAmount > usdcToken.balanceOf(address(this))) {
            buyAmount = usdcToken.balanceOf(address(this));
        }

        if (buyAmount > 0) {
            // Execute buy through AMM (simplified)
            uint256 gateReceived = _simulateAMMTrade(buyAmount, false);

            intervention = AMMIntervention({
                executed: true,
                tradeType: TradeType.BUY,
                amountIn: buyAmount,
                amountOut: gateReceived,
                timestamp: block.timestamp
            });

            emit AMMTradeExecuted(true, buyAmount, gateReceived);
        }

        return intervention;
    }

    function _calculateInterventionAmount(uint256 deviation) internal view returns (uint256) {
        // Calculate intervention size based on deviation and available funds
        uint256 maxIntervention = totalPoolBalance / 20; // Max 5% of pool
        uint256 deviationFactor = deviation * PRECISION / BASIS_POINTS;

        return (maxIntervention * deviationFactor) / PRECISION;
    }

    function _simulateAMMTrade(uint256 amountIn, bool isSell) internal pure returns (uint256 amountOut) {
        // Simplified AMM simulation - in production this would call actual AMM
        if (isSell) {
            amountOut = (amountIn * 99) / 100; // 1% slippage
        } else {
            amountOut = (amountIn * 101) / 100; // 1% bonus
        }
        return amountOut;
    }

    function _transferToChain(uint32 chainId, uint256 amount) internal returns (RebalanceOperation memory operation) {
        chainReserves[0].balance -= amount;
        chainReserves[chainId].balance += amount;

        emit ReserveRebalanced(chainId, amount, true);

        return RebalanceOperation({
            executed: true,
            sourceChain: 0,
            targetChain: chainId,
            amount: amount,
            timestamp: block.timestamp
        });
    }

    function _requestFromChain(uint32 chainId, uint256 amount) internal returns (RebalanceOperation memory operation) {
        chainReserves[chainId].balance -= amount;
        chainReserves[0].balance += amount;

        emit ReserveRebalanced(chainId, amount, false);

        return RebalanceOperation({
            executed: true,
            sourceChain: chainId,
            targetChain: 0,
            amount: amount,
            timestamp: block.timestamp
        });
    }

    function _executeReserveInjection() internal returns (bool) {
        uint256 injectionAmount = emergencyFunds / 2; // Use half of emergency funds
        if (injectionAmount > 0) {
            reserveFunds += injectionAmount;
            emergencyFunds -= injectionAmount;
            totalReserves += injectionAmount;
            return true;
        }
        return false;
    }

    function _executeSupplyAdjustment() internal returns (bool) {
        // This would interact with the main token contract to adjust supply
        // For now, return success as placeholder
        return true;
    }

    function _getCurrentPrice() internal view returns (uint256) {
        // This would integrate with price oracles
        return PRECISION; // Placeholder: 1 USD
    }

    function _getTotalSupply() internal view returns (uint256) {
        return gateToken.totalSupply();
    }

    function _calculatePriceStability(uint256 currentPrice, uint256 targetPrice) internal pure returns (uint256) {
        uint256 deviation = _calculatePriceDeviation(currentPrice, targetPrice);
        return deviation > 1000 ? 0 : 1000 - deviation;
    }

    function _calculateReserveStability(uint256 reserveRatio) internal pure returns (uint256) {
        if (reserveRatio >= MIN_RESERVE_RATIO && reserveRatio <= MAX_RESERVE_RATIO) {
            // Calculate distance from target
            uint256 deviation = reserveRatio > TARGET_RESERVE_RATIO ?
                reserveRatio - TARGET_RESERVE_RATIO :
                TARGET_RESERVE_RATIO - reserveRatio;

            return deviation > 200 ? 0 : 1000 - (deviation * 5); // Scale deviation
        }
        return 0; // Outside acceptable range
    }

    /**
     * @dev Emergency pause function
     */
    function pause() external {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");
        _pause();
    }

    /**
     * @dev Emergency unpause function
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/core/StripeIntegrationManager..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "../interfaces/IEconomicEngine.sol";

/**
 * @title StripeIntegrationManager
 * @dev Stripe Connect integration for real-time fiat backing validation,
 * fiat activity tracking, and demurrage discount calculation for Caesar Token
 */
contract StripeIntegrationManager is Ownable, ReentrancyGuard, Pausable {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    // ============ Constants ============
    uint256 public constant SIGNATURE_VALIDITY_PERIOD = 5 minutes;
    uint256 public constant MAX_WEBHOOK_RETRY = 3;
    uint256 public constant BACKING_VALIDATION_TOLERANCE = 500; // 5% tolerance
    uint256 public constant MIN_FIAT_ACTIVITY_FOR_DISCOUNT = 100e18; // $100 minimum
    uint256 public constant MAX_DISCOUNT_PERCENTAGE = 5000; // 50% maximum discount

    // ============ Enums ============

    enum TransactionType {
        PAYMENT,
        REFUND,
        PAYOUT,
        TRANSFER,
        PURCHASE,
        REDEMPTION
    }

    enum TransactionStatus {
        PENDING,
        SUCCEEDED,
        FAILED,
        CANCELLED
    }

    // ============ Structs ============

    struct StripeAccountData {
        string stripeAccountId;              // Stripe Connect account ID
        address ethereumAddress;             // Associated Ethereum address
        bool isVerified;                     // Whether account is verified
        uint256 totalVolume;                 // Total fiat volume processed
        uint256 lastActivity;                // Last fiat activity timestamp
        uint256 currentBalance;              // Current fiat balance
        uint8 accountType;                   // Account type (0=individual, 1=business)
        string businessCategory;             // Business category for risk assessment
        uint256 riskScore;                   // Risk score (0-1000)
        bool isBlocked;                      // Whether account is blocked
    }

    struct FiatTransaction {
        string transactionId;                // Transaction ID
        string stripePaymentId;              // Stripe payment ID  
        address userAddress;                 // User's Ethereum address
        uint256 amount;                      // Transaction amount (in cents)
        string currency;                     // Currency code (USD, EUR, etc.)
        TransactionType transactionType;     // Transaction type enum
        TransactionStatus status;            // Transaction status enum
        uint256 timestamp;                   // Transaction timestamp
        string description;                  // Transaction description
        bytes32 hash;                        // Transaction hash for integrity
    }

    struct BackingValidationData {
        uint256 totalUSDCReserves;           // Total USDC reserves
        uint256 totalStripeBalance;          // Total Stripe account balance
        uint256 pendingTransactions;         // Pending transaction amount
        uint256 reservedFunds;               // Reserved funds amount
        uint256 availableFunds;              // Available funds for backing
        uint256 lastValidation;              // Last validation timestamp
        bool isValid;                        // Whether backing is currently valid
        uint256 validationNonce;             // Validation nonce for replay protection
    }

    struct WebhookData {
        string eventId;                      // Stripe event ID
        string eventType;                    // Event type (payment_intent.succeeded, etc.)
        bytes eventData;                     // Encoded event data
        uint256 timestamp;                   // Event timestamp
        bytes signature;                     // Stripe webhook signature
        bool processed;                      // Whether event has been processed
        uint256 retryCount;                  // Number of retry attempts
    }

    struct FiatActivitySummary {
        uint256 volume24h;                   // Volume in last 24 hours
        uint256 volume7d;                    // Volume in last 7 days
        uint256 volume30d;                   // Volume in last 30 days
        uint256 transactionCount24h;         // Transaction count in 24h
        uint256 averageTransactionSize;      // Average transaction size
        uint256 discountEligibility;         // Discount eligibility percentage
        uint256 lastUpdate;                  // Last summary update
    }

    // ============ State Variables ============

    // Economic engine integration
    IEconomicEngine public economicEngine;
    IERC20 public csrToken;

    // Stripe configuration
    string public stripePublishableKey;      // Stripe publishable key
    address public stripeWebhookSigner;      // Address authorized to sign webhooks
    mapping(string => bool) public processedEvents; // Processed Stripe events

    // Account management
    mapping(address => StripeAccountData) public stripeAccounts;
    mapping(string => address) public stripeIdToAddress; // Stripe ID -> Ethereum address
    mapping(address => string) public addressToStripeId; // Ethereum address -> Stripe ID

    // Transaction tracking
    mapping(string => FiatTransaction) public fiatTransactions;
    mapping(address => string[]) public userTransactions; // User -> transaction IDs
    mapping(address => FiatActivitySummary) public activitySummaries;

    // Backing validation
    BackingValidationData public backingData;
    mapping(address => bool) public authorizedValidators; // Authorized backing validators
    uint256 public lastBackingCheck;

    // Webhook processing
    mapping(string => WebhookData) public webhookEvents;
    string[] public pendingWebhooks;

    // Discount calculation
    mapping(address => uint256) public fiatDiscountPercentages;
    mapping(address => uint256) public lastDiscountCalculation;

    // Emergency controls
    bool public emergencyMode;
    mapping(address => bool) public emergencyOperators;
    uint256 public emergencyActivatedAt;

    // ============ Events ============

    event StripeAccountLinked(address indexed user, string stripeAccountId);
    event FiatTransactionProcessed(string transactionId, address indexed user, uint256 amount, TransactionType transactionType);
    event BackingValidated(uint256 totalBacking, uint256 requiredBacking, bool isValid);
    event FiatDiscountCalculated(address indexed user, uint256 discountPercentage);
    event WebhookProcessed(string eventId, string eventType, bool success);
    event EmergencyModeActivated(address operator, string reason);
    event StripeConfigurationUpdated(string publishableKey);
    event AccountVerificationStatusChanged(address indexed user, bool isVerified);

    /**
     * @dev Constructor
     * @param initialOwner Contract owner
     * @param _economicEngine Economic engine address
     * @param _stripeWebhookSigner Authorized webhook signer
     */
    constructor(
        address initialOwner,
        address _economicEngine,
        address _stripeWebhookSigner
    ) Ownable(initialOwner) {
        economicEngine = IEconomicEngine(_economicEngine);
        stripeWebhookSigner = _stripeWebhookSigner;
        lastBackingCheck = block.timestamp;
    }

    // ============ Account Management ============

    /**
     * @dev Link Stripe account to Ethereum address
     * @param stripeAccountId Stripe Connect account ID
     * @param accountType Account type (0=individual, 1=business)
     * @param businessCategory Business category for risk assessment
     */
    function linkStripeAccount(
        string calldata stripeAccountId,
        uint8 accountType,
        string calldata businessCategory
    ) external whenNotPaused {
        require(bytes(stripeAccountId).length > 0, "Invalid Stripe account ID");
        require(stripeIdToAddress[stripeAccountId] == address(0), "Stripe account already linked");
        require(bytes(addressToStripeId[msg.sender]).length == 0, "Address already has Stripe account");

        // Create account data
        stripeAccounts[msg.sender] = StripeAccountData({
            stripeAccountId: stripeAccountId,
            ethereumAddress: msg.sender,
            isVerified: false, // Requires separate verification
            totalVolume: 0,
            lastActivity: block.timestamp,
            currentBalance: 0,
            accountType: accountType,
            businessCategory: businessCategory,
            riskScore: 500, // Default medium risk
            isBlocked: false
        });

        // Update mappings
        stripeIdToAddress[stripeAccountId] = msg.sender;
        addressToStripeId[msg.sender] = stripeAccountId;

        emit StripeAccountLinked(msg.sender, stripeAccountId);
    }

    /**
     * @dev Verify Stripe account (admin only)
     * @param userAddress User's Ethereum address
     * @param isVerified Verification status
     * @param riskScore Risk score (0-1000)
     */
    function verifyStripeAccount(
        address userAddress,
        bool isVerified,
        uint256 riskScore
    ) external onlyOwner {
        require(bytes(addressToStripeId[userAddress]).length > 0, "No linked Stripe account");
        require(riskScore <= 1000, "Invalid risk score");

        StripeAccountData storage account = stripeAccounts[userAddress];
        account.isVerified = isVerified;
        account.riskScore = riskScore;

        emit AccountVerificationStatusChanged(userAddress, isVerified);
    }

    // ============ Transaction Processing ============

    /**
     * @dev Process Stripe webhook for transaction events
     * @param eventId Stripe event ID
     * @param eventType Stripe event type
     * @param eventData Encoded event data
     * @param signature Webhook signature
     */
    function processStripeWebhook(
        string calldata eventId,
        string calldata eventType,
        bytes calldata eventData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused {
        require(bytes(eventId).length > 0, "Invalid event ID");
        require(!processedEvents[eventId], "Event already processed");

        // Verify webhook signature
        bytes32 messageHash = keccak256(abi.encodePacked(eventId, eventType, eventData));
        bytes32 ethSignedMessageHash = messageHash.toEthSignedMessageHash();
        address signer = ethSignedMessageHash.recover(signature);
        require(signer == stripeWebhookSigner, "Invalid webhook signature");

        // Process based on event type
        bool success = false;
        if (keccak256(bytes(eventType)) == keccak256("payment_intent.succeeded")) {
            success = _processPaymentSuccess(eventData);
        } else if (keccak256(bytes(eventType)) == keccak256("payment_intent.payment_failed")) {
            success = _processPaymentFailure(eventData);
        } else if (keccak256(bytes(eventType)) == keccak256("payout.paid")) {
            success = _processPayoutPaid(eventData);
        } else if (keccak256(bytes(eventType)) == keccak256("account.updated")) {
            success = _processAccountUpdate(eventData);
        } else {
            // Unknown event type, mark as processed but don't fail
            success = true;
        }

        if (success) {
            processedEvents[eventId] = true;
        } else {
            // Store for retry
            webhookEvents[eventId] = WebhookData({
                eventId: eventId,
                eventType: eventType,
                eventData: eventData,
                timestamp: block.timestamp,
                signature: signature,
                processed: false,
                retryCount: 1
            });
            pendingWebhooks.push(eventId);
        }

        emit WebhookProcessed(eventId, eventType, success);
    }

    /**
     * @dev Record fiat transaction manually (for testing or backup)
     * @param transaction Transaction data
     */
    function recordFiatTransaction(
        FiatTransaction calldata transaction
    ) external {
        require(authorizedValidators[msg.sender] || msg.sender == owner(), "Unauthorized");
        require(bytes(transaction.transactionId).length > 0, "Invalid transaction ID");

        // Calculate transaction hash
        bytes32 hash = keccak256(abi.encode(
            transaction.transactionId,
            transaction.userAddress,
            transaction.amount,
            transaction.currency,
            transaction.transactionType,
            transaction.timestamp
        ));

        require(hash == transaction.hash, "Transaction hash mismatch");

        // Store transaction
        fiatTransactions[transaction.transactionId] = transaction;
        userTransactions[transaction.userAddress].push(transaction.transactionId);

        // Update user activity summary
        _updateActivitySummary(transaction.userAddress, transaction.amount);

        // Update Stripe account data
        StripeAccountData storage account = stripeAccounts[transaction.userAddress];
        account.totalVolume += transaction.amount;
        account.lastActivity = block.timestamp;

        // Notify economic engine of fiat activity
        if (transaction.status == TransactionStatus.SUCCEEDED && transaction.amount >= MIN_FIAT_ACTIVITY_FOR_DISCOUNT) {
            economicEngine.recordFiatActivity(
                transaction.userAddress,
                transaction.amount,
                uint8(transaction.transactionType)
            );
        }

        emit FiatTransactionProcessed(transaction.transactionId, transaction.userAddress, transaction.amount, transaction.transactionType);
    }

    // ============ Backing Validation ============

    /**
     * @dev Validate fiat backing with signed data from authorized validator
     * @param newBackingData Backing validation data
     * @param signature Validator signature
     */
    function validateFiatBacking(
        BackingValidationData calldata newBackingData,
        bytes calldata signature
    ) external nonReentrant whenNotPaused {
        require(newBackingData.lastValidation > lastBackingCheck, "Stale backing data");
        require(newBackingData.validationNonce > backingData.validationNonce, "Invalid nonce");

        // Verify signature
        bytes32 messageHash = keccak256(abi.encode(
            newBackingData.totalUSDCReserves,
            newBackingData.totalStripeBalance,
            newBackingData.pendingTransactions,
            newBackingData.reservedFunds,
            newBackingData.lastValidation,
            newBackingData.validationNonce
        ));
        bytes32 ethSignedMessageHash = messageHash.toEthSignedMessageHash();
        address signer = ethSignedMessageHash.recover(signature);
        require(authorizedValidators[signer], "Unauthorized validator");

        // Calculate available funds
        uint256 availableFunds = newBackingData.totalUSDCReserves + 
                                 newBackingData.totalStripeBalance - 
                                 newBackingData.pendingTransactions - 
                                 newBackingData.reservedFunds;

        // Get total supply from economic engine (would need to add this function)
        uint256 requiredBacking = _getTotalGateSupply();

        // Check if backing is sufficient (with tolerance)
        uint256 minimumRequired = (requiredBacking * (10000 - BACKING_VALIDATION_TOLERANCE)) / 10000;
        bool isValid = availableFunds >= minimumRequired;

        // Update backing data
        backingData.totalUSDCReserves = newBackingData.totalUSDCReserves;
        backingData.totalStripeBalance = newBackingData.totalStripeBalance;
        backingData.pendingTransactions = newBackingData.pendingTransactions;
        backingData.reservedFunds = newBackingData.reservedFunds;
        backingData.availableFunds = availableFunds;
        backingData.lastValidation = newBackingData.lastValidation;
        backingData.isValid = isValid;
        backingData.validationNonce = newBackingData.validationNonce;

        lastBackingCheck = block.timestamp;

        emit BackingValidated(availableFunds, requiredBacking, isValid);

        // Trigger emergency mode if backing is invalid
        if (!isValid && !emergencyMode) {
            _activateEmergencyMode("Insufficient fiat backing detected");
        }
    }

    /**
     * @dev Calculate fiat activity discount for user
     * @param userAddress User address
     * @return discountPercentage Discount percentage (0-5000 basis points)
     */
    function calculateFiatDiscount(address userAddress) external returns (uint256 discountPercentage) {
        require(
            msg.sender == address(economicEngine) || msg.sender == owner(),
            "Unauthorized"
        );

        FiatActivitySummary storage summary = activitySummaries[userAddress];
        StripeAccountData memory account = stripeAccounts[userAddress];

        // Check if user has verified Stripe account
        if (!account.isVerified || account.isBlocked) {
            return 0;
        }

        // Update activity summary if needed
        if (block.timestamp > summary.lastUpdate + 1 hours) {
            _updateActivitySummary(userAddress, 0); // Update without adding new transaction
        }

        // Calculate discount based on activity levels
        uint256 discount = 0;

        // Base discount for having fiat activity
        if (summary.volume24h > 0) {
            discount = 500; // 5% base discount
        }

        // Additional discount for high activity
        if (summary.volume24h >= 1000e18) { // $1000+
            discount += 1000; // +10%
        } else if (summary.volume24h >= 500e18) { // $500+
            discount += 500; // +5%
        }

        // Frequency bonus
        if (summary.transactionCount24h >= 5) {
            discount += 500; // +5% for frequent usage
        } else if (summary.transactionCount24h >= 3) {
            discount += 250; // +2.5%
        }

        // Weekly volume bonus
        if (summary.volume7d >= 5000e18) { // $5000+ weekly
            discount += 1500; // +15%
        } else if (summary.volume7d >= 2000e18) { // $2000+ weekly
            discount += 750; // +7.5%
        }

        // Risk adjustment (lower risk = higher discount)
        if (account.riskScore <= 300) { // Low risk
            discount = (discount * 120) / 100; // +20% bonus
        } else if (account.riskScore >= 700) { // High risk
            discount = (discount * 80) / 100; // -20% penalty
        }

        // Cap at maximum discount
        discount = discount > MAX_DISCOUNT_PERCENTAGE ? MAX_DISCOUNT_PERCENTAGE : discount;

        // Store calculated discount
        fiatDiscountPercentages[userAddress] = discount;
        lastDiscountCalculation[userAddress] = block.timestamp;

        emit FiatDiscountCalculated(userAddress, discount);
        return discount;
    }

    // ============ Internal Functions ============

    function _processPaymentSuccess(bytes calldata eventData) internal returns (bool) {
        // Decode payment success data and process
        // Implementation depends on Stripe webhook format
        return true; // Placeholder
    }

    function _processPaymentFailure(bytes calldata eventData) internal returns (bool) {
        // Process payment failure
        return true; // Placeholder
    }

    function _processPayoutPaid(bytes calldata eventData) internal returns (bool) {
        // Process payout completion
        return true; // Placeholder
    }

    function _processAccountUpdate(bytes calldata eventData) internal returns (bool) {
        // Process Stripe account updates
        return true; // Placeholder
    }

    function _updateActivitySummary(address userAddress, uint256 newTransactionAmount) internal {
        FiatActivitySummary storage summary = activitySummaries[userAddress];
        uint256 currentTime = block.timestamp;
        uint256 timeSinceUpdate = currentTime - summary.lastUpdate;

        // Apply time decay to existing activity
        if (timeSinceUpdate > 0) {
            // Decay 24h volume
            if (timeSinceUpdate >= 24 hours) {
                summary.volume24h = 0;
                summary.transactionCount24h = 0;
            } else {
                uint256 decayFactor = (24 hours - timeSinceUpdate) * 100 / 24 hours;
                summary.volume24h = (summary.volume24h * decayFactor) / 100;
                summary.transactionCount24h = (summary.transactionCount24h * decayFactor) / 100;
            }

            // Decay 7d volume
            if (timeSinceUpdate >= 7 days) {
                summary.volume7d = 0;
            } else {
                uint256 decayFactor = (7 days - timeSinceUpdate) * 100 / 7 days;
                summary.volume7d = (summary.volume7d * decayFactor) / 100;
            }

            // Decay 30d volume
            if (timeSinceUpdate >= 30 days) {
                summary.volume30d = 0;
            } else {
                uint256 decayFactor = (30 days - timeSinceUpdate) * 100 / 30 days;
                summary.volume30d = (summary.volume30d * decayFactor) / 100;
            }
        }

        // Add new transaction
        if (newTransactionAmount > 0) {
            summary.volume24h += newTransactionAmount;
            summary.volume7d += newTransactionAmount;
            summary.volume30d += newTransactionAmount;
            summary.transactionCount24h++;
        }

        // Update average transaction size
        if (summary.transactionCount24h > 0) {
            summary.averageTransactionSize = summary.volume24h / summary.transactionCount24h;
        }

        summary.lastUpdate = currentTime;
    }

    function _getTotalGateSupply() internal view returns (uint256) {
        // This would query the main Caesar Token contract for total supply
        // Placeholder implementation
        return 1000000 * 1e18;
    }

    function _activateEmergencyMode(string memory reason) internal {
        emergencyMode = true;
        emergencyActivatedAt = block.timestamp;
        economicEngine.activateEmergencyMode(reason);
        emit EmergencyModeActivated(msg.sender, reason);
    }

    // ============ Administrative Functions ============

    /**
     * @dev Update Stripe configuration
     * @param _publishableKey New Stripe publishable key
     * @param _webhookSigner New webhook signer address
     */
    function updateStripeConfiguration(
        string calldata _publishableKey,
        address _webhookSigner
    ) external onlyOwner {
        stripePublishableKey = _publishableKey;
        stripeWebhookSigner = _webhookSigner;
        emit StripeConfigurationUpdated(_publishableKey);
    }

    /**
     * @dev Add authorized backing validator
     * @param validator Validator address
     */
    function addAuthorizedValidator(address validator) external onlyOwner {
        authorizedValidators[validator] = true;
    }

    /**
     * @dev Remove authorized backing validator
     * @param validator Validator address
     */
    function removeAuthorizedValidator(address validator) external onlyOwner {
        authorizedValidators[validator] = false;
    }

    /**
     * @dev Add emergency operator
     * @param operator Operator address
     */
    function addEmergencyOperator(address operator) external onlyOwner {
        emergencyOperators[operator] = true;
    }

    /**
     * @dev Block Stripe account
     * @param userAddress User address to block
     * @param isBlocked Block status
     */
    function blockStripeAccount(address userAddress, bool isBlocked) external onlyOwner {
        require(bytes(addressToStripeId[userAddress]).length > 0, "No linked account");
        stripeAccounts[userAddress].isBlocked = isBlocked;
    }

    // ============ View Functions ============

    function getStripeAccountData(address userAddress) external view returns (StripeAccountData memory) {
        return stripeAccounts[userAddress];
    }

    function getFiatTransaction(string calldata transactionId) external view returns (FiatTransaction memory) {
        return fiatTransactions[transactionId];
    }

    function getUserTransactions(address userAddress) external view returns (string[] memory) {
        return userTransactions[userAddress];
    }

    function getActivitySummary(address userAddress) external view returns (FiatActivitySummary memory) {
        return activitySummaries[userAddress];
    }

    function getBackingData() external view returns (BackingValidationData memory) {
        return backingData;
    }

    function getFiatDiscount(address userAddress) external view returns (uint256) {
        return fiatDiscountPercentages[userAddress];
    }

    function isBackingValid() external view returns (bool) {
        return backingData.isValid && (block.timestamp - backingData.lastValidation <= 1 hours);
    }

    // ============ Emergency Functions ============

    /**
     * @dev Manual emergency mode activation
     * @param reason Emergency reason
     */
    function activateEmergencyMode(string calldata reason) external {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");
        _activateEmergencyMode(reason);
    }

    /**
     * @dev Deactivate emergency mode
     */
    function deactivateEmergencyMode() external onlyOwner {
        emergencyMode = false;
        emergencyActivatedAt = 0;
    }

    /**
     * @dev Emergency pause
     */
    function pause() external {
        require(emergencyOperators[msg.sender] || msg.sender == owner(), "Unauthorized");
        _pause();
    }

    /**
     * @dev Emergency unpause
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ============ Mock Methods for Testing ============

    /**
     * @dev Set CSR token address (for testing)
     * @param _csrToken CSR token address
     */
    function setCsrToken(address _csrToken) external onlyOwner {
        require(_csrToken != address(0), "Invalid token address");
        csrToken = IERC20(_csrToken);
    }

    /**
     * @dev Redeem CSR tokens for fiat (stub for testing)
     * @param amount Amount of CSR to redeem
     */
    function redeemForFiat(uint256 amount) external whenNotPaused nonReentrant {
        require(amount > 0, "Amount must be positive");
        require(address(csrToken) != address(0), "CSR token not set");

        // Transfer CSR tokens from user to this contract (lock them)
        require(csrToken.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        // Record the redemption request
        string memory txId = string(abi.encodePacked("REDEEM_", block.timestamp, "_", msg.sender));

        // Store transaction directly to avoid stack issues
        fiatTransactions[txId].transactionId = txId;
        fiatTransactions[txId].stripePaymentId = "";
        fiatTransactions[txId].userAddress = msg.sender;
        fiatTransactions[txId].amount = amount;
        fiatTransactions[txId].currency = "USD";
        fiatTransactions[txId].transactionType = TransactionType.REDEMPTION;
        fiatTransactions[txId].status = TransactionStatus.PENDING;
        fiatTransactions[txId].timestamp = block.timestamp;
        fiatTransactions[txId].description = "CSR redemption";
        fiatTransactions[txId].hash = keccak256(abi.encodePacked(txId, msg.sender, amount));

        userTransactions[msg.sender].push(txId);

        // Update activity summary
        activitySummaries[msg.sender].volume24h += amount;
        activitySummaries[msg.sender].transactionCount24h++;
        activitySummaries[msg.sender].lastUpdate = block.timestamp;

        emit FiatTransactionProcessed(txId, msg.sender, amount, TransactionType.REDEMPTION);
    }

    /**
     * @dev Get user redemption count (stub for testing)
     * @param userAddress User address to check
     * @return count Number of redemptions
     */
    function getUserRedemptionCount(address userAddress) external view returns (uint256 count) {
        string[] memory transactions = userTransactions[userAddress];
        for (uint256 i = 0; i < transactions.length; i++) {
            if (fiatTransactions[transactions[i]].transactionType == TransactionType.REDEMPTION) {
                count++;
            }
        }
        return count;
    }

    /**
     * @dev Purchase CSR tokens with fiat (stub for testing)
     * @param amount Amount to purchase
     * @param paymentMethodId Payment method identifier
     */
    function purchaseWithFiat(uint256 amount, string calldata paymentMethodId) external whenNotPaused nonReentrant {
        require(amount > 0, "Amount must be positive");
        require(bytes(paymentMethodId).length > 0, "Payment method required");

        string memory txId = string(abi.encodePacked("PURCHASE_", block.timestamp, "_", msg.sender));

        // Store transaction directly to avoid stack issues
        fiatTransactions[txId].transactionId = txId;
        fiatTransactions[txId].stripePaymentId = paymentMethodId;
        fiatTransactions[txId].userAddress = msg.sender;
        fiatTransactions[txId].amount = amount;
        fiatTransactions[txId].currency = "USD";
        fiatTransactions[txId].transactionType = TransactionType.PURCHASE;
        fiatTransactions[txId].status = TransactionStatus.PENDING;
        fiatTransactions[txId].timestamp = block.timestamp;
        fiatTransactions[txId].description = "CSR purchase";
        fiatTransactions[txId].hash = keccak256(abi.encodePacked(txId, msg.sender, amount));

        userTransactions[msg.sender].push(txId);

        emit FiatTransactionProcessed(txId, msg.sender, amount, TransactionType.PURCHASE);
    }
}

