// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./CaesarCoinDEXPair.sol";
import "./ICaesarCoinDEXFactory.sol";

/**
 * @title CaesarCoinDEXFactory
 * @dev Real UniswapV2-style factory for creating and managing trading pairs
 * Enhanced with proper security controls and fee management
 */
contract CaesarCoinDEXFactory is ICaesarCoinDEXFactory, Ownable, ReentrancyGuard {

    // Maximum trading fee (1%)
    uint256 public constant MAX_TRADING_FEE = 100;

    // Mapping from token0 => token1 => pair address
    mapping(address => mapping(address => address)) public override getPair;

    // Array of all pairs created
    address[] public override allPairs;

    // Fee recipient for protocol fees
    address public override feeTo;

    // Fee setter (can be different from owner)
    address public override feeToSetter;

    // Trading fee (in basis points per 1000, default 3 = 0.3%)
    uint256 public override tradingFee = 3;

    // Protocol fee percentage (of trading fees)
    uint256 public protocolFeePercentage = 0; // 0% initially

    // Pair volume tracking
    mapping(address => uint256) public pairVolumes;
    mapping(address => uint256) public pairLastUpdate;

    // Total volume across all pairs
    uint256 public totalVolume;

    // Rate limiting for pair creation
    mapping(address => uint256) public userLastPairCreation;
    uint256 public constant PAIR_CREATION_COOLDOWN = 1 minutes;

    // Temporary storage for pair initialization
    address private _initializingToken0;
    address private _initializingToken1;

    // Events (additional to interface events)
    event ProtocolFeeSet(uint256 fee);
    event VolumeUpdated(address indexed pair, uint256 volume);

    modifier onlyFeeToSetter() {
        require(msg.sender == feeToSetter, "CaesarCoinDEXFactory: FORBIDDEN");
        _;
    }

    constructor(address _owner, address _feeToSetter) Ownable(_owner) {
        require(_owner != address(0), "CaesarCoinDEXFactory: ZERO_ADDRESS");
        require(_feeToSetter != address(0), "CaesarCoinDEXFactory: ZERO_ADDRESS");

        feeToSetter = _feeToSetter;
        feeTo = _owner;
    }

    /**
     * @dev Get the number of pairs created
     */
    function allPairsLength() external view override returns (uint256) {
        return allPairs.length;
    }

    /**
     * @dev Get tokens being initialized (called by pair constructor)
     */
    function getInitializingTokens() external view override returns (address token0, address token1) {
        return (_initializingToken0, _initializingToken1);
    }

    /**
     * @dev Create a new trading pair with proper contract deployment
     */
    function createPair(address tokenA, address tokenB) external override nonReentrant returns (address pair) {
        require(tokenA != tokenB, "CaesarCoinDEXFactory: IDENTICAL_ADDRESSES");
        require(tokenA != address(0) && tokenB != address(0), "CaesarCoinDEXFactory: ZERO_ADDRESS");

        // Rate limiting
        require(
            block.timestamp >= userLastPairCreation[msg.sender] + PAIR_CREATION_COOLDOWN,
            "CaesarCoinDEXFactory: COOLDOWN_NOT_ELAPSED"
        );
        userLastPairCreation[msg.sender] = block.timestamp;

        // Sort tokens
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        require(getPair[token0][token1] == address(0), "CaesarCoinDEXFactory: PAIR_EXISTS");

        // Set initializing tokens for pair constructor
        _initializingToken0 = token0;
        _initializingToken1 = token1;

        // Deploy the pair contract
        bytes memory bytecode = type(CaesarCoinDEXPair).creationCode;
        bytes32 salt = keccak256(abi.encodePacked(token0, token1));

        assembly {
            pair := create2(0, add(bytecode, 32), mload(bytecode), salt)
        }

        require(pair != address(0), "CaesarCoinDEXFactory: FAILED_TO_CREATE_PAIR");

        // Clear initializing tokens
        _initializingToken0 = address(0);
        _initializingToken1 = address(0);

        // Store pair information
        getPair[token0][token1] = pair;
        getPair[token1][token0] = pair;
        allPairs.push(pair);

        emit PairCreated(token0, token1, pair, allPairs.length);

        return pair;
    }

    /**
     * @dev Set fee recipient
     */
    function setFeeTo(address _feeTo) external override onlyOwner {
        feeTo = _feeTo;
        emit FeeToSet(_feeTo);
    }

    /**
     * @dev Set fee setter
     */
    function setFeeToSetter(address _feeToSetter) external override onlyOwner {
        require(_feeToSetter != address(0), "CaesarCoinDEXFactory: ZERO_ADDRESS");
        feeToSetter = _feeToSetter;
        emit FeeToSetterSet(_feeToSetter);
    }

    /**
     * @dev Set the trading fee (only fee setter can call)
     */
    function setTradingFee(uint256 _fee) external override onlyFeeToSetter {
        require(_fee <= MAX_TRADING_FEE, "CaesarCoinDEXFactory: FEE_TOO_HIGH");
        tradingFee = _fee;
        emit TradingFeeSet(_fee);
    }

    /**
     * @dev Set protocol fee percentage
     */
    function setProtocolFee(uint256 _fee) external override onlyFeeToSetter {
        require(_fee <= 50, "CaesarCoinDEXFactory: PROTOCOL_FEE_TOO_HIGH"); // Max 50% of trading fees
        protocolFeePercentage = _fee;
        emit ProtocolFeeSet(_fee);
    }

    /**
     * @dev Get effective trading fee for a pair
     */
    function getPairTradingFee(address pair) external view override returns (uint256) {
        // Verify this is actually a pair created by this factory
        bool isPairValid = false;
        for (uint256 i = 0; i < allPairs.length; i++) {
            if (allPairs[i] == pair) {
                isPairValid = true;
                break;
            }
        }

        if (!isPairValid) {
            return 0;
        }

        return tradingFee;
    }

    /**
     * @dev Update pair volume (called by pairs during swaps)
     */
    function updatePairVolume(address pair, uint256 volumeToAdd) external override {
        // Verify caller is a valid pair
        bool isPairValid = false;
        for (uint256 i = 0; i < allPairs.length; i++) {
            if (allPairs[i] == msg.sender && allPairs[i] == pair) {
                isPairValid = true;
                break;
            }
        }

        require(isPairValid, "CaesarCoinDEXFactory: INVALID_PAIR");

        pairVolumes[pair] += volumeToAdd;
        pairLastUpdate[pair] = block.timestamp;
        totalVolume += volumeToAdd;

        emit VolumeUpdated(pair, pairVolumes[pair]);
    }

    /**
     * @dev Collect protocol fees from a specific pair
     */
    function collectProtocolFees(address pair) external override {
        require(feeTo != address(0), "CaesarCoinDEXFactory: FEE_TO_NOT_SET");

        // Verify this is a valid pair
        bool isPairValid = false;
        for (uint256 i = 0; i < allPairs.length; i++) {
            if (allPairs[i] == pair) {
                isPairValid = true;
                break;
            }
        }

        require(isPairValid, "CaesarCoinDEXFactory: INVALID_PAIR");

        // Call pair's collect function
        CaesarCoinDEXPair(pair).collectProtocolFee();
    }

    /**
     * @dev Collect protocol fees from all pairs
     */
    function collectAllProtocolFees() external {
        require(feeTo != address(0), "CaesarCoinDEXFactory: FEE_TO_NOT_SET");

        for (uint256 i = 0; i < allPairs.length; i++) {
            try CaesarCoinDEXPair(allPairs[i]).collectProtocolFee() {
                // Success, continue
            } catch {
                // Skip failed collections
                continue;
            }
        }
    }

    /**
     * @dev Get pair creation code hash for CREATE2 prediction
     */
    function pairCodeHash() external pure returns (bytes32) {
        return keccak256(type(CaesarCoinDEXPair).creationCode);
    }

    /**
     * @dev Get pair address using CREATE2 prediction
     */
    function predictPairAddress(address tokenA, address tokenB) external view returns (address pair) {
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        bytes32 salt = keccak256(abi.encodePacked(token0, token1));
        bytes32 hash = keccak256(abi.encodePacked(
            bytes1(0xff),
            address(this),
            salt,
            keccak256(type(CaesarCoinDEXPair).creationCode)
        ));
        return address(uint160(uint256(hash)));
    }

    /**
     * @dev Emergency function to pause pair creation (owner only)
     */
    function setPairCreationPaused(bool paused) external onlyOwner {
        // This would be implemented with a paused state
        // For now, we'll use the cooldown mechanism
    }

    /**
     * @dev Get pair volume statistics
     */
    function getPairStats(address pair) external view returns (
        uint256 volume,
        uint256 lastUpdate,
        bool isValid
    ) {
        // Verify pair
        bool isPairValid = false;
        for (uint256 i = 0; i < allPairs.length; i++) {
            if (allPairs[i] == pair) {
                isPairValid = true;
                break;
            }
        }

        return (
            pairVolumes[pair],
            pairLastUpdate[pair],
            isPairValid
        );
    }

    /**
     * @dev Get total DEX statistics
     */
    function getDEXStats() external view returns (
        uint256 _totalVolume,
        uint256 _totalPairs,
        uint256 _currentTradingFee,
        uint256 _protocolFeePercentage
    ) {
        return (
            totalVolume,
            allPairs.length,
            tradingFee,
            protocolFeePercentage
        );
    }
}

contracts/dex/CaesarCoinDEXPair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "./ICaesarCoinDEXFactory.sol";

/**
 * @title CaesarCoinDEXPair
 * @dev UniswapV2-style trading pair with liquidity pools and swap mechanics
 * Enhanced with anti-MEV protection and fair trading mechanisms
 */
contract CaesarCoinDEXPair is ERC20, ReentrancyGuard {
    using Math for uint256;

    // Minimum liquidity locked forever
    uint256 public constant MINIMUM_LIQUIDITY = 10**3;

    // Maximum fee (1%)
    uint256 public constant MAX_FEE = 100;

    // Factory and tokens
    address public immutable factory;
    address public immutable token0;
    address public immutable token1;

    // Reserves and last update
    uint112 private reserve0;
    uint112 private reserve1;
    uint32 private blockTimestampLast;

    // Cumulative price tracking for TWAP
    uint256 public price0CumulativeLast;
    uint256 public price1CumulativeLast;
    uint256 public kLast; // reserve0 * reserve1 at the time of the most recent liquidity event

    // Fee tracking
    uint256 public totalFeeCollected0;
    uint256 public totalFeeCollected1;

    // Events
    event Mint(address indexed sender, uint256 amount0, uint256 amount1);
    event Burn(address indexed sender, uint256 amount0, uint256 amount1, address indexed to);
    event Swap(
        address indexed sender,
        uint256 amount0In,
        uint256 amount1In,
        uint256 amount0Out,
        uint256 amount1Out,
        address indexed to
    );
    event Sync(uint112 reserve0, uint112 reserve1);

    modifier onlyFactory() {
        require(msg.sender == factory, "DEXPair: FORBIDDEN");
        _;
    }

    constructor() ERC20("Gateway DEX LP", "GW-LP") {
        factory = msg.sender;
        (token0, token1) = ICaesarCoinDEXFactory(msg.sender).getInitializingTokens();
    }

    /**
     * @dev Initialize pair with token addresses (called by factory)
     */
    function initialize(address _token0, address _token1) external onlyFactory {
        // This is handled in constructor via factory callback
    }

    /**
     * @dev Get current reserves and last block timestamp
     */
    function getReserves() public view returns (uint112 _reserve0, uint112 _reserve1, uint32 _blockTimestampLast) {
        _reserve0 = reserve0;
        _reserve1 = reserve1;
        _blockTimestampLast = blockTimestampLast;
    }

    /**
     * @dev Update reserves and cumulative prices
     */
    function _update(uint256 balance0, uint256 balance1, uint112 _reserve0, uint112 _reserve1) private {
        require(balance0 <= type(uint112).max && balance1 <= type(uint112).max, "DEXPair: OVERFLOW");

        uint32 blockTimestamp = uint32(block.timestamp % 2**32);
        uint32 timeElapsed = blockTimestamp - blockTimestampLast;

        if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
            // * never overflows, and + overflow is desired
            price0CumulativeLast += uint256(_reserve1) * 2**112 / _reserve0 * timeElapsed;
            price1CumulativeLast += uint256(_reserve0) * 2**112 / _reserve1 * timeElapsed;
        }

        reserve0 = uint112(balance0);
        reserve1 = uint112(balance1);
        blockTimestampLast = blockTimestamp;

        emit Sync(reserve0, reserve1);
    }

    /**
     * @dev Mint liquidity tokens for adding liquidity
     */
    function mint(address to) external nonReentrant returns (uint256 liquidity) {
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        uint256 balance0 = IERC20(token0).balanceOf(address(this));
        uint256 balance1 = IERC20(token1).balanceOf(address(this));
        uint256 amount0 = balance0 - _reserve0;
        uint256 amount1 = balance1 - _reserve1;

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply();

        if (_totalSupply == 0) {
            liquidity = Math.sqrt(amount0 * amount1) - MINIMUM_LIQUIDITY;
            _mint(address(0), MINIMUM_LIQUIDITY); // permanently lock the first MINIMUM_LIQUIDITY tokens
        } else {
            liquidity = Math.min(amount0 * _totalSupply / _reserve0, amount1 * _totalSupply / _reserve1);
        }

        require(liquidity > 0, "DEXPair: INSUFFICIENT_LIQUIDITY_MINTED");
        _mint(to, liquidity);

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = uint256(reserve0) * reserve1;

        emit Mint(msg.sender, amount0, amount1);
    }

    /**
     * @dev Burn liquidity tokens to remove liquidity
     */
    function burn(address to) external nonReentrant returns (uint256 amount0, uint256 amount1) {
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        address _token0 = token0;
        address _token1 = token1;
        uint256 balance0 = IERC20(_token0).balanceOf(address(this));
        uint256 balance1 = IERC20(_token1).balanceOf(address(this));
        uint256 liquidity = balanceOf(address(this));

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply();

        amount0 = liquidity * balance0 / _totalSupply;
        amount1 = liquidity * balance1 / _totalSupply;

        require(amount0 > 0 && amount1 > 0, "DEXPair: INSUFFICIENT_LIQUIDITY_BURNED");

        _burn(address(this), liquidity);
        IERC20(_token0).transfer(to, amount0);
        IERC20(_token1).transfer(to, amount1);

        balance0 = IERC20(_token0).balanceOf(address(this));
        balance1 = IERC20(_token1).balanceOf(address(this));

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = uint256(reserve0) * reserve1;

        emit Burn(msg.sender, amount0, amount1, to);
    }

    /**
     * @dev Swap tokens with automatic fee collection
     */
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata data) external nonReentrant {
        require(amount0Out > 0 || amount1Out > 0, "DEXPair: INSUFFICIENT_OUTPUT_AMOUNT");
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        require(amount0Out < _reserve0 && amount1Out < _reserve1, "DEXPair: INSUFFICIENT_LIQUIDITY");

        uint256 balance0;
        uint256 balance1;
        {
            address _token0 = token0;
            address _token1 = token1;
            require(to != _token0 && to != _token1, "DEXPair: INVALID_TO");

            if (amount0Out > 0) IERC20(_token0).transfer(to, amount0Out);
            if (amount1Out > 0) IERC20(_token1).transfer(to, amount1Out);

            if (data.length > 0) {
                // Flash loan callback support
                (bool success,) = to.call(data);
                require(success, "DEXPair: CALLBACK_FAILED");
            }

            balance0 = IERC20(_token0).balanceOf(address(this));
            balance1 = IERC20(_token1).balanceOf(address(this));
        }

        uint256 amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
        uint256 amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
        require(amount0In > 0 || amount1In > 0, "DEXPair: INSUFFICIENT_INPUT_AMOUNT");

        {
            // Get trading fee from factory
            uint256 fee = ICaesarCoinDEXFactory(factory).getPairTradingFee(address(this));
            uint256 balance0Adjusted = (balance0 * 1000) - (amount0In * fee);
            uint256 balance1Adjusted = (balance1 * 1000) - (amount1In * fee);

            require(
                balance0Adjusted * balance1Adjusted >= uint256(_reserve0) * _reserve1 * (1000**2), 
                "DEXPair: K"
            );

            // Track fees
            if (amount0In > 0) {
                totalFeeCollected0 += (amount0In * fee) / 1000;
            }
            if (amount1In > 0) {
                totalFeeCollected1 += (amount1In * fee) / 1000;
            }
        }

        _update(balance0, balance1, _reserve0, _reserve1);
        emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
    }

    /**
     * @dev Force reserves to match balances
     */
    function skim(address to) external nonReentrant {
        address _token0 = token0;
        address _token1 = token1;
        IERC20(_token0).transfer(to, IERC20(_token0).balanceOf(address(this)) - reserve0);
        IERC20(_token1).transfer(to, IERC20(_token1).balanceOf(address(this)) - reserve1);
    }

    /**
     * @dev Force balances to match reserves
     */
    function sync() external nonReentrant {
        _update(IERC20(token0).balanceOf(address(this)), IERC20(token1).balanceOf(address(this)), reserve0, reserve1);
    }

    /**
     * @dev Calculate and mint protocol fee
     */
    function _mintFee(uint112 _reserve0, uint112 _reserve1) private returns (bool feeOn) {
        address feeTo = ICaesarCoinDEXFactory(factory).feeTo();
        feeOn = feeTo != address(0);
        uint256 _kLast = kLast;

        if (feeOn) {
            if (_kLast != 0) {
                uint256 rootK = Math.sqrt(uint256(_reserve0) * _reserve1);
                uint256 rootKLast = Math.sqrt(_kLast);

                if (rootK > rootKLast) {
                    uint256 numerator = totalSupply() * (rootK - rootKLast);
                    uint256 denominator = rootK * 5 + rootKLast;
                    uint256 liquidity = numerator / denominator;

                    if (liquidity > 0) _mint(feeTo, liquidity);
                }
            }
        } else if (_kLast != 0) {
            kLast = 0;
        }
    }

    /**
     * @dev Get amount out for a given amount in (with fees)
     */
    function getAmountOut(uint256 amountIn, address tokenIn) external view returns (uint256 amountOut) {
        require(tokenIn == token0 || tokenIn == token1, "DEXPair: INVALID_TOKEN");
        require(amountIn > 0, "DEXPair: INSUFFICIENT_INPUT_AMOUNT");

        (uint112 reserveIn, uint112 reserveOut) = tokenIn == token0 ? (reserve0, reserve1) : (reserve1, reserve0);
        require(reserveIn > 0 && reserveOut > 0, "DEXPair: INSUFFICIENT_LIQUIDITY");

        uint256 fee = ICaesarCoinDEXFactory(factory).getPairTradingFee(address(this));
        uint256 amountInWithFee = amountIn * (1000 - fee);
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = (reserveIn * 1000) + amountInWithFee;

        amountOut = numerator / denominator;
    }

    /**
     * @dev Get amount in for a given amount out (with fees)
     */
    function getAmountIn(uint256 amountOut, address tokenOut) external view returns (uint256 amountIn) {
        require(tokenOut == token0 || tokenOut == token1, "DEXPair: INVALID_TOKEN");
        require(amountOut > 0, "DEXPair: INSUFFICIENT_OUTPUT_AMOUNT");

        (uint112 reserveIn, uint112 reserveOut) = tokenOut == token0 ? (reserve1, reserve0) : (reserve0, reserve1);
        require(reserveIn > 0 && reserveOut > amountOut, "DEXPair: INSUFFICIENT_LIQUIDITY");

        uint256 fee = ICaesarCoinDEXFactory(factory).getPairTradingFee(address(this));
        uint256 numerator = reserveIn * amountOut * 1000;
        uint256 denominator = (reserveOut - amountOut) * (1000 - fee);

        amountIn = (numerator / denominator) + 1;
    }

    /**
     * @dev Get current trading fee for this pair
     */
    function getTradingFee() external view returns (uint256) {
        return ICaesarCoinDEXFactory(factory).getPairTradingFee(address(this));
    }

    /**
     * @dev Collect protocol fees (only factory can call)
     */
    function collectProtocolFee() external onlyFactory {
        address feeTo = ICaesarCoinDEXFactory(factory).feeTo();
        require(feeTo != address(0), "DEXPair: FEE_TO_NOT_SET");

        if (totalFeeCollected0 > 0) {
            IERC20(token0).transfer(feeTo, totalFeeCollected0);
            totalFeeCollected0 = 0;
        }

        if (totalFeeCollected1 > 0) {
            IERC20(token1).transfer(feeTo, totalFeeCollected1);
            totalFeeCollected1 = 0;
        }
    }
}

contracts/dex/ICaesarCoinDEXFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

/**
 * @title ICaesarCoinDEXFactory
 * @dev Interface for the Caesar Token DEX Factory
 */
interface ICaesarCoinDEXFactory {
    // Events
    event PairCreated(address indexed token0, address indexed token1, address pair, uint256 allPairsLength);
    event FeeToSet(address indexed feeTo);
    event FeeToSetterSet(address indexed feeToSetter);
    event TradingFeeSet(uint256 fee);

    // Read functions
    function feeTo() external view returns (address);
    function feeToSetter() external view returns (address);
    function tradingFee() external view returns (uint256);
    function getPair(address tokenA, address tokenB) external view returns (address pair);
    function allPairs(uint256 index) external view returns (address pair);
    function allPairsLength() external view returns (uint256);
    function getPairTradingFee(address pair) external view returns (uint256);
    function getInitializingTokens() external view returns (address token0, address token1);

    // Write functions
    function createPair(address tokenA, address tokenB) external returns (address pair);
    function setFeeTo(address _feeTo) external;
    function setFeeToSetter(address _feeToSetter) external;
    function setTradingFee(uint256 _fee) external;
    function setProtocolFee(uint256 _fee) external;
    function updatePairVolume(address pair, uint256 volumeToAdd) external;
    function collectProtocolFees(address pair) external;
}

contracts/hypermesh/ConsensusProofEngine.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title ConsensusProofEngine
 * @dev Implements consensus proof mechanism via distribution via hops and sharding
 * 
 * This contract eliminates traditional PoS/PoW by using cryptographic proofs
 * of distributed hop validation across the network matrix
 */
contract ConsensusProofEngine is Ownable, ReentrancyGuard {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    // Consensus proof structure
    struct ConsensusProof {
        bytes32 transactionHash;        // Hash of transaction being validated
        address[] validationPath;       // Ordered path of validation nodes
        bytes32[] hopProofs;            // Cryptographic proof from each hop
        uint256[] timestamps;           // Timestamp of each validation step
        bytes signature;                // Aggregated signature of validation
        uint256 consensusScore;         // Consensus strength score (0-1000)
        ProofStatus status;             // Current status of proof
    }

    enum ProofStatus {
        PENDING,                        // Awaiting validation
        VALIDATING,                     // In progress
        CONSENSUS_REACHED,              // Sufficient consensus achieved
        CONSENSUS_FAILED,               // Failed to reach consensus
        EXPIRED                         // Proof expired due to timeout
    }

    // Validation node capability tracking
    struct ValidationNode {
        address nodeAddress;            // Node address
        uint256 validationPower;        // Node's validation capacity (not stake-based)
        uint256 successfulValidations;  // Historical validation successes
        uint256 failedValidations;      // Historical validation failures
        uint256 averageLatency;         // Average validation latency
        uint256 lastValidation;         // Timestamp of last validation
        bool isAuthorized;              // Authorization status
        bytes32 nodeSignature;          // Node's cryptographic signature
    }

    // Sharding for parallel consensus
    struct ValidationShard {
        uint256 shardId;                // Unique shard identifier
        address[] assignedNodes;        // Nodes assigned to this shard
        uint256 activeValidations;      // Current validation count
        uint256 shardCapacity;          // Maximum concurrent validations
        uint256 averageConsensusTime;   // Average time to reach consensus
        bool isActive;                  // Shard status
    }

    // Consensus parameters (from concept folder requirements)
    struct ConsensusParams {
        uint256 minValidators;          // Minimum validators for consensus (from Factor 1)
        uint256 optimalValidators;      // Optimal validator count
        uint256 consensusThreshold;     // Threshold for consensus (67% from precept.md)
        uint256 maxValidationTime;      // Maximum validation time (seconds)
        uint256 hopTimeoutMs;           // Timeout per hop in milliseconds  
        uint256 shardRebalanceInterval; // How often to rebalance shards
        bool emergencyConsensusMode;    // Emergency consensus mode flag
    }

    // State variables
    mapping(bytes32 => ConsensusProof) public consensusProofs;
    mapping(address => ValidationNode) public validationNodes;
    mapping(uint256 => ValidationShard) public validationShards;
    mapping(bytes32 => address) public proofToValidator;

    address[] public activeValidators;
    bytes32[] public pendingProofs;
    uint256 public totalShards;
    uint256 public totalValidations;

    ConsensusParams public consensusParams;

    // Network utility scoring (from formulas.py)
    struct NetworkMetrics {
        uint256 dailyValidations;       // Daily validation count
        uint256 crossChainValidations;  // Cross-chain validations
        uint256 averageConsensusTime;   // Average time to consensus
        uint256 networkUtilityScore;    // Overall network utility (0-1000)
        uint256 validationSuccessRate;  // Success rate (0-1000)
    }

    NetworkMetrics public networkMetrics;

    // Events
    event ConsensusProofStarted(bytes32 indexed proofId, bytes32 transactionHash, address[] validators);
    event HopValidated(bytes32 indexed proofId, address validator, uint256 hopIndex, bytes32 proof);
    event ConsensusReached(bytes32 indexed proofId, uint256 consensusScore, uint256 validationTime);
    event ConsensusFailed(bytes32 indexed proofId, string reason);
    event ValidatorAuthorized(address indexed validator, uint256 validationPower);
    event ShardRebalanced(uint256 indexed shardId, address[] newValidators);
    event EmergencyConsensusActivated(string reason);

    // Modifiers
    modifier onlyAuthorizedValidator() {
        require(validationNodes[msg.sender].isAuthorized, "Not authorized validator");
        _;
    }

    modifier validProof(bytes32 proofId) {
        require(consensusProofs[proofId].transactionHash != bytes32(0), "Invalid proof ID");
        _;
    }

    constructor(address owner) Ownable(owner) {
        // Initialize consensus parameters based on concept folder specs
        consensusParams = ConsensusParams({
            minValidators: 3,               // Minimum 3 validators (from requirements)
            optimalValidators: 5,           // Optimal 5 validators  
            consensusThreshold: 670,        // 67% consensus (from precept.md)
            maxValidationTime: 300,         // 5 minutes maximum
            hopTimeoutMs: 2000,             // 2 second hop timeout
            shardRebalanceInterval: 3600,   // Rebalance every hour
            emergencyConsensusMode: false
        });

        // Initialize with 3 shards (gradual expansion)
        totalShards = 3;
        for (uint256 i = 0; i < totalShards; i++) {
            validationShards[i] = ValidationShard({
                shardId: i,
                assignedNodes: new address[](0),
                activeValidations: 0,
                shardCapacity: 100,         // 100 concurrent validations per shard
                averageConsensusTime: 0,
                isActive: true
            });
        }
    }

    /**
     * @dev Authorize a validator node (stake-neutral authorization)
     * @param validator Address of the validator node
     * @param validationPower Validation capacity (based on performance, not stake)
     */
    function authorizeValidator(address validator, uint256 validationPower) external onlyOwner {
        require(validator != address(0), "Invalid validator address");
        require(validationPower > 0 && validationPower <= 1000, "Invalid validation power");

        validationNodes[validator] = ValidationNode({
            nodeAddress: validator,
            validationPower: validationPower,
            successfulValidations: 0,
            failedValidations: 0,
            averageLatency: 1000,           // Default 1 second
            lastValidation: 0,
            isAuthorized: true,
            nodeSignature: keccak256(abi.encodePacked(validator, block.timestamp))
        });

        activeValidators.push(validator);

        // Assign to least loaded shard
        _assignToOptimalShard(validator);

        emit ValidatorAuthorized(validator, validationPower);
    }

    /**
     * @dev Initiate consensus proof for a transaction
     * @param transactionHash Hash of transaction requiring consensus
     * @param requiredValidators Number of validators needed for this consensus
     * @return proofId Unique identifier for this consensus proof
     */
    function initiateConsensusProof(
        bytes32 transactionHash,
        uint256 requiredValidators
    ) external nonReentrant returns (bytes32 proofId) {
        require(transactionHash != bytes32(0), "Invalid transaction hash");
        require(requiredValidators >= consensusParams.minValidators, "Insufficient validators");
        require(activeValidators.length >= requiredValidators, "Not enough active validators");

        // Generate unique proof ID
        proofId = keccak256(abi.encodePacked(
            transactionHash,
            msg.sender,
            block.timestamp,
            block.prevrandao
        ));

        require(consensusProofs[proofId].transactionHash == bytes32(0), "Proof already exists");

        // Select validators using stake-neutral random selection
        address[] memory selectedValidators = _selectValidators(requiredValidators);

        consensusProofs[proofId] = ConsensusProof({
            transactionHash: transactionHash,
            validationPath: selectedValidators,
            hopProofs: new bytes32[](selectedValidators.length),
            timestamps: new uint256[](selectedValidators.length),
            signature: "",
            consensusScore: 0,
            status: ProofStatus.PENDING
        });

        pendingProofs.push(proofId);
        proofToValidator[proofId] = msg.sender;

        emit ConsensusProofStarted(proofId, transactionHash, selectedValidators);
        return proofId;
    }

    /**
     * @dev Submit validation proof for a hop in the consensus process
     * @param proofId Consensus proof identifier
     * @param hopIndex Index of the hop being validated
     * @param hopProof Cryptographic proof of validation
     */
    function submitHopValidation(
        bytes32 proofId,
        uint256 hopIndex,
        bytes32 hopProof
    ) external onlyAuthorizedValidator validProof(proofId) {
        ConsensusProof storage proof = consensusProofs[proofId];
        require(proof.status == ProofStatus.PENDING || proof.status == ProofStatus.VALIDATING, 
                "Proof not accepting validations");
        require(hopIndex < proof.validationPath.length, "Invalid hop index");
        require(proof.validationPath[hopIndex] == msg.sender, "Unauthorized for this hop");
        require(proof.hopProofs[hopIndex] == bytes32(0), "Hop already validated");

        // Check if proof has expired
        if (block.timestamp > proof.timestamps[0] + consensusParams.maxValidationTime) {
            proof.status = ProofStatus.EXPIRED;
            emit ConsensusFailed(proofId, "Validation timeout");
            return;
        }

        // Record hop validation
        proof.hopProofs[hopIndex] = hopProof;
        proof.timestamps[hopIndex] = block.timestamp;
        proof.status = ProofStatus.VALIDATING;

        // Update validator metrics
        ValidationNode storage validator = validationNodes[msg.sender];
        validator.lastValidation = block.timestamp;

        emit HopValidated(proofId, msg.sender, hopIndex, hopProof);

        // Check if consensus is reached
        _evaluateConsensus(proofId);
    }

    /**
     * @dev Evaluate if consensus has been reached for a proof
     */
    function _evaluateConsensus(bytes32 proofId) internal {
        ConsensusProof storage proof = consensusProofs[proofId];

        // Count completed validations
        uint256 completedValidations = 0;
        uint256 pathValidations = proof.validationPath.length;

        for (uint256 i = 0; i < pathValidations; i++) {
            if (proof.hopProofs[i] != bytes32(0)) {
                completedValidations++;
            }
        }

        // Calculate consensus score
        uint256 consensusScore = (completedValidations * 1000) / pathValidations;
        proof.consensusScore = consensusScore;

        // Check if consensus threshold is met
        if (consensusScore >= consensusParams.consensusThreshold) {
            proof.status = ProofStatus.CONSENSUS_REACHED;

            // Calculate validation time
            uint256 validationTime = block.timestamp - proof.timestamps[0];

            // Update network metrics
            _updateNetworkMetrics(validationTime, true);

            // Update individual validator success rates
            for (uint256 i = 0; i < proof.validationPath.length; i++) {
                if (proof.hopProofs[i] != bytes32(0)) {
                    validationNodes[proof.validationPath[i]].successfulValidations++;
                }
            }

            totalValidations++;
            emit ConsensusReached(proofId, consensusScore, validationTime);

        } else if (completedValidations == pathValidations && consensusScore < consensusParams.consensusThreshold) {
            // All validators responded but consensus not reached
            proof.status = ProofStatus.CONSENSUS_FAILED;

            _updateNetworkMetrics(0, false);

            // Update failure metrics
            for (uint256 i = 0; i < proof.validationPath.length; i++) {
                validationNodes[proof.validationPath[i]].failedValidations++;
            }

            emit ConsensusFailed(proofId, "Insufficient consensus");
        }
    }

    /**
     * @dev Select validators using stake-neutral random selection (Factor 1 compliance)
     */
    function _selectValidators(uint256 count) internal view returns (address[] memory) {
        require(activeValidators.length >= count, "Insufficient validators");

        address[] memory selected = new address[](count);
        bool[] memory used = new bool[](activeValidators.length);

        // Use cryptographically secure randomness for stake-neutral selection
        uint256 randomSeed = uint256(keccak256(abi.encodePacked(
            block.timestamp,
            block.prevrandao,
            msg.sender,
            totalValidations
        )));

        for (uint256 i = 0; i < count; i++) {
            uint256 attempts = 0;
            uint256 index;

            do {
                index = (randomSeed + i * 997 + attempts) % activeValidators.length;
                attempts++;

                // Prevent infinite loop
                if (attempts > activeValidators.length * 2) break;

            } while (used[index] || !validationNodes[activeValidators[index]].isAuthorized);

            used[index] = true;
            selected[i] = activeValidators[index];
        }

        return selected;
    }

    /**
     * @dev Assign validator to optimal shard based on load balancing
     */
    function _assignToOptimalShard(address validator) internal {
        uint256 minLoad = type(uint256).max;
        uint256 optimalShard = 0;

        // Find shard with minimum load
        for (uint256 i = 0; i < totalShards; i++) {
            if (validationShards[i].isActive && 
                validationShards[i].assignedNodes.length < minLoad) {
                minLoad = validationShards[i].assignedNodes.length;
                optimalShard = i;
            }
        }

        validationShards[optimalShard].assignedNodes.push(validator);
    }

    /**
     * @dev Update network metrics based on validation results
     */
    function _updateNetworkMetrics(uint256 validationTime, bool success) internal {
        if (success) {
            // Update average consensus time using exponential moving average
            if (networkMetrics.averageConsensusTime == 0) {
                networkMetrics.averageConsensusTime = validationTime;
            } else {
                // 90% weight to previous average, 10% to new measurement
                networkMetrics.averageConsensusTime = 
                    (networkMetrics.averageConsensusTime * 9 + validationTime) / 10;
            }

            networkMetrics.dailyValidations++;
        }

        // Update success rate
        uint256 totalAttempts = networkMetrics.dailyValidations + 
                               (success ? 0 : 1); // Add failed attempt if applicable
        uint256 successCount = networkMetrics.dailyValidations;

        networkMetrics.validationSuccessRate = totalAttempts > 0 ? 
            (successCount * 1000) / totalAttempts : 1000;

        // Calculate network utility score based on formulas.py
        networkMetrics.networkUtilityScore = _calculateNetworkUtilityScore();
    }

    /**
     * @dev Calculate network utility score (from formulas.py implementation)
     */
    function _calculateNetworkUtilityScore() internal view returns (uint256) {
        // Target metrics from concept folder
        uint256 targetDailyValidations = 500000;  // From precept.md simulation
        uint256 targetCrossChain = 50000;         // 10% cross-chain target

        // Calculate utility components
        uint256 validationUtility = networkMetrics.dailyValidations > targetDailyValidations ?
            1000 : (networkMetrics.dailyValidations * 1000) / targetDailyValidations;

        uint256 crossChainUtility = networkMetrics.crossChainValidations > targetCrossChain ?
            1000 : (networkMetrics.crossChainValidations * 1000) / targetCrossChain;

        // Network utility formula from formulas.py
        uint256 networkUtility = (validationUtility + crossChainUtility) / 2;

        // Apply success rate modifier
        networkUtility = (networkUtility * networkMetrics.validationSuccessRate) / 1000;

        return networkUtility;
    }

    /**
     * @dev Get consensus proof status and details
     */
    function getConsensusProof(bytes32 proofId) external view returns (
        bytes32 transactionHash,
        address[] memory validationPath,
        uint256 consensusScore,
        ProofStatus status,
        uint256 completedHops
    ) {
        ConsensusProof storage proof = consensusProofs[proofId];

        uint256 completed = 0;
        for (uint256 i = 0; i < proof.hopProofs.length; i++) {
            if (proof.hopProofs[i] != bytes32(0)) {
                completed++;
            }
        }

        return (
            proof.transactionHash,
            proof.validationPath,
            proof.consensusScore,
            proof.status,
            completed
        );
    }

    /**
     * @dev Get network consensus metrics
     */
    function getNetworkMetrics() external view returns (
        uint256 activeValidatorCount,
        uint256 averageConsensusTime,
        uint256 validationSuccessRate,
        uint256 networkUtilityScore,
        uint256 totalValidationsToday
    ) {
        return (
            activeValidators.length,
            networkMetrics.averageConsensusTime,
            networkMetrics.validationSuccessRate,
            networkMetrics.networkUtilityScore,
            networkMetrics.dailyValidations
        );
    }

    /**
     * @dev Get validator performance metrics
     */
    function getValidatorMetrics(address validator) external view returns (
        uint256 validationPower,
        uint256 successfulValidations,
        uint256 failedValidations,
        uint256 successRate,
        bool isAuthorized
    ) {
        ValidationNode storage node = validationNodes[validator];

        uint256 nodeValidations = node.successfulValidations + node.failedValidations;
        uint256 nodeSuccessRate = nodeValidations > 0 ? 
            (node.successfulValidations * 1000) / nodeValidations : 1000;

        return (
            node.validationPower,
            node.successfulValidations,
            node.failedValidations,
            nodeSuccessRate,
            node.isAuthorized
        );
    }

    /**
     * @dev Emergency consensus management
     */
    function activateEmergencyConsensus(string calldata reason) external onlyOwner {
        consensusParams.emergencyConsensusMode = true;
        consensusParams.consensusThreshold = 510;  // Reduce to 51% in emergency
        consensusParams.maxValidationTime = 60;    // Reduce to 1 minute

        emit EmergencyConsensusActivated(reason);
    }

    function deactivateEmergencyConsensus() external onlyOwner {
        consensusParams.emergencyConsensusMode = false;
        consensusParams.consensusThreshold = 670;  // Restore to 67%
        consensusParams.maxValidationTime = 300;   // Restore to 5 minutes
    }

    /**
     * @dev Administrative functions
     */
    function updateConsensusParams(ConsensusParams calldata newParams) external onlyOwner {
        consensusParams = newParams;
    }

    function rebalanceShards() external onlyOwner {
        // Implement shard rebalancing logic
        for (uint256 i = 0; i < totalShards; i++) {
            if (validationShards[i].isActive) {
                emit ShardRebalanced(i, validationShards[i].assignedNodes);
            }
        }
    }
}

contracts/hypermesh/CrossChainRouteOptim.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "./DynamicEconomicsOracle.sol";

/**
 * @title CrossChainRouteOptimizer
 * @dev Intelligent rate limiting and cross-chain rerouting system
 * 
 * Implements dynamic transaction routing based on:
 * - Network capacity and performance metrics
 * - Real-time cost analysis
 * - Automated failover and load balancing
 * - Circuit breaker mechanisms for network protection
 */
contract CrossChainRouteOptimizer is Ownable, ReentrancyGuard, Pausable {

    // Route optimization configuration
    struct RouteConfig {
        uint256 maxRetries;                 // Maximum routing retry attempts
        uint256 timeoutWindow;              // Route timeout in seconds
        uint256 costThresholdPercent;       // Cost increase threshold for rerouting (%)
        uint256 latencyThresholdMs;         // Maximum acceptable latency (ms)
        uint256 minQualityScore;            // Minimum network quality for routing
        uint256 emergencyRerouteThreshold;  // Emergency rerouting quality threshold
        bool adaptiveRoutingEnabled;        // Enable/disable adaptive routing
    }

    // Transaction routing request
    struct RouteRequest {
        bytes32 requestId;                  // Unique request identifier
        address sender;                     // Transaction sender
        address targetNetwork;              // Preferred target network
        uint256 amount;                     // Transaction amount
        uint256 maxCost;                    // Maximum acceptable cost
        uint256 maxLatency;                 // Maximum acceptable latency
        uint256 priority;                   // Transaction priority (0-1000)
        uint256 timestamp;                  // Request timestamp
        RouteStatus status;                 // Current routing status
    }

    // Route path information
    struct RoutePath {
        address[] networks;                 // Network path
        uint256[] expectedCosts;            // Cost per network hop
        uint256[] expectedLatencies;        // Latency per network hop
        uint256 totalCost;                  // Total routing cost
        uint256 totalLatency;               // Total expected latency
        uint256 qualityScore;               // Route quality score
        uint256 reliabilityScore;           // Route reliability score
        bool isActive;                      // Route active status
    }

    // Network rate limiting state
    struct RateLimit {
        uint256 currentCount;               // Current transaction count in window
        uint256 maxCount;                   // Maximum allowed transactions
        uint256 windowStart;                // Rate limiting window start time
        uint256 windowDuration;             // Window duration in seconds
        uint256 backoffUntil;               // Backoff period end timestamp
        bool isThrottled;                   // Current throttling status
    }

    // Network performance metrics
    struct NetworkMetrics {
        uint256 successRate;                // Historical success rate (0-1000)
        uint256 averageLatency;             // Average transaction latency
        uint256 currentLoad;                // Current network load (0-1000)
        uint256 capacityUtilization;       // Capacity utilization (0-1000)
        uint256 lastFailureTime;           // Last recorded failure timestamp
        uint256 consecutiveFailures;       // Consecutive failure count
        uint256 totalTransactions;         // Total transactions routed
        uint256 lastUpdate;                 // Last metrics update
    }

    enum RouteStatus {
        PENDING,        // Awaiting route calculation
        CALCULATED,     // Route calculated successfully
        EXECUTING,      // Route execution in progress
        COMPLETED,      // Route completed successfully
        FAILED,         // Route execution failed
        REROUTED,       // Route was rerouted to alternative
        TIMEOUT         // Route execution timed out
    }

    // Emergency throttling modes
    enum ThrottleMode {
        NORMAL,         // 100% capacity
        CONGESTED,      // 70% capacity
        EMERGENCY,      // 30% capacity
        HALT            // 0% capacity (trading halted)
    }

    // State variables
    RouteConfig public routeConfig;
    DynamicEconomicsOracle public economicsOracle;

    mapping(bytes32 => RouteRequest) public routeRequests;
    mapping(address => RateLimit) public rateLimits;
    mapping(address => NetworkMetrics) public networkMetrics;
    mapping(address => bool) public supportedNetworks;
    mapping(bytes32 => RoutePath) public calculatedRoutes;

    address[] public activeNetworks;
    bytes32[] public pendingRequests;

    uint256 public totalRequests;
    uint256 public successfulRoutes;
    uint256 public failedRoutes;
    uint256 public reroutedTransactions;

    ThrottleMode public currentThrottleMode;
    uint256 public lastThrottleUpdate;

    // Events
    event RouteRequested(bytes32 indexed requestId, address sender, address targetNetwork, uint256 amount);
    event RouteCalculated(bytes32 indexed requestId, address[] networks, uint256 totalCost, uint256 totalLatency);
    event RouteExecuted(bytes32 indexed requestId, bool success, uint256 actualCost, uint256 actualLatency);
    event RouteRerouted(bytes32 indexed requestId, address fromNetwork, address toNetwork, string reason);
    event RateLimitTriggered(address indexed network, uint256 currentLoad, uint256 backoffDuration);
    event ThrottleModeChanged(ThrottleMode oldMode, ThrottleMode newMode, string reason);
    event NetworkMetricsUpdated(address indexed network, uint256 successRate, uint256 averageLatency);
    event EmergencyRerouteActivated(address indexed network, string reason);

    constructor(address owner, address payable _economicsOracle) Ownable(owner) {
        economicsOracle = DynamicEconomicsOracle(_economicsOracle);

        // Initialize default configuration
        routeConfig = RouteConfig({
            maxRetries: 3,
            timeoutWindow: 300,             // 5 minutes
            costThresholdPercent: 150,      // 150% cost increase threshold
            latencyThresholdMs: 30000,      // 30 seconds max latency
            minQualityScore: 300,           // Minimum 30% quality score
            emergencyRerouteThreshold: 200, // 20% quality for emergency reroute
            adaptiveRoutingEnabled: true
        });

        currentThrottleMode = ThrottleMode.NORMAL;
        lastThrottleUpdate = block.timestamp;
    }

    /**
     * @dev Request optimal route for cross-chain transaction
     */
    function requestRoute(
        address targetNetwork,
        uint256 amount,
        uint256 maxCost,
        uint256 maxLatency,
        uint256 priority
    ) external nonReentrant whenNotPaused returns (bytes32 requestId) {
        require(supportedNetworks[targetNetwork], "Unsupported target network");
        require(amount > 0, "Invalid amount");
        require(priority <= 1000, "Invalid priority");

        // Check rate limiting
        require(!_isRateLimited(targetNetwork), "Network rate limited");

        // Generate unique request ID
        requestId = keccak256(abi.encodePacked(
            msg.sender,
            targetNetwork,
            amount,
            block.timestamp,
            totalRequests
        ));

        // Create route request
        routeRequests[requestId] = RouteRequest({
            requestId: requestId,
            sender: msg.sender,
            targetNetwork: targetNetwork,
            amount: amount,
            maxCost: maxCost,
            maxLatency: maxLatency,
            priority: priority,
            timestamp: block.timestamp,
            status: RouteStatus.PENDING
        });

        pendingRequests.push(requestId);
        totalRequests++;

        // Calculate optimal route
        _calculateOptimalRoute(requestId);

        emit RouteRequested(requestId, msg.sender, targetNetwork, amount);
        return requestId;
    }

    /**
     * @dev Calculate optimal route based on current network conditions
     */
    function _calculateOptimalRoute(bytes32 requestId) internal {
        RouteRequest storage request = routeRequests[requestId];

        // Get current economic parameters
        DynamicEconomicsOracle.EconomicParameters memory economicParams = economicsOracle.getEconomicParameters();

        // Find available networks
        address[] memory availableNetworks = _getAvailableNetworks();

        // Calculate route options
        RoutePath memory bestRoute;
        uint256 bestScore = 0;

        for (uint256 i = 0; i < availableNetworks.length; i++) {
            address network = availableNetworks[i];

            // Skip if network doesn't meet minimum requirements
            NetworkMetrics memory metrics = networkMetrics[network];
            if (metrics.successRate < routeConfig.minQualityScore) {
                continue;
            }

            // Calculate route score
            uint256 routeScore = _calculateRouteScore(network, request, economicParams);

            if (routeScore > bestScore) {
                bestScore = routeScore;
                bestRoute = _buildRoutePath(network, request, economicParams);
            }
        }

        // Store calculated route
        if (bestRoute.networks.length > 0) {
            calculatedRoutes[requestId] = bestRoute;
            request.status = RouteStatus.CALCULATED;

            emit RouteCalculated(
                requestId, 
                bestRoute.networks, 
                bestRoute.totalCost, 
                bestRoute.totalLatency
            );
        } else {
            request.status = RouteStatus.FAILED;
        }
    }

    /**
     * @dev Calculate route score based on cost, latency, and reliability
     * Formula: Route_Score = (1/Cost) * Quality * (1/Latency) * Success_Rate
     */
    function _calculateRouteScore(
        address network,
        RouteRequest memory request,
        DynamicEconomicsOracle.EconomicParameters memory economicParams
    ) internal view returns (uint256) {
        NetworkMetrics memory metrics = networkMetrics[network];

        // Cost factor (inversely proportional)
        uint256 estimatedCost = _estimateRoutingCost(network, request.amount, economicParams);
        uint256 costScore = estimatedCost > 0 ? (1000 ether) / estimatedCost : 0;

        // Latency factor (inversely proportional)
        uint256 latencyScore = metrics.averageLatency > 0 ? 
            (routeConfig.latencyThresholdMs * 1000) / metrics.averageLatency : 1000;

        // Quality factor (network health) - use success rate as fallback
        uint256 qualityScore = metrics.successRate;

        // Success rate factor
        uint256 successScore = metrics.successRate;

        // Priority adjustment
        uint256 priorityMultiplier = 500 + (request.priority / 2); // Range: 500-1000

        // Calculate final score
        uint256 score = (costScore * qualityScore * latencyScore * successScore * priorityMultiplier) / 
                       (1000 * 1000 * 1000 * 1000);

        return score;
    }

    /**
     * @dev Build complete route path for network
     */
    function _buildRoutePath(
        address network,
        RouteRequest memory request,
        DynamicEconomicsOracle.EconomicParameters memory economicParams
    ) internal view returns (RoutePath memory) {
        address[] memory networks = new address[](1);
        uint256[] memory costs = new uint256[](1);
        uint256[] memory latencies = new uint256[](1);

        networks[0] = network;
        costs[0] = _estimateRoutingCost(network, request.amount, economicParams);
        latencies[0] = networkMetrics[network].averageLatency;

        return RoutePath({
            networks: networks,
            expectedCosts: costs,
            expectedLatencies: latencies,
            totalCost: costs[0],
            totalLatency: latencies[0],
            qualityScore: networkMetrics[network].successRate,
            reliabilityScore: _calculateReliabilityScore(network),
            isActive: true
        });
    }

    /**
     * @dev Estimate routing cost for network
     */
    function _estimateRoutingCost(
        address network,
        uint256 amount,
        DynamicEconomicsOracle.EconomicParameters memory economicParams
    ) internal view returns (uint256) {
        // Base cost from dynamic gas fee
        uint256 baseCost = economicParams.dynamicGasFee;

        // Network-specific cost multiplier
        NetworkMetrics memory metrics = networkMetrics[network];
        uint256 loadMultiplier = 1000 + (metrics.currentLoad / 2); // Up to 1.5x for high load

        // Amount-based scaling (larger amounts may have higher costs)
        uint256 amountMultiplier = 1000 + (amount / 100 ether); // Small scaling factor

        return (baseCost * loadMultiplier * amountMultiplier) / (1000 * 1000);
    }

    /**
     * @dev Calculate network reliability score
     */
    function _calculateReliabilityScore(address network) internal view returns (uint256) {
        NetworkMetrics memory metrics = networkMetrics[network];

        // Base score from success rate
        uint256 baseScore = metrics.successRate;

        // Penalty for consecutive failures
        if (metrics.consecutiveFailures > 0) {
            uint256 failurePenalty = metrics.consecutiveFailures * 50; // -50 per consecutive failure
            baseScore = baseScore > failurePenalty ? baseScore - failurePenalty : 0;
        }

        // Bonus for high transaction volume (proven reliability)
        if (metrics.totalTransactions > 1000) {
            uint256 volumeBonus = 50; // +50 for high volume networks
            baseScore = baseScore + volumeBonus > 1000 ? 1000 : baseScore + volumeBonus;
        }

        return baseScore;
    }

    /**
     * @dev Execute calculated route
     */
    function executeRoute(bytes32 requestId) external nonReentrant {
        RouteRequest storage request = routeRequests[requestId];
        require(request.sender == msg.sender, "Unauthorized");
        require(request.status == RouteStatus.CALCULATED, "Route not ready");

        RoutePath memory route = calculatedRoutes[requestId];
        require(route.isActive, "Route inactive");

        // Check if rerouting is needed
        (bool needsReroute, address alternativeNetwork) = economicsOracle.shouldTriggerReroute(route.networks[0]);

        if (needsReroute && routeConfig.adaptiveRoutingEnabled) {
            _handleReroute(requestId, route.networks[0], alternativeNetwork);
            return;
        }

        // Update request status
        request.status = RouteStatus.EXECUTING;

        // Update rate limiting
        _updateRateLimit(route.networks[0]);

        // Simulate route execution (in production, this would interact with actual cross-chain protocols)
        bool success = _simulateRouteExecution(route);

        // Update metrics and status
        _updateNetworkMetrics(route.networks[0], success, route.totalLatency);

        if (success) {
            request.status = RouteStatus.COMPLETED;
            successfulRoutes++;
            emit RouteExecuted(requestId, true, route.totalCost, route.totalLatency);
        } else {
            request.status = RouteStatus.FAILED;
            failedRoutes++;
            emit RouteExecuted(requestId, false, 0, 0);
        }
    }

    /**
     * @dev Handle route rerouting
     */
    function _handleReroute(bytes32 requestId, address originalNetwork, address alternativeNetwork) internal {
        RouteRequest storage request = routeRequests[requestId];

        if (alternativeNetwork != address(0) && supportedNetworks[alternativeNetwork]) {
            // Update target network
            request.targetNetwork = alternativeNetwork;
            request.status = RouteStatus.REROUTED;

            // Recalculate route for alternative network
            _calculateOptimalRoute(requestId);

            reroutedTransactions++;
            emit RouteRerouted(requestId, originalNetwork, alternativeNetwork, "Network quality below threshold");
        } else {
            request.status = RouteStatus.FAILED;
            emit RouteRerouted(requestId, originalNetwork, address(0), "No alternative network available");
        }
    }

    /**
     * @dev Simulate route execution (replace with actual cross-chain integration)
     */
    function _simulateRouteExecution(RoutePath memory route) internal view returns (bool) {
        // Simulate based on network success rate
        NetworkMetrics memory metrics = networkMetrics[route.networks[0]];

        // Generate pseudo-random success based on network reliability
        uint256 randomValue = uint256(keccak256(abi.encodePacked(block.timestamp, msg.sender))) % 1000;

        return randomValue < metrics.successRate;
    }

    /**
     * @dev Update network metrics after route execution
     */
    function _updateNetworkMetrics(address network, bool success, uint256 actualLatency) internal {
        NetworkMetrics storage metrics = networkMetrics[network];

        // Update total transactions
        metrics.totalTransactions++;

        // Update success rate (exponential moving average)
        uint256 newSuccessValue = success ? 1000 : 0;
        metrics.successRate = (metrics.successRate * 9 + newSuccessValue) / 10;

        // Update average latency (exponential moving average)
        if (success) {
            metrics.averageLatency = (metrics.averageLatency * 9 + actualLatency) / 10;
            metrics.consecutiveFailures = 0;
        } else {
            metrics.consecutiveFailures++;
            metrics.lastFailureTime = block.timestamp;
        }

        metrics.lastUpdate = block.timestamp;

        // Check for throttle mode changes
        _evaluateThrottleMode();

        emit NetworkMetricsUpdated(network, metrics.successRate, metrics.averageLatency);
    }

    /**
     * @dev Check if network is rate limited
     */
    function _isRateLimited(address network) internal view returns (bool) {
        RateLimit memory limit = rateLimits[network];

        // Check backoff period
        if (limit.backoffUntil > block.timestamp) {
            return true;
        }

        // Check current throttle mode
        uint256 capacityMultiplier = _getCapacityMultiplier();
        uint256 effectiveLimit = (limit.maxCount * capacityMultiplier) / 1000;

        // Check if within rate window and under limit
        if (block.timestamp >= limit.windowStart + limit.windowDuration) {
            return false; // New window, reset
        }

        return limit.currentCount >= effectiveLimit;
    }

    /**
     * @dev Update rate limit counters
     */
    function _updateRateLimit(address network) internal {
        RateLimit storage limit = rateLimits[network];

        // Initialize if first time
        if (limit.windowStart == 0) {
            limit.maxCount = 100; // Default 100 transactions per window
            limit.windowDuration = 3600; // 1 hour window
        }

        // Check if new window
        if (block.timestamp >= limit.windowStart + limit.windowDuration) {
            limit.currentCount = 1;
            limit.windowStart = block.timestamp;
            limit.isThrottled = false;
        } else {
            limit.currentCount++;
        }

        // Check if rate limit exceeded
        uint256 capacityMultiplier = _getCapacityMultiplier();
        uint256 effectiveLimit = (limit.maxCount * capacityMultiplier) / 1000;

        if (limit.currentCount >= effectiveLimit) {
            limit.isThrottled = true;
            limit.backoffUntil = block.timestamp + 300; // 5 minute backoff

            emit RateLimitTriggered(network, limit.currentCount, 300);
        }
    }

    /**
     * @dev Get capacity multiplier based on current throttle mode
     */
    function _getCapacityMultiplier() internal view returns (uint256) {
        if (currentThrottleMode == ThrottleMode.NORMAL) return 1000;      // 100%
        if (currentThrottleMode == ThrottleMode.CONGESTED) return 700;    // 70%
        if (currentThrottleMode == ThrottleMode.EMERGENCY) return 300;    // 30%
        return 0; // HALT mode
    }

    /**
     * @dev Evaluate and update throttle mode based on network conditions
     */
    function _evaluateThrottleMode() internal {
        // Get overall network health from economics oracle
        (uint256 activeNodes, uint256 avgSuccessRate, uint256 avgLatency, , ) = 
            economicsOracle.getNetworkHealth();

        ThrottleMode newMode = currentThrottleMode;

        // Determine new throttle mode
        if (avgSuccessRate < 500 || avgLatency > 20000) {           // < 50% success or > 20s latency
            newMode = ThrottleMode.HALT;
        } else if (avgSuccessRate < 700 || avgLatency > 10000) {    // < 70% success or > 10s latency
            newMode = ThrottleMode.EMERGENCY;
        } else if (avgSuccessRate < 850 || avgLatency > 5000) {     // < 85% success or > 5s latency
            newMode = ThrottleMode.CONGESTED;
        } else {
            newMode = ThrottleMode.NORMAL;
        }

        // Update mode if changed
        if (newMode != currentThrottleMode) {
            ThrottleMode oldMode = currentThrottleMode;
            currentThrottleMode = newMode;
            lastThrottleUpdate = block.timestamp;

            string memory reason = _getThrottleModeReason(newMode, avgSuccessRate, avgLatency);
            emit ThrottleModeChanged(oldMode, newMode, reason);
        }
    }

    /**
     * @dev Get throttle mode change reason
     */
    function _getThrottleModeReason(
        ThrottleMode mode, 
        uint256 successRate, 
        uint256 latency
    ) internal pure returns (string memory) {
        if (mode == ThrottleMode.HALT) {
            return successRate < 500 ? "Success rate below 50%" : "Latency above 20 seconds";
        } else if (mode == ThrottleMode.EMERGENCY) {
            return successRate < 700 ? "Success rate below 70%" : "Latency above 10 seconds";
        } else if (mode == ThrottleMode.CONGESTED) {
            return successRate < 850 ? "Success rate below 85%" : "Latency above 5 seconds";
        }
        return "Network conditions normalized";
    }

    /**
     * @dev Get available networks for routing
     */
    function _getAvailableNetworks() internal view returns (address[] memory) {
        uint256 availableCount = 0;

        // Count available networks
        for (uint256 i = 0; i < activeNetworks.length; i++) {
            if (supportedNetworks[activeNetworks[i]] && !_isRateLimited(activeNetworks[i])) {
                availableCount++;
            }
        }

        // Build array of available networks
        address[] memory available = new address[](availableCount);
        uint256 index = 0;

        for (uint256 i = 0; i < activeNetworks.length; i++) {
            if (supportedNetworks[activeNetworks[i]] && !_isRateLimited(activeNetworks[i])) {
                available[index] = activeNetworks[i];
                index++;
            }
        }

        return available;
    }

    /**
     * @dev Add supported network
     */
    function addSupportedNetwork(address network) external onlyOwner {
        require(!supportedNetworks[network], "Network already supported");

        supportedNetworks[network] = true;
        activeNetworks.push(network);

        // Initialize network metrics
        networkMetrics[network] = NetworkMetrics({
            successRate: 1000,              // Start with perfect score
            averageLatency: 5000,           // Default 5 second latency
            currentLoad: 0,
            capacityUtilization: 0,
            lastFailureTime: 0,
            consecutiveFailures: 0,
            totalTransactions: 0,
            lastUpdate: block.timestamp
        });

        // Initialize rate limiting
        rateLimits[network] = RateLimit({
            currentCount: 0,
            maxCount: 100,                  // Default 100 transactions per hour
            windowStart: block.timestamp,
            windowDuration: 3600,           // 1 hour window
            backoffUntil: 0,
            isThrottled: false
        });
    }

    /**
     * @dev Get route request details
     */
    function getRouteRequest(bytes32 requestId) external view returns (RouteRequest memory) {
        return routeRequests[requestId];
    }

    /**
     * @dev Get calculated route details
     */
    function getCalculatedRoute(bytes32 requestId) external view returns (RoutePath memory) {
        return calculatedRoutes[requestId];
    }

    /**
     * @dev Get network performance metrics
     */
    function getNetworkMetrics(address network) external view returns (NetworkMetrics memory) {
        return networkMetrics[network];
    }

    /**
     * @dev Get system performance statistics
     */
    function getSystemStats() external view returns (
        uint256 totalRequestCount,
        uint256 successfulRouteCount,
        uint256 failedRouteCount,
        uint256 rerouteCount,
        uint256 activeNetworkCount,
        ThrottleMode throttleMode
    ) {
        return (
            totalRequests,
            successfulRoutes,
            failedRoutes,
            reroutedTransactions,
            activeNetworks.length,
            currentThrottleMode
        );
    }

    /**
     * @dev Emergency functions
     */
    function setThrottleMode(ThrottleMode mode, string calldata reason) external onlyOwner {
        ThrottleMode oldMode = currentThrottleMode;
        currentThrottleMode = mode;
        lastThrottleUpdate = block.timestamp;

        emit ThrottleModeChanged(oldMode, mode, reason);
    }

    function updateRouteConfig(RouteConfig calldata newConfig) external onlyOwner {
        routeConfig = newConfig;
    }

    function emergencyPauseNetwork(address network, string calldata reason) external onlyOwner {
        supportedNetworks[network] = false;
        rateLimits[network].backoffUntil = block.timestamp + 86400; // 24 hour backoff

        emit EmergencyRerouteActivated(network, reason);
    }
}

contracts/hypermesh/DynamicEconomicsOrac.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title DynamicEconomicsOracle
 * @dev Real-time gas fee and reward calculation based on network-matrix liquidity/volatility
 * 
 * Implements dynamic economic adjustments to achieve self-stabilization through:
 * - Liquidity health analysis across network matrix
 * - Volatility-based fee scaling
 * - Merit-based reward distribution
 * - Cross-chain economic coordination
 */
contract DynamicEconomicsOracle is Ownable, ReentrancyGuard, Pausable {

    // Economic configuration parameters
    struct EconomicConfig {
        uint256 baseFee;                    // Base transaction fee (in wei)
        uint256 maxFeeMultiplier;           // Maximum fee multiplier (default: 10x)
        uint256 hostRewardPercentage;       // Percentage of fees for routing hosts (default: 70%)
        uint256 liquidityPoolPercentage;    // Percentage for liquidity pool (default: 20%)
        uint256 reservePercentage;          // Percentage for reserve fund (default: 10%)
        uint256 crossChainBonusRate;        // Cross-chain routing bonus rate
        uint256 performanceDecayRate;       // Rate at which performance scores decay
        bool emergencyMode;                 // Emergency fee adjustment mode
    }

    // Network liquidity health metrics
    struct LiquidityMetrics {
        uint256 liquidityHealthIndex;       // L(t) - Current liquidity health (0-1000)
        uint256 activeParticipants;         // Number of active network participants
        uint256 targetParticipants;         // Target participant count
        uint256 dailyVolume;                // 24h transaction volume
        uint256 targetVolume;               // Target daily volume
        uint256 stabilityReserve;           // Current stability reserve
        uint256 requiredReserve;            // Required reserve amount
        uint256 lastUpdate;                 // Last metrics update timestamp
    }

    // Market pressure and volatility indicators
    struct VolatilityMetrics {
        uint256 marketPressure;             // |current_price - target_price| / target_price * 1000
        uint256 priceDeviation;             // Price deviation from target
        uint256 transactionVolume;          // Current transaction volume
        uint256 targetTransactionVolume;    // Target transaction volume
        uint256 crossChainTransfers;        // Cross-chain transfer count
        uint256 targetCrossChainTransfers;  // Target cross-chain transfers
        uint256 volatilityScore;            // Overall volatility score (0-1000)
        uint256 lastUpdate;                 // Last update timestamp
    }

    // Network health assessment per chain
    struct NetworkHealth {
        address networkAddress;             // Network/chain identifier
        uint256 settlementRate;             // Success rate (0-1000, where 1000 = 100%)
        uint256 averageLatency;             // Average transaction latency (ms)
        uint256 capacityUtilization;       // Network capacity usage (0-1000)
        uint256 qualityScore;               // Overall network quality (0-1000)
        bool isActive;                      // Network active status
        uint256 lastHealthCheck;            // Last health assessment
    }

    // Economic calculation results
    struct EconomicParameters {
        uint256 dynamicGasFee;              // Calculated gas fee
        uint256 hostReward;                 // Reward per routing host
        uint256 performanceMultiplier;      // Performance-based multiplier
        uint256 crossChainBonus;            // Cross-chain routing bonus
        uint256 rateLimitThreshold;         // Current rate limiting threshold
        uint256 rearouteThreshold;          // Threshold for cross-chain rerouting
    }

    // State variables
    EconomicConfig public economicConfig;
    LiquidityMetrics public liquidityMetrics;
    VolatilityMetrics public volatilityMetrics;

    mapping(address => NetworkHealth) public networkHealth;
    mapping(address => uint256) public hostPerformanceScores;
    mapping(address => uint256) public hostTotalRewards;

    address[] public monitoredNetworks;
    address[] public activeNodes;
    bytes32[] public pendingValidations;
    // Define a NetworkNode struct for nodes mapping
    struct NetworkNode {
        bool isActive;
        uint256 successRate;
        uint256 avgLatency;
    }
    mapping(address => NetworkNode) public nodes;
    uint256 public totalNetworks;

    // Economic formulas constants (from formulas.py)
    uint256 constant SCALE_FACTOR = 1000;           // 1000 = 100% for calculations
    uint256 constant MIN_LIQUIDITY_HEALTH = 100;    // 10% minimum liquidity health
    uint256 constant EMERGENCY_THRESHOLD = 200;     // 20% emergency threshold
    uint256 constant HALT_THRESHOLD = 100;          // 10% halt threshold
    uint256 constant MAX_MARKET_PRESSURE = 500;     // 50% maximum market pressure

    // Events
    event EconomicParametersUpdated(uint256 newGasFee, uint256 newHostReward, uint256 timestamp);
    event LiquidityMetricsUpdated(uint256 healthIndex, uint256 marketPressure, uint256 timestamp);
    event NetworkHealthUpdated(address indexed network, uint256 qualityScore, uint256 timestamp);
    event EmergencyModeActivated(string reason, uint256 timestamp);
    event RewardDistributed(address indexed host, uint256 amount, uint256 performanceScore);
    event RateLimitThresholdUpdated(uint256 newThreshold, string reason);
    event CrossChainRerouteTriggered(address fromNetwork, address toNetwork, string reason);

    constructor(address owner) Ownable(owner) {
        // Initialize default economic configuration
        economicConfig = EconomicConfig({
            baseFee: 0.001 ether,           // 0.001 ETH base fee
            maxFeeMultiplier: 10000,        // 10x maximum multiplier (10000 = 10.0)
            hostRewardPercentage: 700,      // 70% to routing hosts
            liquidityPoolPercentage: 200,   // 20% to liquidity pool
            reservePercentage: 100,         // 10% to reserve
            crossChainBonusRate: 50,        // 5% cross-chain bonus
            performanceDecayRate: 50,       // 5% daily performance decay
            emergencyMode: false
        });

        // Initialize liquidity metrics with neutral values
        liquidityMetrics = LiquidityMetrics({
            liquidityHealthIndex: 700,      // Start with 70% health
            activeParticipants: 0,
            targetParticipants: 100,        // Target 100 participants
            dailyVolume: 0,
            targetVolume: 10 ether,         // Target 10 ETH daily volume
            stabilityReserve: 0,
            requiredReserve: 1 ether,       // Require 1 ETH reserve
            lastUpdate: block.timestamp
        });

        // Initialize volatility metrics
        volatilityMetrics = VolatilityMetrics({
            marketPressure: 0,
            priceDeviation: 0,
            transactionVolume: 0,
            targetTransactionVolume: 100,   // Target 100 transactions
            crossChainTransfers: 0,
            targetCrossChainTransfers: 10,  // Target 10 cross-chain transfers
            volatilityScore: 0,
            lastUpdate: block.timestamp
        });
    }

    /**
     * @dev Calculate dynamic gas fee based on current network conditions
     * Formula: Dynamic_Gas_Fee = base_fee * (1 + Market_Pressure) * sqrt(Transaction_Volume / Target_Volume) * (1/Liquidity_Health_Index)
     */
    function calculateDynamicGasFee() external view returns (uint256) {
        uint256 baseFee = economicConfig.baseFee;

        // Market pressure adjustment (1 + Market_Pressure)
        uint256 pressureMultiplier = SCALE_FACTOR + volatilityMetrics.marketPressure;

        // Volume scaling factor: sqrt(Transaction_Volume / Target_Volume)
        uint256 volumeRatio = (volatilityMetrics.transactionVolume * SCALE_FACTOR) / volatilityMetrics.targetTransactionVolume;
        uint256 volumeMultiplier = _sqrt(volumeRatio);

        // Liquidity health adjustment: (1 / Liquidity_Health_Index)
        uint256 liquidityDivisor = liquidityMetrics.liquidityHealthIndex > 0 ? 
            liquidityMetrics.liquidityHealthIndex : MIN_LIQUIDITY_HEALTH;
        uint256 liquidityMultiplier = (SCALE_FACTOR * SCALE_FACTOR) / liquidityDivisor;

        // Calculate final fee
        uint256 dynamicFee = (baseFee * pressureMultiplier * volumeMultiplier * liquidityMultiplier) / 
                            (SCALE_FACTOR * SCALE_FACTOR * SCALE_FACTOR);

        // Apply emergency mode caps
        if (economicConfig.emergencyMode || liquidityMetrics.liquidityHealthIndex < EMERGENCY_THRESHOLD) {
            uint256 maxFee = (baseFee * economicConfig.maxFeeMultiplier) / SCALE_FACTOR;
            if (dynamicFee > maxFee) {
                dynamicFee = maxFee;
            }
        }

        return dynamicFee;
    }

    /**
     * @dev Calculate host reward based on performance and contribution
     * Formula: Host_Reward = (Transaction_Fee * Host_Percentage) * Performance_Multiplier + Cross_Chain_Bonus
     */
    function calculateHostReward(
        address host, 
        uint256 transactionFee, 
        bool isCrossChain
    ) external view returns (uint256) {
        // Base reward calculation
        uint256 baseReward = (transactionFee * economicConfig.hostRewardPercentage) / SCALE_FACTOR;

        // Performance multiplier based on host's historical performance
        uint256 performanceScore = hostPerformanceScores[host];
        if (performanceScore == 0) {
            performanceScore = 500; // Default neutral performance (50%)
        }

        uint256 performanceMultiplier = _calculatePerformanceMultiplier(performanceScore);
        uint256 adjustedReward = (baseReward * performanceMultiplier) / SCALE_FACTOR;

        // Add cross-chain bonus if applicable
        if (isCrossChain) {
            uint256 crossChainBonus = (baseReward * economicConfig.crossChainBonusRate) / SCALE_FACTOR;
            adjustedReward += crossChainBonus;
        }

        return adjustedReward;
    }

    /**
     * @dev Update liquidity health metrics
     * Formula: Liquidity_Health_Index = min(active_participants/target_participants, daily_volume/target_volume, stability_reserve/required_reserve)
     */
    function updateLiquidityMetrics(
        uint256 activeParticipants,
        uint256 dailyVolume,
        uint256 stabilityReserve
    ) external onlyOwner {
        // Calculate individual health ratios
        uint256 participantRatio = activeParticipants > liquidityMetrics.targetParticipants ? 
            SCALE_FACTOR : (activeParticipants * SCALE_FACTOR) / liquidityMetrics.targetParticipants;

        uint256 volumeRatio = dailyVolume > liquidityMetrics.targetVolume ?
            SCALE_FACTOR : (dailyVolume * SCALE_FACTOR) / liquidityMetrics.targetVolume;

        uint256 reserveRatio = stabilityReserve > liquidityMetrics.requiredReserve ?
            SCALE_FACTOR : (stabilityReserve * SCALE_FACTOR) / liquidityMetrics.requiredReserve;

        // Take minimum as overall health index
        uint256 healthIndex = participantRatio;
        if (volumeRatio < healthIndex) healthIndex = volumeRatio;
        if (reserveRatio < healthIndex) healthIndex = reserveRatio;

        // Update metrics
        liquidityMetrics.liquidityHealthIndex = healthIndex;
        liquidityMetrics.activeParticipants = activeParticipants;
        liquidityMetrics.dailyVolume = dailyVolume;
        liquidityMetrics.stabilityReserve = stabilityReserve;
        liquidityMetrics.lastUpdate = block.timestamp;

        // Check for emergency conditions
        if (healthIndex < HALT_THRESHOLD) {
            economicConfig.emergencyMode = true;
            emit EmergencyModeActivated("Liquidity health below halt threshold", block.timestamp);
        } else if (healthIndex < EMERGENCY_THRESHOLD && !economicConfig.emergencyMode) {
            economicConfig.emergencyMode = true;
            emit EmergencyModeActivated("Liquidity health in emergency zone", block.timestamp);
        } else if (healthIndex > EMERGENCY_THRESHOLD * 2 && economicConfig.emergencyMode) {
            economicConfig.emergencyMode = false;
        }

        emit LiquidityMetricsUpdated(healthIndex, volatilityMetrics.marketPressure, block.timestamp);
    }

    /**
     * @dev Update market volatility metrics
     * Formula: Market_Pressure = |current_price - target_price| / target_price
     */
    function updateVolatilityMetrics(
        uint256 currentPrice,
        uint256 targetPrice,
        uint256 transactionVolume,
        uint256 crossChainTransfers
    ) external onlyOwner {
        // Calculate market pressure
        uint256 priceDeviation = currentPrice > targetPrice ? 
            currentPrice - targetPrice : targetPrice - currentPrice;
        uint256 marketPressure = (priceDeviation * SCALE_FACTOR) / targetPrice;

        // Cap market pressure at maximum
        if (marketPressure > MAX_MARKET_PRESSURE) {
            marketPressure = MAX_MARKET_PRESSURE;
        }

        // Calculate network utility score
        uint256 transactionRatio = (transactionVolume * SCALE_FACTOR) / volatilityMetrics.targetTransactionVolume;
        uint256 crossChainRatio = (crossChainTransfers * SCALE_FACTOR) / volatilityMetrics.targetCrossChainTransfers;
        uint256 networkUtilityScore = (transactionRatio + crossChainRatio) / 2;

        // Update volatility metrics
        volatilityMetrics.marketPressure = marketPressure;
        volatilityMetrics.priceDeviation = priceDeviation;
        volatilityMetrics.transactionVolume = transactionVolume;
        volatilityMetrics.crossChainTransfers = crossChainTransfers;
        volatilityMetrics.volatilityScore = (marketPressure + (SCALE_FACTOR - networkUtilityScore)) / 2;
        volatilityMetrics.lastUpdate = block.timestamp;

        emit LiquidityMetricsUpdated(liquidityMetrics.liquidityHealthIndex, marketPressure, block.timestamp);
    }

    /**
     * @dev Update network health for a specific chain
     */
    function updateNetworkHealth(
        address network,
        uint256 settlementRate,
        uint256 averageLatency,
        uint256 capacityUtilization
    ) external onlyOwner {
        // Calculate quality score based on metrics
        uint256 qualityScore = _calculateNetworkQualityScore(
            settlementRate,
            averageLatency,
            capacityUtilization
        );

        // Update network health
        NetworkHealth storage health = networkHealth[network];
        if (health.networkAddress == address(0)) {
            // New network
            monitoredNetworks.push(network);
            totalNetworks++;
            health.networkAddress = network;
            health.isActive = true;
        }

        health.settlementRate = settlementRate;
        health.averageLatency = averageLatency;
        health.capacityUtilization = capacityUtilization;
        health.qualityScore = qualityScore;
        health.lastHealthCheck = block.timestamp;

        emit NetworkHealthUpdated(network, qualityScore, block.timestamp);
    }

    /**
     * @dev Calculate rate limiting threshold based on current conditions
     * Formula: Rate_Limit = base_limit * Liquidity_Health_Index * (1 / sqrt(Market_Pressure + 1))
     */
    function calculateRateLimitThreshold() external view returns (uint256) {
        uint256 baseLimit = 100; // Base rate limit (100 transactions per unit time)

        // Liquidity health factor
        uint256 liquidityFactor = liquidityMetrics.liquidityHealthIndex;

        // Market pressure adjustment
        uint256 pressureAdjustment = _sqrt(volatilityMetrics.marketPressure + SCALE_FACTOR);
        uint256 pressureFactor = (SCALE_FACTOR * SCALE_FACTOR) / pressureAdjustment;

        // Calculate final threshold
        uint256 threshold = (baseLimit * liquidityFactor * pressureFactor) / (SCALE_FACTOR * SCALE_FACTOR);

        return threshold;
    }

    /**
     * @dev Determine if cross-chain rerouting should be triggered
     */
    function shouldTriggerReroute(address network) external view returns (bool, address) {
        NetworkHealth memory health = networkHealth[network];

        // Check if network quality is below threshold
        if (health.qualityScore < 300 || health.capacityUtilization > 900) { // 30% quality or 90% capacity
            // Find alternative network
            address bestAlternative = _findBestAlternativeNetwork(network);
            if (bestAlternative != address(0)) {
                return (true, bestAlternative);
            }
        }

        return (false, address(0));
    }

    /**
     * @dev Update host performance score
     */
    function updateHostPerformance(
        address host,
        bool success,
        uint256 latency,
        uint256 expectedLatency
    ) external onlyOwner {
        uint256 currentScore = hostPerformanceScores[host];
        if (currentScore == 0) {
            currentScore = 500; // Start with neutral score
        }

        // Performance adjustment based on success and latency
        int256 adjustment = 0;

        if (success) {
            adjustment += 10; // +10 for successful routing
            if (latency < expectedLatency) {
                adjustment += int256((expectedLatency - latency) * 5 / expectedLatency); // Bonus for better latency
            }
        } else {
            adjustment -= 50; // -50 for failed routing
        }

        // Apply adjustment with bounds checking
        int256 newScore = int256(currentScore) + adjustment;
        if (newScore < 0) newScore = 0;
        if (newScore > 1000) newScore = 1000;

        hostPerformanceScores[host] = uint256(newScore);
    }

    /**
     * @dev Get network health metrics
     */
    function getNetworkHealth() external view returns (
        uint256 activeNodeCount,
        uint256 avgSuccessRate,
        uint256 avgLatency,
        uint256 totalValidations,
        uint256 emergencyModeStatus
    ) {
        activeNodeCount = activeNodes.length;

        uint256 totalSuccessRate = 0;
        uint256 totalLatency = 0;
        uint256 activeCount = 0;

        for (uint256 i = 0; i < activeNodes.length; i++) {
            if (nodes[activeNodes[i]].isActive) {
                totalSuccessRate += nodes[activeNodes[i]].successRate;
                totalLatency += nodes[activeNodes[i]].avgLatency;
                activeCount++;
            }
        }

        avgSuccessRate = activeCount > 0 ? totalSuccessRate / activeCount : 0;
        avgLatency = activeCount > 0 ? totalLatency / activeCount : 0;
        totalValidations = pendingValidations.length;
        emergencyModeStatus = economicConfig.emergencyMode ? 1 : 0;
    }

    /**
     * @dev Get comprehensive economic parameters for current conditions
     */
    function getEconomicParameters() external view returns (EconomicParameters memory) {
        return EconomicParameters({
            dynamicGasFee: this.calculateDynamicGasFee(),
            hostReward: 0, // Calculated per transaction
            performanceMultiplier: 0, // Calculated per host
            crossChainBonus: economicConfig.crossChainBonusRate,
            rateLimitThreshold: this.calculateRateLimitThreshold(),
            rearouteThreshold: 300 // 30% network quality threshold
        });
    }

    // Internal helper functions

    /**
     * @dev Calculate performance multiplier based on score
     * Range: 50% to 200% (0.5x to 2.0x)
     */
    function _calculatePerformanceMultiplier(uint256 performanceScore) internal pure returns (uint256) {
        // Linear scaling: 0 score = 0.5x, 500 score = 1.0x, 1000 score = 2.0x
        return 500 + (performanceScore * 1500) / 1000; // Range: 500-2000 (0.5x-2.0x)
    }

    /**
     * @dev Calculate network quality score
     */
    function _calculateNetworkQualityScore(
        uint256 settlementRate,
        uint256 averageLatency,
        uint256 capacityUtilization
    ) internal pure returns (uint256) {
        // Settlement rate weight: 50%
        uint256 settlementScore = (settlementRate * 500) / SCALE_FACTOR;

        // Latency score weight: 30% (lower latency = higher score)
        uint256 maxLatency = 10000; // 10 seconds max
        uint256 latencyScore = averageLatency > maxLatency ? 0 : 
            ((maxLatency - averageLatency) * 300) / maxLatency;

        // Capacity utilization weight: 20% (optimal at 70%)
        uint256 optimalCapacity = 700;
        uint256 capacityDiff = capacityUtilization > optimalCapacity ?
            capacityUtilization - optimalCapacity : optimalCapacity - capacityUtilization;
        uint256 capacityScore = capacityDiff > optimalCapacity ? 0 :
            ((optimalCapacity - capacityDiff) * 200) / optimalCapacity;

        return settlementScore + latencyScore + capacityScore;
    }

    /**
     * @dev Find best alternative network for rerouting
     */
    function _findBestAlternativeNetwork(address excludeNetwork) internal view returns (address) {
        address bestNetwork = address(0);
        uint256 bestScore = 0;

        for (uint256 i = 0; i < monitoredNetworks.length; i++) {
            address network = monitoredNetworks[i];
            if (network != excludeNetwork && networkHealth[network].isActive) {
                uint256 score = networkHealth[network].qualityScore;
                if (score > bestScore) {
                    bestScore = score;
                    bestNetwork = network;
                }
            }
        }

        return bestNetwork;
    }

    /**
     * @dev Square root approximation using Babylonian method
     */
    function _sqrt(uint256 x) internal pure returns (uint256) {
        if (x == 0) return 0;

        uint256 z = (x + 1) / 2;
        uint256 y = x;

        while (z < y) {
            y = z;
            z = (x / z + z) / 2;
        }

        return y;
    }

    /**
     * @dev Emergency functions (owner only)
     */
    function activateEmergencyMode(string calldata reason) external onlyOwner {
        economicConfig.emergencyMode = true;
        emit EmergencyModeActivated(reason, block.timestamp);
    }

    function deactivateEmergencyMode() external onlyOwner {
        economicConfig.emergencyMode = false;
    }

    function updateEconomicConfig(EconomicConfig calldata newConfig) external onlyOwner {
        economicConfig = newConfig;
    }

    /**
     * @dev Receive function for fee collection
     */
    receive() external payable {
        // Fees collected for economic calculations
    }
}

contracts/hypermesh/HostRewardDistributo.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./DynamicEconomicsOracle.sol";
import "./HypermeshNetworkManager.sol";

/**
 * @title HostRewardDistributor
 * @dev Merit-based reward distribution system for transaction routing hosts
 * 
 * Implements comprehensive reward sharing based on:
 * - Transaction routing performance and success rates
 * - Cross-chain bridging and network utility contributions
 * - Stake-neutral reward distribution ensuring equal opportunities
 * - Anti-gaming mechanisms and Sybil protection
 */
contract HostRewardDistributor is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // Reward distribution configuration
    struct RewardConfig {
        uint256 baseRewardPercentage;       // Base reward percentage for routing hosts (default: 70%)
        uint256 performanceBonusMax;        // Maximum performance bonus multiplier (default: 2x)
        uint256 crossChainBonusRate;        // Additional bonus for cross-chain routing (default: 5%)
        uint256 networkUtilityBonusRate;    // Bonus for network utility contributions (default: 3%)
        uint256 minimumRoutingThreshold;    // Minimum transactions before earning rewards
        uint256 rewardDecayRate;            // Daily reward decay rate for inactive hosts
        uint256 maxRewardAccumulation;      // Maximum reward accumulation period (days)
        bool stakingRequirementEnabled;     // Enable/disable staking requirements (should be false)
    }

    // Host reward tracking
    struct HostRewards {
        address hostAddress;                // Host wallet address
        uint256 totalEarned;                // Total rewards earned lifetime
        uint256 totalRouted;                // Total transactions successfully routed
        uint256 successfulTransactions;     // Number of successful transactions
        uint256 failedTransactions;         // Number of failed transactions
        uint256 totalLatencySeconds;        // Cumulative latency for averaging
        uint256 crossChainTransactions;     // Cross-chain transactions routed
        uint256 lastRewardClaim;            // Last reward claim timestamp
        uint256 pendingRewards;             // Unclaimed rewards balance
        uint256 reputationScore;            // Long-term reputation (0-1000)
        bool isActive;                      // Active status
    }

    // Reward distribution event tracking
    struct RewardDistribution {
        bytes32 transactionId;              // Associated transaction ID
        address host;                       // Reward recipient
        uint256 baseReward;                 // Base routing reward
        uint256 performanceBonus;           // Performance-based bonus
        uint256 crossChainBonus;            // Cross-chain routing bonus
        uint256 networkUtilityBonus;        // Network utility bonus
        uint256 totalReward;                // Total reward distributed
        uint256 timestamp;                  // Distribution timestamp
        string reason;                      // Reward distribution reason
    }

    // Network utility contribution tracking
    struct NetworkContribution {
        uint256 liquidityProvided;         // Liquidity provided to network
        uint256 uptimeSeconds;              // Host uptime contribution
        uint256 networkStabilizationActions; // Actions contributing to network stability
        uint256 crossChainBridgeVolume;     // Volume facilitated in cross-chain bridging
        uint256 lastContributionUpdate;    // Last contribution update timestamp
    }

    // Reward pool management
    struct RewardPool {
        uint256 totalPoolSize;              // Total rewards available for distribution
        uint256 distributedRewards;         // Total rewards distributed
        uint256 pendingDistributions;       // Pending reward distributions
        uint256 reserveAmount;              // Reserve fund amount
        uint256 lastPoolUpdate;             // Last pool size update
        bool emergencyWithdrawEnabled;      // Emergency withdrawal status
    }

    // State variables
    RewardConfig public rewardConfig;
    RewardPool public rewardPool;
    DynamicEconomicsOracle public economicsOracle;
    HypermeshNetworkManager public networkManager;
    IERC20 public rewardToken;

    mapping(address => HostRewards) public hostRewards;
    mapping(bytes32 => RewardDistribution) public rewardDistributions;
    mapping(address => NetworkContribution) public networkContributions;
    mapping(address => bool) public authorizedDistributors;

    address[] public activeHosts;
    bytes32[] public recentDistributions;

    uint256 public totalHosts;
    uint256 public totalRewardsDistributed;
    uint256 public totalTransactionsProcessed;

    // Anti-gaming and security
    mapping(address => uint256) public lastActivityTimestamp;
    mapping(address => uint256) public dailyRewardCap;
    mapping(bytes32 => bool) public processedTransactions;

    // Events
    event RewardDistributed(
        address indexed host,
        bytes32 indexed transactionId,
        uint256 baseReward,
        uint256 totalReward,
        string reason
    );
    event HostRegistered(address indexed host, uint256 timestamp);
    event HostDeactivated(address indexed host, string reason);
    event RewardClaimed(address indexed host, uint256 amount, uint256 timestamp);
    event NetworkContributionUpdated(address indexed host, uint256 contributionType, uint256 amount);
    event RewardPoolUpdated(uint256 newPoolSize, uint256 reserveAmount);
    event EmergencyWithdrawal(address indexed host, uint256 amount, string reason);
    event PerformanceMetricsUpdated(address indexed host, uint256 successRate, uint256 avgLatency);

    constructor(
        address owner,
        address payable _economicsOracle,
        address payable _networkManager,
        address _rewardToken
    ) Ownable(owner) {
        economicsOracle = DynamicEconomicsOracle(_economicsOracle);
        networkManager = HypermeshNetworkManager(_networkManager);
        rewardToken = IERC20(_rewardToken);

        // Initialize reward configuration (stake-neutral design)
        rewardConfig = RewardConfig({
            baseRewardPercentage: 700,          // 70% of transaction fees to hosts
            performanceBonusMax: 2000,          // 2x maximum performance bonus
            crossChainBonusRate: 50,            // 5% cross-chain bonus
            networkUtilityBonusRate: 30,        // 3% network utility bonus
            minimumRoutingThreshold: 10,        // Minimum 10 transactions before rewards
            rewardDecayRate: 50,                // 5% daily decay for inactive hosts
            maxRewardAccumulation: 7,           // Maximum 7 days reward accumulation
            stakingRequirementEnabled: false    // NO staking requirements (stake-neutral)
        });

        // Initialize reward pool
        rewardPool = RewardPool({
            totalPoolSize: 0,
            distributedRewards: 0,
            pendingDistributions: 0,
            reserveAmount: 0,
            lastPoolUpdate: block.timestamp,
            emergencyWithdrawEnabled: false
        });

        // Authorize this contract and economics oracle as distributors
        authorizedDistributors[address(this)] = true;
        authorizedDistributors[address(_economicsOracle)] = true;
    }

    /**
     * @dev Register host for reward distribution (stake-neutral)
     */
    function registerHost() external {
        require(hostRewards[msg.sender].hostAddress == address(0), "Host already registered");

        // No staking requirements - purely stake-neutral registration
        hostRewards[msg.sender] = HostRewards({
            hostAddress: msg.sender,
            totalEarned: 0,
            totalRouted: 0,
            successfulTransactions: 0,
            failedTransactions: 0,
            totalLatencySeconds: 0,
            crossChainTransactions: 0,
            lastRewardClaim: block.timestamp,
            pendingRewards: 0,
            reputationScore: 500,               // Start with neutral reputation
            isActive: true
        });

        activeHosts.push(msg.sender);
        totalHosts++;
        lastActivityTimestamp[msg.sender] = block.timestamp;

        emit HostRegistered(msg.sender, block.timestamp);
    }

    /**
     * @dev Distribute rewards for successful transaction routing
     * Called by authorized contracts (HypermeshNetworkManager, DynamicEconomicsOracle)
     */
    function distributeTransactionReward(
        bytes32 transactionId,
        address host,
        uint256 transactionFee,
        bool isCrossChain,
        uint256 actualLatency,
        bool success
    ) external nonReentrant {
        require(authorizedDistributors[msg.sender], "Unauthorized distributor");
        require(hostRewards[host].hostAddress != address(0), "Host not registered");
        require(!processedTransactions[transactionId], "Transaction already processed");

        processedTransactions[transactionId] = true;

        // Update host performance metrics
        _updateHostMetrics(host, success, actualLatency, isCrossChain);

        if (!success) {
            // No reward for failed transactions, but track metrics
            return;
        }

        // Calculate rewards based on current configuration and performance
        (uint256 baseReward, uint256 performanceBonus, uint256 crossChainBonus, uint256 utilityBonus) = 
            _calculateHostReward(host, transactionFee, isCrossChain);

        uint256 totalReward = baseReward + performanceBonus + crossChainBonus + utilityBonus;

        // Apply daily reward cap protection
        if (_checkDailyRewardCap(host, totalReward)) {
            // Update pending rewards
            hostRewards[host].pendingRewards += totalReward;
            rewardPool.pendingDistributions += totalReward;

            // Record distribution
            rewardDistributions[transactionId] = RewardDistribution({
                transactionId: transactionId,
                host: host,
                baseReward: baseReward,
                performanceBonus: performanceBonus,
                crossChainBonus: crossChainBonus,
                networkUtilityBonus: utilityBonus,
                totalReward: totalReward,
                timestamp: block.timestamp,
                reason: "Transaction routing reward"
            });

            recentDistributions.push(transactionId);
            totalRewardsDistributed += totalReward;
            totalTransactionsProcessed++;

            emit RewardDistributed(host, transactionId, baseReward, totalReward, "Transaction routing");
        }

        lastActivityTimestamp[host] = block.timestamp;
    }

    /**
     * @dev Calculate comprehensive reward for host based on performance and contribution
     * Implements formulas from Factor 1, 2, and 3 specifications
     */
    function _calculateHostReward(
        address host,
        uint256 transactionFee,
        bool isCrossChain
    ) internal view returns (uint256 baseReward, uint256 performanceBonus, uint256 crossChainBonus, uint256 utilityBonus) {
        HostRewards memory hostData = hostRewards[host];

        // Base reward calculation (70% of transaction fee)
        baseReward = (transactionFee * rewardConfig.baseRewardPercentage) / 1000;

        // Performance bonus calculation based on success rate and latency
        uint256 successRate = hostData.totalRouted > 0 ? 
            (hostData.successfulTransactions * 1000) / hostData.totalRouted : 1000;
        uint256 avgLatency = hostData.successfulTransactions > 0 ? 
            hostData.totalLatencySeconds / hostData.successfulTransactions : 5000;

        // Performance multiplier: combines success rate (40%) + latency performance (30%) + reputation (30%)
        uint256 performanceMultiplier = _calculatePerformanceMultiplier(successRate, avgLatency, hostData.reputationScore);
        performanceBonus = (baseReward * (performanceMultiplier - 1000)) / 1000; // Subtract base multiplier

        // Cross-chain bonus (5% additional for cross-chain transactions)
        if (isCrossChain) {
            crossChainBonus = (baseReward * rewardConfig.crossChainBonusRate) / 1000;
        }

        // Network utility bonus based on overall contribution
        NetworkContribution memory contribution = networkContributions[host];
        uint256 utilityMultiplier = _calculateNetworkUtilityMultiplier(contribution);
        utilityBonus = (baseReward * utilityMultiplier) / 1000;

        return (baseReward, performanceBonus, crossChainBonus, utilityBonus);
    }

    /**
     * @dev Calculate performance multiplier based on host metrics
     * Formula: Performance_Multiplier = (Success_Rate * 0.4) + (Avg_Latency_Score * 0.3) + (Reputation * 0.3)
     */
    function _calculatePerformanceMultiplier(
        uint256 successRate,
        uint256 avgLatency,
        uint256 reputationScore
    ) internal view returns (uint256) {
        // Success rate component (40% weight) - range 0-1000
        uint256 successComponent = (successRate * 400) / 1000;

        // Latency performance component (30% weight) - better latency = higher score
        uint256 targetLatency = 5000; // 5 seconds target
        uint256 latencyScore = avgLatency > targetLatency ? 
            (targetLatency * 1000) / avgLatency : 1000;
        uint256 latencyComponent = (latencyScore * 300) / 1000;

        // Reputation component (30% weight)
        uint256 reputationComponent = (reputationScore * 300) / 1000;

        // Total multiplier (base 1000 = 1x, max 2000 = 2x)
        uint256 totalMultiplier = 1000 + successComponent + latencyComponent + reputationComponent;

        // Cap at maximum bonus
        if (totalMultiplier > rewardConfig.performanceBonusMax) {
            totalMultiplier = rewardConfig.performanceBonusMax;
        }

        return totalMultiplier;
    }

    /**
     * @dev Calculate network utility multiplier for additional bonuses
     */
    function _calculateNetworkUtilityMultiplier(NetworkContribution memory contribution) internal view returns (uint256) {
        uint256 utilityScore = 0;

        // Liquidity provision bonus
        if (contribution.liquidityProvided > 1 ether) {
            utilityScore += 10; // 1% bonus for significant liquidity provision
        }

        // Uptime bonus (for hosts with > 90% uptime)
        uint256 daysSinceUpdate = (block.timestamp - contribution.lastContributionUpdate) / 86400;
        if (daysSinceUpdate > 0) {
            uint256 uptimePercentage = (contribution.uptimeSeconds * 100) / (daysSinceUpdate * 86400);
            if (uptimePercentage > 90) {
                utilityScore += 15; // 1.5% bonus for high uptime
            }
        }

        // Network stabilization actions bonus
        if (contribution.networkStabilizationActions > 10) {
            utilityScore += 5; // 0.5% bonus for stabilization contributions
        }

        return utilityScore;
    }

    /**
     * @dev Update host performance metrics after transaction
     */
    function _updateHostMetrics(address host, bool success, uint256 actualLatency, bool isCrossChain) internal {
        HostRewards storage hostData = hostRewards[host];

        hostData.totalRouted++;

        if (success) {
            hostData.successfulTransactions++;
            hostData.totalLatencySeconds += actualLatency;

            if (isCrossChain) {
                hostData.crossChainTransactions++;
            }

            // Improve reputation for successful transactions
            if (hostData.reputationScore < 1000) {
                hostData.reputationScore += 2; // Small reputation increase
            }
        } else {
            hostData.failedTransactions++;

            // Decrease reputation for failed transactions
            if (hostData.reputationScore > 10) {
                hostData.reputationScore -= 10; // Larger reputation decrease for failures
            }
        }

        emit PerformanceMetricsUpdated(
            host,
            hostData.totalRouted > 0 ? (hostData.successfulTransactions * 1000) / hostData.totalRouted : 0,
            hostData.successfulTransactions > 0 ? hostData.totalLatencySeconds / hostData.successfulTransactions : 0
        );
    }

    /**
     * @dev Check daily reward cap to prevent gaming
     */
    function _checkDailyRewardCap(address host, uint256 rewardAmount) internal returns (bool) {
        uint256 today = block.timestamp / 86400; // Get current day
        uint256 lastRewardDay = lastActivityTimestamp[host] / 86400;

        // Reset daily cap if new day
        if (today > lastRewardDay) {
            dailyRewardCap[host] = 0;
        }

        // Check if adding this reward would exceed daily cap
        uint256 maxDailyCap = rewardPool.totalPoolSize / 100; // 1% of total pool per day max
        if (dailyRewardCap[host] + rewardAmount > maxDailyCap) {
            return false; // Exceeds daily cap
        }

        dailyRewardCap[host] += rewardAmount;
        return true;
    }

    /**
     * @dev Claim pending rewards (stake-neutral)
     */
    function claimRewards() external nonReentrant whenNotPaused {
        HostRewards storage hostData = hostRewards[msg.sender];
        require(hostData.hostAddress != address(0), "Host not registered");
        require(hostData.pendingRewards > 0, "No pending rewards");
        require(hostData.totalRouted >= rewardConfig.minimumRoutingThreshold, "Insufficient routing activity");

        uint256 claimAmount = hostData.pendingRewards;

        // Apply reward decay if host has been inactive
        uint256 daysSinceLastClaim = (block.timestamp - hostData.lastRewardClaim) / 86400;
        if (daysSinceLastClaim > rewardConfig.maxRewardAccumulation) {
            // Apply decay for extended inactivity
            uint256 decayFactor = 1000 - (rewardConfig.rewardDecayRate * daysSinceLastClaim);
            if (decayFactor < 500) decayFactor = 500; // Minimum 50% retention
            claimAmount = (claimAmount * decayFactor) / 1000;
        }

        // Ensure sufficient pool balance
        require(rewardToken.balanceOf(address(this)) >= claimAmount, "Insufficient reward pool");

        // Update host data
        hostData.pendingRewards = 0;
        hostData.totalEarned += claimAmount;
        hostData.lastRewardClaim = block.timestamp;

        // Update pool data
        rewardPool.distributedRewards += claimAmount;
        rewardPool.pendingDistributions -= hostData.pendingRewards + claimAmount;

        // Transfer rewards
        rewardToken.safeTransfer(msg.sender, claimAmount);

        emit RewardClaimed(msg.sender, claimAmount, block.timestamp);
    }

    /**
     * @dev Update network contribution metrics
     */
    function updateNetworkContribution(
        address host,
        uint256 liquidityProvided,
        uint256 uptimeSeconds,
        uint256 stabilizationActions
    ) external {
        require(authorizedDistributors[msg.sender] || msg.sender == host, "Unauthorized");

        NetworkContribution storage contribution = networkContributions[host];
        contribution.liquidityProvided = liquidityProvided;
        contribution.uptimeSeconds += uptimeSeconds;
        contribution.networkStabilizationActions += stabilizationActions;
        contribution.lastContributionUpdate = block.timestamp;

        emit NetworkContributionUpdated(host, 1, liquidityProvided);
    }

    /**
     * @dev Get comprehensive host statistics
     */
    function getHostStatistics(address host) external view returns (
        uint256 totalEarned,
        uint256 pendingRewards,
        uint256 successRate,
        uint256 averageLatency,
        uint256 reputationScore,
        uint256 totalRouted,
        uint256 crossChainTransactions,
        bool isActive
    ) {
        HostRewards memory hostData = hostRewards[host];

        uint256 avgLatency = hostData.successfulTransactions > 0 ? 
            hostData.totalLatencySeconds / hostData.successfulTransactions : 0;
        uint256 successRatePercent = hostData.totalRouted > 0 ? 
            (hostData.successfulTransactions * 1000) / hostData.totalRouted : 0;

        return (
            hostData.totalEarned,
            hostData.pendingRewards,
            successRatePercent,
            avgLatency,
            hostData.reputationScore,
            hostData.totalRouted,
            hostData.crossChainTransactions,
            hostData.isActive
        );
    }

    /**
     * @dev Get system-wide reward statistics
     */
    function getSystemRewardStatistics() external view returns (
        uint256 totalPoolSize,
        uint256 totalDistributed,
        uint256 totalPending,
        uint256 totalActiveHosts,
        uint256 systemTransactionsProcessed,
        uint256 averageRewardPerTransaction
    ) {
        uint256 avgReward = totalTransactionsProcessed > 0 ? 
            totalRewardsDistributed / totalTransactionsProcessed : 0;

        return (
            rewardPool.totalPoolSize,
            rewardPool.distributedRewards,
            rewardPool.pendingDistributions,
            activeHosts.length,
            totalTransactionsProcessed,
            avgReward
        );
    }

    /**
     * @dev Fund reward pool
     */
    function fundRewardPool(uint256 amount) external {
        require(amount > 0, "Invalid amount");

        rewardToken.safeTransferFrom(msg.sender, address(this), amount);
        rewardPool.totalPoolSize += amount;
        rewardPool.lastPoolUpdate = block.timestamp;

        emit RewardPoolUpdated(rewardPool.totalPoolSize, rewardPool.reserveAmount);
    }

    /**
     * @dev Emergency functions (owner only)
     */
    function emergencyWithdrawHost(address host, string calldata reason) external onlyOwner {
        require(rewardPool.emergencyWithdrawEnabled, "Emergency withdraw disabled");

        HostRewards storage hostData = hostRewards[host];
        uint256 amount = hostData.pendingRewards;

        if (amount > 0) {
            hostData.pendingRewards = 0;
            rewardPool.pendingDistributions -= amount;

            rewardToken.safeTransfer(host, amount);
            emit EmergencyWithdrawal(host, amount, reason);
        }
    }

    function setEmergencyWithdrawEnabled(bool enabled) external onlyOwner {
        rewardPool.emergencyWithdrawEnabled = enabled;
    }

    function updateRewardConfig(RewardConfig calldata newConfig) external onlyOwner {
        // Enforce stake-neutral design
        require(!newConfig.stakingRequirementEnabled, "Staking requirements not allowed");
        rewardConfig = newConfig;
    }

    function addAuthorizedDistributor(address distributor) external onlyOwner {
        authorizedDistributors[distributor] = true;
    }

    function removeAuthorizedDistributor(address distributor) external onlyOwner {
        authorizedDistributors[distributor] = false;
    }

    /**
     * @dev Receive function for direct ETH rewards
     */
    receive() external payable {
        rewardPool.totalPoolSize += msg.value;
        emit RewardPoolUpdated(rewardPool.totalPoolSize, rewardPool.reserveAmount);
    }
}

contracts/hypermesh/HypermeshNetworkMana.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.22;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title HypermeshNetworkManager
 * @dev Main coordinator contract for Hypermesh network-matrix system
 * 
 * Implements consensus proof mechanism via distribution via hops and sharding
 * Eliminates traditional PoS/PoW in favor of hop-based validation
 */
contract HypermeshNetworkManager is Ownable, ReentrancyGuard, Pausable {

    // Network configuration
    struct NetworkConfig {
        uint256 minHops;                    // Minimum hops for consensus (default: 3)
        uint256 optimalHops;                // Optimal hops for validation (default: 5-7)
        uint256 maxHops;                    // Maximum hops before timeout (default: 10)
        uint256 shardCount;                 // Number of active shards
        uint256 hopTimeoutMs;               // Timeout per hop in milliseconds
        uint256 consensusThreshold;         // Minimum nodes for consensus (67%)
        bool emergencyMode;                 // Emergency circuit breaker status
    }

    // Node registration and performance tracking
    struct NetworkNode {
        address nodeAddress;                // Node wallet address
        bytes32 deviceFingerprint;          // Unique device identifier
        uint256 successRate;                // Historical success rate (0-1000)
        uint256 avgLatency;                 // Average latency in milliseconds
        uint256 reputationScore;            // Long-term reputation (0-1000)
        uint256 totalRouted;                // Total transactions routed
        uint256 lastActivity;               // Last activity timestamp
        bool isActive;                      // Active status
        bool isBlacklisted;                 // Blacklist status for bad actors
    }

    // Hop validation tracking
    struct HopValidation {
        bytes32 transactionId;              // Unique transaction identifier
        address[] hopPath;                  // Ordered list of hop nodes
        uint256[] hopTimestamps;            // Timestamp of each hop completion
        bytes32[] hopProofs;                // Cryptographic proof from each hop
        uint256 totalHops;                  // Number of hops completed
        uint256 startTime;                  // Transaction start time
        ValidationStatus status;            // Current validation status
        address originChain;                // Origin chain/network
        address targetChain;                // Target chain/network
    }

    enum ValidationStatus {
        PENDING,        // Awaiting hop completion
        IN_PROGRESS,    // Hops in progress
        COMPLETED,      // All hops validated successfully
        FAILED,         // Hop validation failed
        TIMEOUT         // Validation timed out
    }

    // Shard management
    struct NetworkShard {
        uint256 shardId;                    // Unique shard identifier
        address[] assignedNodes;            // Nodes assigned to this shard
        uint256 transactionCount;           // Transactions processed by shard
        uint256 loadFactor;                 // Current load (0-1000, where 1000 = 100%)
        uint256 avgLatency;                 // Average processing latency
        bool isActive;                      // Shard active status
    }

    // State variables
    NetworkConfig public networkConfig;
    mapping(address => NetworkNode) public nodes;
    mapping(bytes32 => HopValidation) public validations;
    mapping(uint256 => NetworkShard) public shards;

    address[] public activeNodes;           // List of active node addresses
    bytes32[] public pendingValidations;    // Queue of pending validations
    uint256 public totalNodes;              // Total registered nodes
    uint256 public activeShardCount;        // Number of active shards

    // Economic parameters (integrated with CAES economics)
    uint256 public baseRewardRate = 1000;          // Base reward per successful route (0.1%)
    uint256 public performanceBonusMultiplier = 2000; // Max performance bonus (2x)
    uint256 public hostRewardPercentage = 700;     // 70% of fees go to routing hosts
    uint256 public crossChainBonusRate = 500;      // 0.05% bonus for cross-chain routing

    // Events
    event NodeRegistered(address indexed node, bytes32 deviceFingerprint);
    event NodeDeactivated(address indexed node, string reason);
    event ValidationStarted(bytes32 indexed transactionId, address[] hopPath);
    event HopCompleted(bytes32 indexed transactionId, address node, uint256 hopIndex, bytes32 proof);
    event ValidationCompleted(bytes32 indexed transactionId, bool success, uint256 totalTime);
    event ShardCreated(uint256 indexed shardId, address[] assignedNodes);
    event ShardRebalanced(uint256 indexed shardId, address[] newNodes);
    event EmergencyModeActivated(string reason);
    event RewardDistributed(address indexed node, uint256 amount, string reason);

    constructor(address owner) Ownable(owner) {
        // Initialize default network configuration
        networkConfig = NetworkConfig({
            minHops: 3,
            optimalHops: 5,
            maxHops: 10,
            shardCount: 3,              // Start with 3 shards
            hopTimeoutMs: 2000,         // 2 second timeout per hop
            consensusThreshold: 670,    // 67% consensus requirement
            emergencyMode: false
        });

        activeShardCount = networkConfig.shardCount;

        // Initialize shards
        for (uint256 i = 0; i < networkConfig.shardCount; i++) {
            shards[i] = NetworkShard({
                shardId: i,
                assignedNodes: new address[](0),
                transactionCount: 0,
                loadFactor: 0,
                avgLatency: 0,
                isActive: true
            });
        }
    }

    /**
     * @dev Register a new node in the network (stake-neutral)
     * @param deviceFingerprint Unique device identifier for Sybil protection
     */
    function registerNode(bytes32 deviceFingerprint) external {
        require(nodes[msg.sender].nodeAddress == address(0), "Node already registered");
        require(deviceFingerprint != bytes32(0), "Invalid device fingerprint");

        // Check for duplicate device fingerprints (Sybil protection)
        for (uint256 i = 0; i < activeNodes.length; i++) {
            require(nodes[activeNodes[i]].deviceFingerprint != deviceFingerprint, 
                    "Device already registered");
        }

        nodes[msg.sender] = NetworkNode({
            nodeAddress: msg.sender,
            deviceFingerprint: deviceFingerprint,
            successRate: 1000,         // Start with perfect score
            avgLatency: 1000,           // Default 1 second latency
            reputationScore: 500,       // Start with neutral reputation
            totalRouted: 0,
            lastActivity: block.timestamp,
            isActive: true,
            isBlacklisted: false
        });

        activeNodes.push(msg.sender);
        totalNodes++;

        // Assign to least loaded shard
        _assignNodeToShard(msg.sender);

        emit NodeRegistered(msg.sender, deviceFingerprint);
    }

    /**
     * @dev Start hop-based validation for a transaction
     * @param transactionId Unique transaction identifier
     * @param originChain Origin network/chain
     * @param targetChain Target network/chain
     */
    function startHopValidation(
        bytes32 transactionId,
        address originChain,
        address targetChain
    ) external nonReentrant whenNotPaused returns (address[] memory hopPath) {
        require(transactionId != bytes32(0), "Invalid transaction ID");
        require(validations[transactionId].transactionId == bytes32(0), "Validation already exists");
        require(activeNodes.length >= networkConfig.minHops, "Insufficient active nodes");

        // Generate random hop path (stake-neutral selection)
        hopPath = _generateHopPath(networkConfig.optimalHops);

        validations[transactionId] = HopValidation({
            transactionId: transactionId,
            hopPath: hopPath,
            hopTimestamps: new uint256[](hopPath.length),
            hopProofs: new bytes32[](hopPath.length),
            totalHops: hopPath.length,
            startTime: block.timestamp,
            status: ValidationStatus.PENDING,
            originChain: originChain,
            targetChain: targetChain
        });

        pendingValidations.push(transactionId);

        emit ValidationStarted(transactionId, hopPath);
        return hopPath;
    }

    /**
     * @dev Submit hop completion proof
     * @param transactionId Transaction being validated
     * @param hopIndex Index of completed hop
     * @param proof Cryptographic proof of hop completion
     */
    function submitHopProof(
        bytes32 transactionId,
        uint256 hopIndex,
        bytes32 proof
    ) external {
        HopValidation storage validation = validations[transactionId];
        require(validation.transactionId != bytes32(0), "Validation not found");
        require(validation.status == ValidationStatus.PENDING || 
                validation.status == ValidationStatus.IN_PROGRESS, "Validation not active");
        require(hopIndex < validation.hopPath.length, "Invalid hop index");
        require(validation.hopPath[hopIndex] == msg.sender, "Unauthorized hop node");
        require(validation.hopProofs[hopIndex] == bytes32(0), "Hop already completed");

        // Check timeout
        if (block.timestamp > validation.startTime + (networkConfig.hopTimeoutMs * networkConfig.maxHops / 1000)) {
            validation.status = ValidationStatus.TIMEOUT;
            emit ValidationCompleted(transactionId, false, block.timestamp - validation.startTime);
            return;
        }

        // Record hop completion
        validation.hopTimestamps[hopIndex] = block.timestamp;
        validation.hopProofs[hopIndex] = proof;
        validation.status = ValidationStatus.IN_PROGRESS;

        emit HopCompleted(transactionId, msg.sender, hopIndex, proof);

        // Check if all hops completed
        bool allCompleted = true;
        for (uint256 i = 0; i < validation.hopPath.length; i++) {
            if (validation.hopProofs[i] == bytes32(0)) {
                allCompleted = false;
                break;
            }
        }

        if (allCompleted) {
            validation.status = ValidationStatus.COMPLETED;
            uint256 totalTime = block.timestamp - validation.startTime;

            // Distribute rewards to hop nodes
            _distributeHopRewards(transactionId, totalTime);

            emit ValidationCompleted(transactionId, true, totalTime);
        }
    }

    /**
     * @dev Get network health metrics
     */
    function getNetworkHealth() external view returns (
        uint256 activeNodeCount,
        uint256 avgSuccessRate,
        uint256 avgLatency,
        uint256 totalValidations,
        uint256 emergencyModeStatus
    ) {
        activeNodeCount = activeNodes.length;

        uint256 totalSuccessRate = 0;
        uint256 totalLatency = 0;
        uint256 activeCount = 0;

        for (uint256 i = 0; i < activeNodes.length; i++) {
            if (nodes[activeNodes[i]].isActive) {
                totalSuccessRate += nodes[activeNodes[i]].successRate;
                totalLatency += nodes[activeNodes[i]].avgLatency;
                activeCount++;
            }
        }

        avgSuccessRate = activeCount > 0 ? totalSuccessRate / activeCount : 0;
        avgLatency = activeCount > 0 ? totalLatency / activeCount : 0;
        totalValidations = pendingValidations.length;
        emergencyModeStatus = networkConfig.emergencyMode ? 1 : 0;
    }

    /**
     * @dev Get node performance metrics
     */
    function getNodeMetrics(address node) external view returns (
        uint256 successRate,
        uint256 avgLatency,
        uint256 reputationScore,
        uint256 totalRouted,
        bool isActive
    ) {
        NetworkNode storage nodeInfo = nodes[node];
        return (
            nodeInfo.successRate,
            nodeInfo.avgLatency,
            nodeInfo.reputationScore,
            nodeInfo.totalRouted,
            nodeInfo.isActive
        );
    }

    /**
     * @dev Internal function to generate random hop path (stake-neutral)
     */
    function _generateHopPath(uint256 hopCount) internal view returns (address[] memory) {
        require(activeNodes.length >= hopCount, "Insufficient nodes for hop path");

        address[] memory hopPath = new address[](hopCount);
        bool[] memory selected = new bool[](activeNodes.length);

        // Use block-based randomness for stake-neutral selection
        // Note: In production, this should use VRF or similar secure randomness
        uint256 randomSeed = uint256(keccak256(abi.encodePacked(
            block.timestamp,
            block.prevrandao,
            msg.sender
        )));

        for (uint256 i = 0; i < hopCount; i++) {
            uint256 attempts = 0;
            uint256 nodeIndex;

            do {
                nodeIndex = (randomSeed + i + attempts) % activeNodes.length;
                attempts++;

                // Prevent infinite loops
                if (attempts > activeNodes.length * 2) {
                    break;
                }
            } while (selected[nodeIndex] || !nodes[activeNodes[nodeIndex]].isActive);

            selected[nodeIndex] = true;
            hopPath[i] = activeNodes[nodeIndex];
        }

        return hopPath;
    }

    /**
     * @dev Assign node to least loaded shard
     */
    function _assignNodeToShard(address node) internal {
        uint256 minLoad = type(uint256).max;
        uint256 targetShardId = 0;

        // Find shard with minimum load
        for (uint256 i = 0; i < activeShardCount; i++) {
            if (shards[i].isActive && shards[i].loadFactor < minLoad) {
                minLoad = shards[i].loadFactor;
                targetShardId = i;
            }
        }

        shards[targetShardId].assignedNodes.push(node);
    }

    /**
     * @dev Distribute rewards to hop nodes based on performance
     */
    function _distributeHopRewards(bytes32 transactionId, uint256 totalTime) internal {
        HopValidation storage validation = validations[transactionId];

        // Calculate base reward per hop
        uint256 baseReward = (msg.value * hostRewardPercentage) / (validation.hopPath.length * 1000);

        for (uint256 i = 0; i < validation.hopPath.length; i++) {
            address hopNode = validation.hopPath[i];
            NetworkNode storage node = nodes[hopNode];

            // Calculate performance bonus
            uint256 hopLatency = i > 0 ? 
                validation.hopTimestamps[i] - validation.hopTimestamps[i-1] :
                validation.hopTimestamps[i] - validation.startTime;

            uint256 performanceMultiplier = _calculatePerformanceMultiplier(
                node.successRate,
                hopLatency,
                node.avgLatency
            );

            uint256 reward = (baseReward * performanceMultiplier) / 1000;

            // Add cross-chain bonus if applicable
            if (validation.originChain != validation.targetChain) {
                reward += (baseReward * crossChainBonusRate) / 10000;
            }

            // Update node metrics
            node.totalRouted++;
            node.lastActivity = block.timestamp;

            // Send reward (in production, this would interact with token contract)
            payable(hopNode).transfer(reward);

            emit RewardDistributed(hopNode, reward, "Hop validation reward");
        }
    }

    /**
     * @dev Calculate performance multiplier based on node metrics
     */
    function _calculatePerformanceMultiplier(
        uint256 successRate,
        uint256 actualLatency,
        uint256 avgLatency
    ) internal view returns (uint256) {
        // Base multiplier (1000 = 1x)
        uint256 multiplier = 1000;

        // Success rate bonus (up to 2x for perfect success rate)
        multiplier = (multiplier * successRate) / 1000;

        // Latency bonus (better latency = higher multiplier)
        if (actualLatency < avgLatency) {
            uint256 latencyBonus = ((avgLatency - actualLatency) * 1000) / avgLatency;
            multiplier += latencyBonus / 2; // 50% of latency improvement as bonus
        }

        // Cap at maximum bonus
        if (multiplier > performanceBonusMultiplier) {
            multiplier = performanceBonusMultiplier;
        }

        return multiplier;
    }

    /**
     * @dev Emergency functions (owner only)
     */
    function activateEmergencyMode(string calldata reason) external onlyOwner {
        networkConfig.emergencyMode = true;
        _pause();
        emit EmergencyModeActivated(reason);
    }

    function deactivateEmergencyMode() external onlyOwner {
        networkConfig.emergencyMode = false;
        _unpause();
    }

    function updateNetworkConfig(NetworkConfig calldata newConfig) external onlyOwner {
        networkConfig = newConfig;
    }

    /**
     * @dev Receive function to accept payments for transaction fees
     */
    receive() external payable {
        // Fees received for transaction validation
    }
}

